window.WORD_MEMORY_HOOKS=[null,{"kind":"词根场景","text":"past-/pasc- 表示“喂养”（和 pastor 牧人同族）：让牲畜吃草的地方 → pasture（牧场）。","basis":"manual"},{"kind":"词源人物","text":"hygie- 来自希腊健康女神 Hygieia（许癸厄亚）；她掌管健康与清洁，所以 hygiene 就是“卫生、保健”。拼写钉住 hy-gie-ne。","basis":"manual"},{"kind":"词义沿革","text":"dumb 最早只表示“哑的、不能说话”，后来才发展出“笨的”。结尾 b 不发音：看到沉默的 b，就先想“哑”，再连到“笨”。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 fluctuate 定义为“cause to fluctuate or move in a wavelike pattern”。先抓定义中的 wavelike，再落到中文核心“围绕某个水平上下波动”；词形用外框 flu…ate 定位。","basis":"definition"},{"kind":"词义沿革","text":"nuisance 在古法语里原指“伤害、损害”，词义后来减弱为“造成烦扰的人或事” → 麻烦、讨厌的东西。","basis":"manual"},{"kind":"拟声钩子","text":"crow 本来就是模仿乌鸦叫声的词：乌鸦一边 cro(w)-cro(w) 地叫，一边就是 a crow；名词“乌鸦”和动词“啼叫”一起记。","basis":"manual"},{"kind":"拟声钩子","text":"slam 的短促重音模仿门“砰”地合上；听到这一声就联到“猛关、猛击”，而不是安静地 close。","basis":"manual"},{"kind":"同族词","text":"poultry 与 pullet（小母鸡）同族；从一只小鸡扩展到家养鸡鸭等整体 → 家禽。中间固定写 -ultr-，不是 poetry。","basis":"manual"},{"kind":"词义沿革","text":"carpenter 的拉丁祖先 carpentarius 原是“造车的人”；木车由木匠打造，于是职业义固定为“木匠”。","basis":"manual"},{"kind":"词根链","text":"muni- 指公共职责、公共服务，-al 表示“……的”：与城市公共事务有关的 → municipal（市政的）。","basis":"manual"},{"kind":"动作画面","text":"slope 与 slip/slide 的“向下滑”画面相近：地面让东西顺势滑下去，说明它有坡度 → slope（斜坡、倾斜）。","basis":"manual"},{"kind":"真实语境","text":"在真实句“propagate these characteristics”里，propagate 是正在发生的动作；把动作画面直接标成“传播”。以后先演动作，再叫出这个词；词形用外框 pro…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"duplicate 是“复制”，delicate 是“易受损的”；把差异位 up ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：cabin = “small room on a ship or boat where people sleep”。辨识时先提取关键词 people，确认核心义“小木屋”；回忆时保留完整短词形 cabin。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a musical organization consisting of a group of instrumentalists including string players”反向定位 orchestra：线索词 instrumentalists 指向“管弦乐队”。说出中文后再完整看一遍词形；词形用外框 orc…tra 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 crane 定义为“stretch (the neck) so as to see better”。先抓定义中的 stretch，再落到中文核心“伸长看”；回忆时保留完整短词形 crane。","basis":"definition"},{"kind":"形近对照","text":"barn 是“谷仓”，bark 是“吠叫”；把差异位 n ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：bulletin = “a brief report (especially an official statement issued for immediate publication or broadcast)”。辨识时先提取关键词 publication，确认核心义“公告”；词形再钉住双写 ll。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“The performance is likely to intrigue Sue”。intrigue 在这里推动句子发生，核心动作是“激起…的兴趣”；词形用外框 int…gue 定位。","basis":"usage"},{"kind":"真实语境","text":"在真实句“They drain the water”里，drain 是正在发生的动作；把动作画面直接标成“排水”。以后先演动作，再叫出这个词；回忆时保留完整短词形 drain。","basis":"usage"},{"kind":"释义锚点","text":"attorney 暂无合适的例句，不编故事。用可核验定义“a professional person authorized to practice law; conducts lawsuits or gives legal advice”做锚点，把 professional 与“律师”成对回忆；词形再钉住双写 tt。","basis":"definition"},{"kind":"形近对照","text":"coward 是“懦夫”，cord 是“粗线”；把差异位 wa ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“latent talent”校准词义：latent 不是孤立标签，而是在说明“潜在的”的状态；回忆时保留完整短词形 latent。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 merchant 定义为“a businessperson engaged in retail trade”。先抓定义中的 businessperson，再落到中文核心“商人”；词形用外框 mer…ant 定位。","basis":"definition"},{"kind":"真实语境","text":"把 foam 固定在真实用法“the beer had a thick head of foam”里：它在句中指向“海绵橡胶”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 foam。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：tribe = “a social division of (usually preliterate) people”。辨识时先提取关键词 preliterate，确认核心义“部落”；回忆时保留完整短词形 tribe。","basis":"definition"},{"kind":"形近对照","text":"torment 是“痛苦”，torrent 是“急流”；把差异位 m ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“Sam cannot plague Sue”给 plague 留的是名词位；把这个位置换成“瘟疫”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 plague。","basis":"usage"},{"kind":"形近对照","text":"intimate 是“亲密的”，intricate 是“错综复杂的”；把差异位 im ↔ ric 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“a solemn promise”里圈出被修饰对象，再把 solemn 写成中文侧注“严肃的”。对象＋特征一起记；词形再钉住辨识块 mn。","basis":"usage"},{"kind":"场景联想","text":"gadget 就是小而巧的工具；想象口袋里一件带按钮的小装置，按一下便完成任务 → 小器具。此条是场景钩子。","basis":"manual"},{"kind":"形近对照","text":"herd 是“兽群”，herb 是“药草”；把差异位 d ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 batch 固定在真实用法“a batch of letters”里：它在句中指向“一批”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 tch。","basis":"usage"},{"kind":"拼写钩子","text":"bizarre 本身拼写就反常：中间双 r、结尾 -arre 都不按常见节奏。把这副“怪拼写”直接绑定到“奇异的、古怪的”。","basis":"manual"},{"kind":"词根链","text":"dec- 在这里来自“合适、相称”，-ent 表性质：举止合宜、达到体面标准 → decent（得体的、不错的）。","basis":"manual"},{"kind":"同形双线","text":"形容词 tender 来自“柔软、娇嫩”；动词/名词 tender 则可表示正式提出。先用“嫩”锁住最常考核心义，再按词性分线。","basis":"manual"},{"kind":"真实语境","text":"把 exquisite 记成“an exquisite cameo”里的属性标签：它说明对象“精美的”。看到相同描述位就触发这个词；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"词根链","text":"cata-（向下、彻底）+ strophe（转折、翻转）：局势彻底翻转、崩塌 → catastrophe（大灾难）。","basis":"manual"},{"kind":"形近对照","text":"cord 是“粗线”，corn 是“谷物”；把差异位 d ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"audi-（听）+ -orium（场所）：坐下来听演讲、音乐的地方 → auditorium（礼堂）。","basis":"manual"},{"kind":"释义锚点","text":"doctrine 暂无合适的例句，不编故事。用可核验定义“a belief (or system of beliefs) accepted as authoritative by some group or school”做锚点，把 authoritative 与“教义”成对回忆；词形用外框 doc…ine 定位。","basis":"definition"},{"kind":"形近对照","text":"rag 是破布，rug 是小地毯：a 像破布上的洞，u 像铺在地上的弧面；只用这一个元音区分。","basis":"manual"},{"kind":"真实语境","text":"记一帧动作证据：“They want to slaughter the prisoners”。slaughter 在这里推动句子发生，核心动作是“屠宰”；词形再钉住辨识块 augh。","basis":"usage"},{"kind":"词根链","text":"ten-/tain- 表示“握住、持有”；持有并使用一处房产的人 → tenant（房客、承租人）。","basis":"manual"},{"kind":"词根场景","text":"ven- 表示“来”（compare convene：共同来到）：大家来到并聚集的地点 → venue（场所、会场）。","basis":"manual"},{"kind":"真实语境","text":"不要硬编词根：在“it was a limited realm of discourse”中直接圈出 realm，旁注“领域”。句位、场景和词形三者一起回放；回忆时保留完整短词形 realm。","basis":"usage"},{"kind":"形近对照","text":"stroke 是“中风”，stride 是“大步走”；把差异位 ok ↔ id 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“Wrap the present”里，wrap 是正在发生的动作；把动作画面直接标成“包”。以后先演动作，再叫出这个词；词形再钉住辨识块 wr。","basis":"usage"},{"kind":"词根链","text":"com-（共同）+ pati（承受，和 compassion 同族）+ -able（能够）：能够共同承受、彼此容纳 → 兼容的。","basis":"manual"},{"kind":"词根链","text":"juven-（年轻、青年）+ -ile（……的）：年轻人的、未成年的 → juvenile。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“Sam cannot menace Sue”做记忆证据：其中 menace 承担名词成分，核心就是“威胁”。闭眼复述句意后再看词；回忆时保留完整短词形 menace。","basis":"usage"},{"kind":"形近对照","text":"pant 是“气喘”，pact 是“协定”；把差异位 n ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词义沿革","text":"salut- 原指健康、安全（与 salvation 同族）；见面先祝对方安康，动作便发展为 salute（致敬、敬礼）。","basis":"manual"},{"kind":"形近对照","text":"refrain 是“克制”，restrain 是“抑制”；把差异位 f ↔ st 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"recipe 是“食谱”，recite 是“背诵”；把差异位 p ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"burglar 是“窃贼”，burger 是“汉堡包”；把差异位 la ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"portray 是“描绘”，portrait 是“肖像”；把差异位 y ↔ it 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"famine 是“饥荒”，faint 是“微弱的”；把差异位 mine ↔ int 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“sour-tasting liquid produced usually by oxidation of the alcohol in wine or cider and used as a condiment or food preservative”反向定位 vinegar：线索词 sour-tasting 指向“醋”。说出中文后再完整看一遍词形；回忆时保留完整短词形 vinegar。","basis":"definition"},{"kind":"真实语境","text":"真实句“Sam and Sue drone”给 drone 留的是名词位；把这个位置换成“无人机”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 drone。","basis":"usage"},{"kind":"词根场景","text":"agon- 原指竞赛、搏斗；人在激烈挣扎中承受的状态 → agony（极度痛苦）。","basis":"manual"},{"kind":"形近对照","text":"grind 是“磨碎”，grin 是“咧嘴笑”；把差异位 d ↔ grin 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tangle 是“缠结的一团”，tongue 是“舌头”；把差异位 angl ↔ ongu 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源＋形近","text":"古英语 stice 原指“刺、扎”；它与 stick 的“尖物刺入”同源。针每刺一下留下一个 stitch（针脚），同时盯住结尾 -tch，别写成 stick。","basis":"manual"},{"kind":"释义锚点","text":"contaminate 暂无合适的例句，不编故事。用可核验定义“make impure”做锚点，把 impure 与“弄脏”成对回忆；词形用外框 con…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：petroleum = “a dark oil consisting mainly of hydrocarbons”。辨识时先提取关键词 hydrocarbons，确认核心义“石油”；词形用外框 pet…eum 定位。","basis":"definition"},{"kind":"词义沿革","text":"scandal 的希腊词源本指“陷阱、绊脚石”；让人栽跟头并招来非议的事 → 丑闻。","basis":"manual"},{"kind":"词源故事","text":"tragedy 的希腊构词原意是“山羊之歌”（trag- 山羊 + ode 歌），后来专指悲剧表演；用这个独有故事锁定“悲剧”。","basis":"manual"},{"kind":"形近对照","text":"parasite 是“寄生虫”，paradise 是“天堂”；把差异位 sit ↔ dis 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“Sam cannot scorn Sue”比拆假词根可靠：定位其中的动词 scorn，用“轻蔑”复述整句；回忆时保留完整短词形 scorn。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“The squatters had to surrender the building after the police moved in”。surrender 在这里推动句子发生，核心动作是“投降”；词形再钉住双写 rr。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 meadow 定义为“a piece of land covered or mostly covered with grass; a field where grass or alfalfa are grown to be made into hay”。先抓定义中的 covered，再落到中文核心“草地”；回忆时保留完整短词形 meadow。","basis":"definition"},{"kind":"释义锚点","text":"prevalent 暂无合适的例句，不编故事。用可核验定义“most frequent or common”做锚点，把 frequent 与“在一定范围内广泛存在”成对回忆；词形用外框 pre…ent 定位。","basis":"definition"},{"kind":"形近对照","text":"coarse 是“粗糙的”，clause 是“从句”；把差异位 oar ↔ lau 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根画面","text":"tort- 表“扭曲”（见 distort）：把人的身体和意志强行扭曲 → torture（拷问、折磨）。","basis":"manual"},{"kind":"形近对照","text":"carpet 是“地毯”，carve 是“雕刻”；把差异位 pet ↔ ve 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"cellar 暂无合适的例句，不编故事。用可核验定义“the lowermost portion of a structure partly or wholly below ground level; often used for storage”做锚点，把 lowermost 与“地窖”成对回忆；词形再钉住双写 ll。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：booth = “a table (in a restaurant or bar) surrounded by two high-backed benches”。辨识时先提取关键词 high-backed，确认核心义“小隔间”；词形再钉住双写 oo。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a distinctive odor that is pleasant”反向定位 perfume：线索词 distinctive 指向“香味”。说出中文后再完整看一遍词形；回忆时保留完整短词形 perfume。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 mosaic 定义为“art consisting of a design made of small pieces of colored stone or glass”。先抓定义中的 consisting，再落到中文核心“马赛克”；回忆时保留完整短词形 mosaic。","basis":"definition"},{"kind":"形近对照","text":"disguise 是“伪装”，disgust 是“反感”；把差异位 ise ↔ st 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：malignant = “dangerous to health; characterized by progressive and uncontrolled growth (especially of a tumor)”。辨识时先提取关键词 uncontrolled，确认核心义“恶毒的”；词形用外框 mal…ant 定位。","basis":"definition"},{"kind":"形近对照","text":"sponge 是“海绵”，spine 是“脊柱”；把差异位 ong ↔ in 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“tremendous sweeping plains”中，tremendous 正在给对象贴上“极好的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 tre…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"grease 是“油脂”，grape 是“葡萄”；把差异位 eas ↔ ap 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"re-（反向、回转）+ volt/volv（转）：从原有统治方向转过去 → revolt（反抗、反叛）。","basis":"manual"},{"kind":"形近对照","text":"leap 是“跳跃”，lean 是“倾斜身体”；把差异位 p ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tribute 是“致敬”，tribe 是“部落”；把差异位 ut ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"kettle 暂无合适的例句，不编故事。用可核验定义“a metal pot for stewing or boiling; usually has a lid”做锚点，把 stewing 与“水壶”成对回忆；词形再钉住双写 tt。","basis":"definition"},{"kind":"形近对照","text":"raid 是“突袭”，rid 是“使摆脱”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"interim 是“过渡期”，inherit 是“继承”；把差异位 terim ↔ herit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 physiology 定义为“the branch of the biological sciences dealing with the functioning of organisms”。先抓定义中的 functioning，再落到中文核心“生理”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"真实语境","text":"把 alienate 放回“The performance is likely to alienate Sue”：句中主语做的正是“使疏远”。先抓施事者与动作，再提取词形；词形用外框 ali…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"pirate 是“海盗”，parade 是“游行”；把差异位 irat ↔ arad 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"crab 是“螃蟹”，cab 是“出租车”；把差异位 r ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 pottery 定义为“ceramic ware made from clay and baked in a kiln”。先抓定义中的 ceramic，再落到中文核心“陶器”；词形再钉住双写 tt。","basis":"definition"},{"kind":"真实语境","text":"把 salient 记成“salient traits”里的属性标签：它说明对象“显著的”。看到相同描述位就触发这个词；回忆时保留完整短词形 salient。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“those rights and obligations are based on an unstated consensus”中直接圈出 consensus，旁注“一致的意见”。句位、场景和词形三者一起回放；词形用外框 con…sus 定位。","basis":"usage"},{"kind":"形近对照","text":"dean 是“院长”，deaf 是“聋的”；把差异位 n ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 eloquent 定义为“expressing yourself readily, clearly, effectively”。先抓定义中的 effectively，再落到中文核心“有说服力的”；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"释义锚点","text":"crust 暂无合适的例句，不编故事。用可核验定义“the outer layer of the Earth”做锚点，把 outer 与“面包皮”成对回忆；回忆时保留完整短词形 crust。","basis":"definition"},{"kind":"形近对照","text":"sneeze 是“打喷嚏”，squeeze 是“挤压”；把差异位 n ↔ qu 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"patrol 是“巡逻”，patron 是“赞助人”；把差异位 l ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"divine 是“神的”，devise 是“设计”；把差异位 ivin ↔ evis 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"pilgrim 暂无合适的例句，不编故事。用可核验定义“someone who journeys in foreign lands”做锚点，把 journeys 与“朝圣者”成对回忆；回忆时保留完整短词形 pilgrim。","basis":"definition"},{"kind":"动作分线","text":"lumber 作名词是木材；沉重木料搬动时步伐笨重，所以动词可指缓慢、笨重地移动。用木料重量统一两义。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a basis for comparison; a reference point against which other things can be evaluated”反向定位 criterion：线索词 comparison 指向“标准”。说出中文后再完整看一遍词形；词形用外框 cri…ion 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 scrutiny 定义为“the act of examining something closely (as for mistakes)”。先抓定义中的 examining，再落到中文核心“严格而仔细地审查”；词形用外框 scr…iny 定位。","basis":"definition"},{"kind":"真实语境","text":"把 plight 固定在真实用法“the woeful plight of homeless people”里：它在句中指向“困境”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 ght。","basis":"usage"},{"kind":"词根场景","text":"culmin- 指顶点、最高处：事情一路上升到顶点并在那里结束 → culminate（达到高潮、以……告终）。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“an ingenious solution to the problem”校准词义：ingenious 不是孤立标签，而是在说明“心灵手巧的”的状态；词形用外框 ing…ous 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 nursery 定义为“a child's room for a baby”。先抓定义中的 child，再落到中文核心“托儿所”；回忆时保留完整短词形 nursery。","basis":"definition"},{"kind":"词根场景","text":"cord-/cor- 表“心”（见 cardiac）：发自内心地热情友好 → cordial（热情友好的、诚恳的）。","basis":"manual"},{"kind":"形近对照","text":"toil 是“苦工”，tail 是“尾巴”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he behaved with great dignity”做记忆证据：其中 dignity 承担名词成分，核心就是“尊严”。闭眼复述句意后再看词；回忆时保留完整短词形 dignity。","basis":"usage"},{"kind":"真实语境","text":"真实句“a prosperous family”中，prosperous 正在给对象贴上“兴旺的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 pro…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"intricate 是“错综复杂的”，intimate 是“亲密的”；把差异位 ric ↔ im 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：porch = “a structure attached to the exterior of a building often forming a covered entrance”。辨识时先提取关键词 structure，确认核心义“门廊”；回忆时保留完整短词形 porch。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a toothed wheel that engages another toothed mechanism in order to change the speed or direction of transmitted motion”反向定位 gear：线索词 transmitted 指向“齿轮”。说出中文后再完整看一遍词形；回忆时保留完整短词形 gear。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 majesty 定义为“impressiveness in scale or proportion”。先抓定义中的 impressiveness，再落到中文核心“雄伟壮观”；回忆时保留完整短词形 majesty。","basis":"definition"},{"kind":"释义锚点","text":"flock 暂无合适的例句，不编故事。用可核验定义“a church congregation guided by a pastor”做锚点，把 congregation 与“群”成对回忆；回忆时保留完整短词形 flock。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：eradicate = “kill in large numbers”。辨识时先提取关键词 numbers，确认核心义“根除”；词形用外框 era…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a periodic count of the population”反向定位 census：线索词 population 指向“人口普查”。说出中文后再完整看一遍词形；回忆时保留完整短词形 census。","basis":"definition"},{"kind":"形近对照","text":"stoop 是“弯腰”，stool 是“凳子”；把差异位 p ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 corrupt 记成“a corrupt text”里的属性标签：它说明对象“腐败的”。看到相同描述位就触发这个词；词形再钉住双写 rr。","basis":"usage"},{"kind":"真实语境","text":"真实用法“gauge bricks”比拆假词根可靠：定位其中的动词 gauge，用“判断”复述整句；回忆时保留完整短词形 gauge。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a distinctive odor that is pleasant”反向定位 scent：线索词 distinctive 指向“气味”。说出中文后再完整看一遍词形；回忆时保留完整短词形 scent。","basis":"definition"},{"kind":"真实语境","text":"真实句“his sophomore year”给 sophomore 留的是名词位；把这个位置换成“二年级学生”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 ph。","basis":"usage"},{"kind":"形近对照","text":"crown 是“王冠”，crow 是“乌鸦”；把差异位 n ↔ crow 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“abrupt prose”里圈出被修饰对象，再把 abrupt 写成中文侧注“突然的”。对象＋特征一起记；回忆时保留完整短词形 abrupt。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“someone who attacks in search of booty”反向定位 predator：线索词 someone 指向“捕食者”。说出中文后再完整看一遍词形；词形用外框 pre…tor 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 thigh 定义为“the part of the leg between the hip and the knee”。先抓定义中的 part，再落到中文核心“大腿”；回忆时保留完整短词形 thigh。","basis":"definition"},{"kind":"真实语境","text":"把 scenario 固定在真实用法“the scenario is France during the Reign of Terror”里：它在句中指向“设想”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 sce…rio 定位。","basis":"usage"},{"kind":"同族词","text":"rigorous 先认出 rigor（严格、严密）+ -ous（具有……性质的）：按严格标准执行 → 严谨的。","basis":"manual"},{"kind":"声音画面","text":"stun 的短音像突然“咚”一下让人停住；把“受重击后一时动不了”的画面绑定到“使震惊、使昏迷”。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 permeate 定义为“spread or diffuse through”。先抓定义中的 diffuse，再落到中文核心“扩散”；词形用外框 per…ate 定位。","basis":"definition"},{"kind":"真实语境","text":"把 fraud 固定在真实用法“that book is a fraud”里：它在句中指向“欺诈罪”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 fraud。","basis":"usage"},{"kind":"真实语境","text":"真实用法“ditch a lover”比拆假词根可靠：定位其中的动词 ditch，用“抛弃”复述整句；词形再钉住辨识块 tch。","basis":"usage"},{"kind":"形近对照","text":"stove 是“炉子”，shove 是“猛推”；把差异位 t ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"prophet 是“预言者”，propel 是“推动”；把差异位 het ↔ el 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 inventory 固定在真实用法“they carried a vast inventory of hardware”里：它在句中指向“库存”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 inv…ory 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：artery = “a blood vessel that carries blood from the heart to the body”。辨识时先提取关键词 carries，确认核心义“动脉”；回忆时保留完整短词形 artery。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a tract of land used for burials”反向定位 cemetery：线索词 burials 指向“墓地”。说出中文后再完整看一遍词形；词形用外框 cem…ery 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 appraisal 定义为“the classification of someone or something with respect to its worth”。先抓定义中的 classification，再落到中文核心“估计”；词形再钉住双写 pp。","basis":"definition"},{"kind":"释义锚点","text":"denounce 暂无合适的例句，不编故事。用可核验定义“speak out against”做锚点，把 speak 与“谴责”成对回忆；词形用外框 den…nce 定位。","basis":"definition"},{"kind":"真实语境","text":"真实用法“Smash a plate”比拆假词根可靠：定位其中的动词 smash，用“打碎”复述整句；回忆时保留完整短词形 smash。","basis":"usage"},{"kind":"构词链","text":"en-（使进入）+ visage（脸、面貌）：让一个面貌进入脑海、看见尚未发生的画面 → 想象、设想。","basis":"manual"},{"kind":"词根链","text":"ec-（向外）+ centr（中心）+ -ic（……的）：偏离中心 → 不合常规 → 古怪的。","basis":"manual"},{"kind":"释义锚点","text":"turmoil 暂无合适的例句，不编故事。用可核验定义“a violent disturbance”做锚点，把 disturbance 与“混乱”成对回忆；回忆时保留完整短词形 turmoil。","basis":"definition"},{"kind":"词源＋口令","text":"dare 来自表示“勇敢面对危险”的古老词根。把它当一句短促口令：DARE?（敢不敢？）→ 挑战、激将。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a structure from which an artificially produced jet of water arises”反向定位 fountain：线索词 artificially 指向“喷泉”。说出中文后再完整看一遍词形；词形用外框 fou…ain 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“a strenuous task”中，strenuous 正在给对象贴上“费力的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 str…ous 定位。","basis":"usage"},{"kind":"真实语境","text":"把 funeral 固定在真实用法“hundreds of people attended his funeral”里：它在句中指向“葬礼”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 funeral。","basis":"usage"},{"kind":"真实语境","text":"在“as sober as a judge”里圈出被修饰对象，再把 sober 写成中文侧注“清醒的”。对象＋特征一起记；回忆时保留完整短词形 sober。","basis":"usage"},{"kind":"形近对照","text":"depict 是“描绘”，defect 是“缺点”；把差异位 pi ↔ fe 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 mob 定义为“a disorderly crowd of people”。先抓定义中的 disorderly，再落到中文核心“暴民”；回忆时保留完整短词形 mob。","basis":"definition"},{"kind":"词源链","text":"acquaint 与 cognition/know 的“认识”概念相连：使某人进入知道的状态 → 使熟悉、使了解。拼写钉住 acqu-。","basis":"manual"},{"kind":"真实语境","text":"不要硬编词根：在“they explored every avenue they could think of”中直接圈出 avenue，旁注“林荫道”。句位、场景和词形三者一起回放；回忆时保留完整短词形 avenue。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“(music) the speed at which a composition is to be played”反向定位 tempo：线索词 composition 指向“速度”。说出中文后再完整看一遍词形；回忆时保留完整短词形 tempo。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 pharmacy 定义为“the art and science of preparing and dispensing drugs and medicines”。先抓定义中的 dispensing，再落到中文核心“药房”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"形近对照","text":"cardinal 是“基本的”，cordial 是“热情友好的”；把差异位 ardin ↔ ordi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"disgust 是“反感”，digest 是“消化”；把差异位 sgu ↔ ge 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"grope 是“搜索”，grape 是“葡萄”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“they checked everyone's badge before letting them in”给 badge 留的是名词位；把这个位置换成“徽章”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 dge。","basis":"usage"},{"kind":"形近对照","text":"lame 是“跛的”，lamb 是“羔羊”；把差异位 e ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：broom = “a cleaning implement for sweeping; bundle of straws or twigs attached to a long handle”。辨识时先提取关键词 implement，确认核心义“扫帚”；词形再钉住双写 oo。","basis":"definition"},{"kind":"形近对照","text":"velvet 是“丝绒”，valve 是“阀门”；把差异位 elvet ↔ alve 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"al-/ad-（使趋向）+ levi（轻，和 levity 同根）+ -ate：把负担变轻 → 减轻、缓和。","basis":"manual"},{"kind":"形近对照","text":"relish 是“享受”，resist 是“抵抗”；把差异位 lish ↔ sist 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“the shabby room struck her as extraordinarily pathetic”里圈出被修饰对象，再把 pathetic 写成中文侧注“可怜的”。对象＋特征一起记；词形用外框 pat…tic 定位。","basis":"usage"},{"kind":"形近对照","text":"tram 是“有轨电车”，tray 是“盘”；把差异位 m ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pitch 是“球场”，patch 是“小块”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 appetite 固定在真实用法“an appetite for life”里：它在句中指向“食欲”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 pp。","basis":"usage"},{"kind":"真实语境","text":"真实用法“He was about to mingle in an unpleasant affair”比拆假词根可靠：定位其中的动词 mingle，用“使混合”复述整句；回忆时保留完整短词形 mingle。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“the fabric in the curtains was light and semitransparent”做记忆证据：其中 fabric 承担名词成分，核心就是“织物”。闭眼复述句意后再看词；回忆时保留完整短词形 fabric。","basis":"usage"},{"kind":"真实语境","text":"真实句“numb with cold”中，numb 正在给对象贴上“失去知觉的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 numb。","basis":"usage"},{"kind":"形近对照","text":"stagnate 是“停滞”，stagnant 是“不流动的”；把差异位 te ↔ nt 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"enquiry 是“询问”，equity 是“资产净值”；把差异位 nquir ↔ quit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根＋哑音","text":"pneumon- 表示“肺”；开头 p 不发音，像病肺吸不出这一声。pneumonia 就是肺部疾病 → 肺炎。","basis":"manual"},{"kind":"真实语境","text":"真实句“a fabulous vacation”中，fabulous 正在给对象贴上“绝妙的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 fab…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"delegate 是“选派”，delicate 是“易受损的”；把差异位 eg ↔ ic 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"trim 是“修剪”，tram 是“有轨电车”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“enforced isolation of patients suffering from a contagious disease in order to prevent the spread of disease”反向定位 quarantine：线索词 contagious 指向“隔离期”。说出中文后再完整看一遍词形；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"形近对照","text":"snatch 是“一把抓起”，sketch 是“草图”；把差异位 na ↔ ke 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"canteen 暂无合适的例句，不编故事。用可核验定义“a flask for carrying water; used by soldiers or travelers”做锚点，把 travelers 与“食堂”成对回忆；词形再钉住双写 ee。","basis":"definition"},{"kind":"真实语境","text":"真实用法“Sam cannot dread Sue”比拆假词根可靠：定位其中的动词 dread，用“恐惧”复述整句；回忆时保留完整短词形 dread。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“there was too much anger and disturbance”做记忆证据：其中 disturbance 承担名词成分，核心就是“干扰”。闭眼复述句意后再看词；词形用外框 dis…nce 定位。","basis":"usage"},{"kind":"形近对照","text":"cannon 是“大炮”，carbon 是“碳”；把差异位 nn ↔ rb 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"albeit 是“尽管”，alert 是“机敏的”；把差异位 bei ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"同族词","text":"dorm 是 dormitory 的短形，dorm-/dormit- 表“睡”：供人睡觉居住的地方 → 宿舍。","basis":"manual"},{"kind":"形近对照","text":"preposition 是“介词”，proposition 是“提议”；把差异位 e ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tug 是“拉”，tub 是“浴缸”；把差异位 g ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dove 是“鸽子”，dive 是“潜水”；把差异位 o ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"herald 是“是…的前兆”，heal 是“治愈”；把差异位 rald ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a person who is entitled by law or by the terms of a will to inherit the estate of another”反向定位 heir：线索词 entitled 指向“继承人”。说出中文后再完整看一遍词形；回忆时保留完整短词形 heir。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 hypocrisy 定义为“an expression of agreement that is not supported by real conviction”。先抓定义中的 expression，再落到中文核心“伪善”；词形用外框 hyp…isy 定位。","basis":"definition"},{"kind":"真实语境","text":"把 debut 固定在真实用法“they looked forward to the debut of their new product line”里：它在句中指向“初次亮相”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 debut。","basis":"usage"},{"kind":"形近对照","text":"riddle 是“谜语”，ridge 是“山脊”；把差异位 dl ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“Sam cannot humiliate Sue”。humiliate 在这里推动句子发生，核心动作是“使蒙羞”；词形用外框 hum…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 hound 定义为“any of several breeds of dog used for hunting typically having large drooping ears”。先抓定义中的 typically，再落到中文核心“猎犬”；回忆时保留完整短词形 hound。","basis":"definition"},{"kind":"真实语境","text":"把 custody 固定在真实用法“the suspect is in custody”里：它在句中指向“监护权”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 custody。","basis":"usage"},{"kind":"形近对照","text":"harbor 是“海港”，horror 是“惊恐”；把差异位 arb ↔ orr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"cabinet 是“橱柜”，cabin 是“小木屋”；把差异位 et ↔ cabin 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作画面","text":"crawl 的 cr- 像身体贴地用力，-awl 拉得很慢；把婴儿四肢着地缓慢前进的完整动作绑定到“爬行”。","basis":"manual"},{"kind":"英美拼写","text":"vapour 就是“蒸汽”，英式保留 -our；美式写 vapor。把飘散的水汽放在中间的 apo 上，重点区分词尾。","basis":"manual"},{"kind":"形近对照","text":"versus 是“与…相比”，verse 是“诗”；把差异位 us ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"graze 是“放牧”，grape 是“葡萄”；把差异位 z ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dive 是“潜水”，dine 是“吃饭”；把差异位 v ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"同族挂钩","text":"resemblance 可与 resemble（看起来像）放在同一词族里对照；保留共同词形，同时把 resemblance 单独落到“相像”。","basis":"family"},{"kind":"真实语境","text":"不要硬编词根：在“The men rifle the area for animals”中直接圈出 rifle，旁注“步枪”。句位、场景和词形三者一起回放；回忆时保留完整短词形 rifle。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a person who has general authority over others”反向定位 lord：线索词 authority 指向“贵族”。说出中文后再完整看一遍词形；回忆时保留完整短词形 lord。","basis":"definition"},{"kind":"形近对照","text":"discrete 是“分离的”，discreet 是“谨慎的”；把差异位 te ↔ et 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"irrespective 暂无合适的例句，不编故事。用可核验定义“in spite of everything; without regard to drawbacks”做锚点，把 everything 与“不顾的”成对回忆；词形再钉住双写 rr。","basis":"definition"},{"kind":"形近对照","text":"spin 是“快速旋转”，span 是“持续时间”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“textile research”做记忆证据：其中 textile 承担名词成分，核心就是“纺织品”。闭眼复述句意后再看词；回忆时保留完整短词形 textile。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 odor 定义为“any property detected by the olfactory system”。先抓定义中的 olfactory，再落到中文核心“气味 - =<英>odour”；回忆时保留完整短词形 odor。","basis":"definition"},{"kind":"释义锚点","text":"lure 暂无合适的例句，不编故事。用可核验定义“qualities that attract by seeming to promise some kind of reward”做锚点，把 qualities 与“诱惑力”成对回忆；回忆时保留完整短词形 lure。","basis":"definition"},{"kind":"形近对照","text":"slum 是“贫民窟”，slam 是“砰地关上”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“a chorus of boos”做记忆证据：其中 chorus 承担名词成分，核心就是“合唱团”。闭眼复述句意后再看词；回忆时保留完整短词形 chorus。","basis":"usage"},{"kind":"真实语境","text":"真实句“metropolitan area”中，metropolitan 正在给对象贴上“大城市的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 met…tan 定位。","basis":"usage"},{"kind":"形近对照","text":"sniff 是“嗅”，stiff 是“僵硬的”；把差异位 n ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“a furious battle”里圈出被修饰对象，再把 furious 写成中文侧注“暴怒的”。对象＋特征一起记；回忆时保留完整短词形 furious。","basis":"usage"},{"kind":"形近对照","text":"clinic 是“诊所”，critic 是“评论家”；把差异位 lin ↔ rit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deceit 是“欺骗”，decent 是“像样的”；把差异位 i ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 bump 放回“They bump”：句中主语做的正是“碰撞”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 bump。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“requests that grew more and more imperative”中直接圈出 imperative，旁注“重要紧急的事”。句位、场景和词形三者一起回放；词形用外框 imp…ive 定位。","basis":"usage"},{"kind":"形近对照","text":"stagnant 是“不流动的”，stagnate 是“停滞”；把差异位 nt ↔ te 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 balcony 定义为“an upper floor projecting from the rear over the main floor in an auditorium”。先抓定义中的 projecting，再落到中文核心“阳台”；回忆时保留完整短词形 balcony。","basis":"definition"},{"kind":"释义锚点","text":"cupboard 暂无合适的例句，不编故事。用可核验定义“a small room (or recess) or cabinet used for storage space”做锚点，把 cabinet 与“橱柜”成对回忆；词形用外框 cup…ard 定位。","basis":"definition"},{"kind":"真实语境","text":"在“an amiable gathering”里圈出被修饰对象，再把 amiable 写成中文侧注“和蔼可亲的”。对象＋特征一起记；回忆时保留完整短词形 amiable。","basis":"usage"},{"kind":"形近对照","text":"bait 是“鱼饵”，bail 是“保释”；把差异位 t ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"coal 是“煤”，coil 是“缠绕”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 reassure 放回“Sam cannot reassure Sue”：句中主语做的正是“使安心”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：napkin = “a small piece of table linen that is used to wipe the mouth and to cover the lap in order to protect clothing”。辨识时先提取关键词 clothing，确认核心义“餐巾”；回忆时保留完整短词形 napkin。","basis":"definition"},{"kind":"形近对照","text":"lump 是“块”，lamp 是“灯”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 metaphor 定义为“a figure of speech in which an expression is used to refer to something that it does not literally denote in order to…”。先抓定义中的 expression，再落到中文核心“隐喻”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"名动统一","text":"hedge 是围住土地的树篱；动词就是“用树篱围住”，再引申为给风险加一道边界 → 防范。","basis":"manual"},{"kind":"形近对照","text":"spine 是“脊柱”，spite 是“恶意”；把差异位 n ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shatter 是“破碎”，scatter 是“撒播”；把差异位 h ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pea 是“豌豆”，peak 是“山峰”；把差异位 pea ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"convene 是“召集”，concede 是“承认”；把差异位 ven ↔ ced 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“urine passes out of the kidney through ureters to the bladder”中直接圈出 kidney，旁注“肾脏”。句位、场景和词形三者一起回放；回忆时保留完整短词形 kidney。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“the wood of trees cut and prepared for use as building material”反向定位 timber：线索词 prepared 指向“木料”。说出中文后再完整看一遍词形；回忆时保留完整短词形 timber。","basis":"definition"},{"kind":"形近对照","text":"recede 是“渐渐远去”，recipe 是“食谱”；把差异位 ed ↔ ip 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 echo 固定在真实用法“his contention contains more than an echo of Rousseau”里：它在句中指向“回音”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 echo。","basis":"usage"},{"kind":"真实语境","text":"在“a reluctant smile”里圈出被修饰对象，再把 reluctant 写成中文侧注“不情愿的”。对象＋特征一起记；词形用外框 rel…ant 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“brutal beatings”校准词义：brutal 不是孤立标签，而是在说明“残忍的”的状态；回忆时保留完整短词形 brutal。","basis":"usage"},{"kind":"真实语境","text":"真实句“his questions covered a lot of territory”给 territory 留的是名词位；把这个位置换成“领土”仍说得通。先复原句中事物，再认词；词形再钉住双写 rr。","basis":"usage"},{"kind":"形近对照","text":"lane 是“小路”，lame 是“跛的”；把差异位 n ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“They will rehearse the duet”比拆假词根可靠：定位其中的动词 rehearse，用“排练”复述整句；词形用外框 reh…rse 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“they collected a urine specimen for urinalysis”做记忆证据：其中 specimen 承担名词成分，核心就是“样本”。闭眼复述句意后再看词；词形用外框 spe…men 定位。","basis":"usage"},{"kind":"形近对照","text":"strife 是“冲突”，stride 是“大步走”；把差异位 f ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 desolate 记成“the desolate surface of the moon”里的属性标签：它说明对象“荒无人烟的”。看到相同描述位就触发这个词；词形用外框 des…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"在“do something rash that he will forever repent”里圈出被修饰对象，再把 rash 写成中文侧注“鲁莽的”。对象＋特征一起记；回忆时保留完整短词形 rash。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“lodge a bullet in the table”。lodge 在这里推动句子发生，核心动作是“正式提出”；词形再钉住辨识块 dge。","basis":"usage"},{"kind":"形近对照","text":"robust 是“强健的”，roast 是“烤”；把差异位 bu ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 rigid 记成“a rigid strip of metal”里的属性标签：它说明对象“死板的”。看到相同描述位就触发这个词；回忆时保留完整短词形 rigid。","basis":"usage"},{"kind":"真实语境","text":"在“sane nuclear policy”里圈出被修饰对象，再把 sane 写成中文侧注“理智的”。对象＋特征一起记；回忆时保留完整短词形 sane。","basis":"usage"},{"kind":"形近对照","text":"dock 是“码头”，deck 是“甲板”；把差异位 o ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 ornament 定义为“something used to beautify”。先抓定义中的 beautify，再落到中文核心“装饰品”；词形用外框 orn…ent 定位。","basis":"definition"},{"kind":"词源核心","text":"genuin- 的历史核心是“天生的、原产的”，不是后来仿造出来的 → genuine（真正的、真品的）。","basis":"manual"},{"kind":"形近对照","text":"herb 是“药草”，herd 是“兽群”；把差异位 b ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sturdy 是“结实的”，storey 是“楼层 - =<美>story”；把差异位 urd ↔ ore 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“The performance is likely to frustrate Sue”里，frustrate 是正在发生的动作；把动作画面直接标成“使沮丧”。以后先演动作，再叫出这个词；词形用外框 fru…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"stroll 是“散步”，stroke 是“中风”；把差异位 ll ↔ ke 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tragic 是“悲惨的”，tropic 是“回归线”；把差异位 ag ↔ op 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he had to overcome his inertia and get back to work”做记忆证据：其中 inertia 承担名词成分，核心就是“懒惰”。闭眼复述句意后再看词；回忆时保留完整短词形 inertia。","basis":"usage"},{"kind":"形近对照","text":"repel 是“击退”，reel 是“卷筒”；把差异位 p ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"descent 是“下降”，decent 是“像样的”；把差异位 s ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“drill for oil”中直接圈出 drill，旁注“钻头”。句位、场景和词形三者一起回放；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"protest 是“抗议”，pretext 是“借口”；把差异位 otes ↔ etex 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“good business depends on having good merchandise”里，merchandise 是正在发生的动作；把动作画面直接标成“推销”。以后先演动作，再叫出这个词；词形用外框 mer…ise 定位。","basis":"usage"},{"kind":"形近对照","text":"concede 是“承认”，conceal 是“隐瞒”；把差异位 de ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"plunge 是“纵身投入”，pledge 是“保证”；把差异位 un ↔ ed 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"clause 是“从句”，coarse 是“粗糙的”；把差异位 lau ↔ oar 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"comrade 是“共患难的朋友”，corrode 是“腐蚀”；把差异位 mra ↔ rro 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"freight 是“运送”，fright 是“惊吓”；把差异位 e ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“The streets swarm with crowds”中直接圈出 swarm，旁注“一大群”。句位、场景和词形三者一起回放；回忆时保留完整短词形 swarm。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“Sam cannot banquet Sue”做记忆证据：其中 banquet 承担名词成分，核心就是“宴会”。闭眼复述句意后再看词；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"形近对照","text":"spade 是“铲子”，shade 是“阴凉处”；把差异位 p ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"lean 是“倾斜身体”，leap 是“跳跃”；把差异位 n ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：pyramid = “a polyhedron having a polygonal base and triangular sides with a common vertex”。辨识时先提取关键词 polyhedron，确认核心义“金字塔”；回忆时保留完整短词形 pyramid。","basis":"definition"},{"kind":"形近对照","text":"analogue 是“模拟的”，analogy 是“类比”；把差异位 ue ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pact 是“协定”，pant 是“气喘”；把差异位 c ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"coalition 暂无合适的例句，不编故事。用可核验定义“an organization of people (or countries) involved in a pact or treaty”做锚点，把 organization 与“联合”成对回忆；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：propaganda = “information that is spread for the purpose of promoting some cause”。辨识时先提取关键词 information，确认核心义“宣传”；词形用外框 pro…nda 定位。","basis":"definition"},{"kind":"形近对照","text":"sore 是“酸痛的”，shore 是“海岸”；把差异位 o ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 shepherd 定义为“a clergyman who watches over a group of people”。先抓定义中的 clergyman，再落到中文核心“牧羊人”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"形近对照","text":"banner 是“横幅”，barber 是“理发师”；把差异位 nn ↔ rb 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：orchard = “garden consisting of a small cultivated wood without undergrowth”。辨识时先提取关键词 undergrowth，确认核心义“果园”；回忆时保留完整短词形 orchard。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a cathedral church”做记忆证据：其中 cathedral 承担名词成分，核心就是“大教堂”。闭眼复述句意后再看词；词形用外框 cat…ral 定位。","basis":"usage"},{"kind":"形近对照","text":"sew 是“缝纫”，saw 是“锯”；把差异位 e ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"steel 是“钢”，steep 是“险峻的”；把差异位 l ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"discard 是“抛弃”，discern 是“察觉出”；把差异位 ard ↔ ern 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tub 是“浴缸”，tug 是“拉”；把差异位 b ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"persecute 是“迫害”，prosecute 是“起诉”；把差异位 er ↔ ro 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"heave 是“举起”，heaven 是“天堂”；把差异位 heave ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"grim 是“严肃的”，grin 是“咧嘴笑”；把差异位 m ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"拼写变体","text":"despatch 是 dispatch 的英式变体，核心都是 dis-（分开送出）+ patch/派送 → 派遣、发送；考试先认 -spatch。","basis":"manual"},{"kind":"真实语境","text":"在真实句“Many people had to emigrate during the Nazi period”里，emigrate 是正在发生的动作；把动作画面直接标成“移居”。以后先演动作，再叫出这个词；词形用外框 emi…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"把 fracture 放回“Did he fracture his foot?”：句中主语做的正是“断裂”。先抓施事者与动作，再提取词形；词形用外框 fra…ure 定位。","basis":"usage"},{"kind":"形近对照","text":"strive 是“努力”，stride 是“大步走”；把差异位 v ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"gut 是“直觉”，gum 是“口香糖”；把差异位 t ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"puppet 是“木偶”，pepper 是“胡椒粉”；把差异位 uppet ↔ epper 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"guild 暂无合适的例句，不编故事。用可核验定义“a formal association of people with similar interests”做锚点，把 association 与“协会”成对回忆；回忆时保留完整短词形 guild。","basis":"definition"},{"kind":"形近对照","text":"marine 是“海洋的”，marble 是“大理石”；把差异位 in ↔ bl 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“any cold-blooded vertebrate of the class Reptilia including tortoises, turtles, snakes, lizards, alligators, crocodiles, and…”反向定位 reptile：线索词 cold-blooded 指向“爬行动物”。说出中文后再完整看一遍词形；回忆时保留完整短词形 reptile。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 wool 定义为“a fabric made from the hair of sheep”。先抓定义中的 fabric，再落到中文核心“绒”；词形再钉住双写 oo。","basis":"definition"},{"kind":"形近对照","text":"stereo 是“立体声”，storey 是“楼层 - =<美>story”；把差异位 ereo ↔ orey 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"absurd 是“荒谬的”，abound 是“大量存在”；把差异位 sur ↔ oun 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“an elastic band”校准词义：elastic 不是孤立标签，而是在说明“有弹性的”的状态；回忆时保留完整短词形 elastic。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 archaeology 定义为“the branch of anthropology that studies prehistoric people and their cultures”。先抓定义中的 anthropology，再落到中文核心“考古学 - =<美>archeology”；词形用外框 arc…ogy 定位。","basis":"definition"},{"kind":"真实语境","text":"把 rubber 固定在真实用法“a rubber check”里：它在句中指向“橡胶”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 bb。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：mammal = “any warm-blooded vertebrate having the skin more or less covered with hair; young are born alive except for the small…”。辨识时先提取关键词 warm-blooded，确认核心义“哺乳动物”；词形再钉住双写 mm。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“breathe with great difficulty, as when experiencing a strong emotion”反向定位 choke：线索词 experiencing 指向“窒息”。说出中文后再完整看一遍词形；回忆时保留完整短词形 choke。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 gasoline 定义为“a volatile flammable mixture of hydrocarbons (hexane and heptane and octane etc.) derived from petroleum; used mainly as a…”。先抓定义中的 hydrocarbons，再落到中文核心“汽油”；词形用外框 gas…ine 定位。","basis":"definition"},{"kind":"真实语境","text":"把 rust 固定在真实用法“These cars won't rust”里：它在句中指向“铁锈”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 rust。","basis":"usage"},{"kind":"形近对照","text":"quiver 是“颤抖”，queer 是“异常的”；把差异位 iv ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sauce 是“酱汁”，saucer 是“茶托”；把差异位 sauce ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“numerous times”中，numerous 正在给对象贴上“众多的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 num…ous 定位。","basis":"usage"},{"kind":"真实语境","text":"把 submerge 放回“submerge your head completely”：句中主语做的正是“淹没”。先抓施事者与动作，再提取词形；词形用外框 sub…rge 定位。","basis":"usage"},{"kind":"真实语境","text":"在“versatile moods”里圈出被修饰对象，再把 versatile 写成中文侧注“多才多艺的”。对象＋特征一起记；词形用外框 ver…ile 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“reckless or malicious behavior that causes discomfort or annoyance in others”反向定位 mischief：线索词 discomfort 指向“恶作剧”。说出中文后再完整看一遍词形；词形用外框 mis…ief 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 wardrobe 定义为“a tall piece of furniture that provides storage space for clothes; has a door and rails or hooks for hanging clothes”。先抓定义中的 furniture，再落到中文核心“衣柜”；词形用外框 war…obe 定位。","basis":"definition"},{"kind":"真实语境","text":"把 volatile 记成“volatile oils”里的属性标签：它说明对象“易变的”。看到相同描述位就触发这个词；词形用外框 vol…ile 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：siege = “the action of an armed force that surrounds a fortified place and isolates it while continuing to attack”。辨识时先提取关键词 continuing，确认核心义“围攻”；回忆时保留完整短词形 siege。","basis":"definition"},{"kind":"形近对照","text":"barren 是“贫瘠的”，barrel 是“桶”；把差异位 n ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"spit 是“吐”，spin 是“快速旋转”；把差异位 t ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pit 是“洞”，pin 是“大头针”；把差异位 t ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shore 是“海岸”，shove 是“猛推”；把差异位 r ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a professional cook”反向定位 chef：线索词 professional 指向“厨师”。说出中文后再完整看一遍词形；回忆时保留完整短词形 chef。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 nitrogen 定义为“a common nonmetallic element that is normally a colorless odorless tasteless inert diatomic gas; constitutes 78 percent of…”。先抓定义中的 nonmetallic，再落到中文核心“氮”；词形用外框 nit…gen 定位。","basis":"definition"},{"kind":"动作转义","text":"bind 是“捆绑”，bound 表示“被约束住”；be bound to do 像被规则绑住只能发生 → 必然、一定。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：friction = “a state of conflict between persons”。辨识时先提取关键词 conflict，确认核心义“摩擦”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"形近对照","text":"deceive 是“欺骗”，deceit 是“欺骗”；把差异位 ve ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"同形双线","text":"pine 作名词是松树；作动词表示长久思念、憔悴。用“独自站着的常青松长久等待”串起松树与渴望。","basis":"manual"},{"kind":"形近对照","text":"curb 是“把事物限制在边界内”，curl 是“卷曲”；把差异位 b ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：cassette = “a container that holds a magnetic tape used for recording or playing sound or video”。辨识时先提取关键词 container，确认核心义“盒式磁带”；词形再钉住双写 ss。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“garments or white goods that can be cleaned by laundering”反向定位 laundry：线索词 laundering 指向“洗衣房”。说出中文后再完整看一遍词形；回忆时保留完整短词形 laundry。","basis":"definition"},{"kind":"形近对照","text":"eminent 是“卓越的”，imminent 是“即将发生的”；把差异位 e ↔ im 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 prototype 固定在真实用法“he is the prototype of good breeding”里：它在句中指向“原型”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 pro…ype 定位。","basis":"usage"},{"kind":"形近对照","text":"tumour 是“肿瘤”，tutor 是“家庭教师”；把差异位 mou ↔ to 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a large structure for open-air sports or entertainments”反向定位 stadium：线索词 entertainments 指向“露天体育场”。说出中文后再完整看一遍词形；回忆时保留完整短词形 stadium。","basis":"definition"},{"kind":"形近对照","text":"seam 是“接缝”，seal 是“封住”；把差异位 m ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"loop 是“环”，loom 是“隐约出现”；把差异位 p ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"nominate 是“提名”，nominal 是“名义上的”；把差异位 te ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形状统一","text":"shaft 的核心形状是“细长直通的部分”：矛杆、机器轴和电梯井都符合这条形状 → 轴、井。","basis":"manual"},{"kind":"形近对照","text":"tariff 是“关税”，thrift 是“节约”；把差异位 ariff ↔ hrift 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 decimal 固定在真实用法“the decimal system”里：它在句中指向“小数”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 decimal。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：nephew = “a son of your brother or sister”。辨识时先提取关键词 brother，确认核心义“侄子”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a taboo subject”做记忆证据：其中 taboo 承担名词成分，核心就是“禁忌”。闭眼复述句意后再看词；词形再钉住双写 oo。","basis":"usage"},{"kind":"真实语境","text":"在真实句“Halt the engines”里，halt 是正在发生的动作；把动作画面直接标成“停止”。以后先演动作，再叫出这个词；回忆时保留完整短词形 halt。","basis":"usage"},{"kind":"真实语境","text":"把 vigorous 记成“a vigorous hiker”里的属性标签：它说明对象“精力充沛的”。看到相同描述位就触发这个词；词形用外框 vig…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"spoil 是“使人或事物变坏”，soil 是“土壤”；把差异位 p ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“a veteran officer”做记忆证据：其中 veteran 承担名词成分，核心就是“退伍军人”。闭眼复述句意后再看词；回忆时保留完整短词形 veteran。","basis":"usage"},{"kind":"形近对照","text":"paradise 是“天堂”，parasite 是“寄生虫”；把差异位 dis ↔ sit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 comb 固定在真实用法“They comb their hair”里：它在句中指向“梳子”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 comb。","basis":"usage"},{"kind":"形近对照","text":"rim 是“边沿”，rib 是“肋骨”；把差异位 m ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“an apparatus consisting of an object mounted so that it swings freely under the influence of gravity”反向定位 pendulum：线索词 consisting 指向“钟摆”。说出中文后再完整看一遍词形；词形用外框 pen…lum 定位。","basis":"definition"},{"kind":"词族链","text":"facile 是“容易的”，facilitate 就是把一件事变得 facile（容易）→ 促进、使便利。","basis":"manual"},{"kind":"形近对照","text":"bitter 是“苦的”，battery 是“电池”；把差异位 itter ↔ attery 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"contrive 是“设法做到”，conceive 是“想象”；把差异位 tr ↔ ce 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a small house with a single story”反向定位 cottage：线索词 single 指向“村舍”。说出中文后再完整看一遍词形；词形再钉住双写 tt。","basis":"definition"},{"kind":"形近对照","text":"tumble 是“摔倒”，tremble 是“颤抖”；把差异位 u ↔ re 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dim 是“暗淡的”，dam 是“水坝”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"torrent 是“急流”，torment 是“痛苦”；把差异位 r ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a light usually carried in the hand; consists of some flammable substance”反向定位 torch：线索词 flammable 指向“火炬”。说出中文后再完整看一遍词形；回忆时保留完整短词形 torch。","basis":"definition"},{"kind":"形近对照","text":"mercy 是“仁慈”，merry 是“愉快的”；把差异位 c ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"拟声画面","text":"bull 指成年公牛；想象公牛低沉地 bull 一声并向前顶。名词先锁“公牛”，金融中的 bull market 再由向上顶引申。","basis":"manual"},{"kind":"形近对照","text":"synthetic 是“合成的”，synthesis 是“综合”；把差异位 tic ↔ sis 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“wild and domesticated birds having a heavy body and short legs”反向定位 pigeon：线索词 domesticated 指向“鸽子”。说出中文后再完整看一遍词形；回忆时保留完整短词形 pigeon。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 blunder 定义为“commit a faux pas or a fault or make a serious mistake”。先抓定义中的 serious，再落到中文核心“犯愚蠢的错误”；回忆时保留完整短词形 blunder。","basis":"definition"},{"kind":"形近对照","text":"stripe 是“条纹”，stride 是“大步走”；把差异位 p ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“they emerged from the woods onto a vast open plain”中直接圈出 plain，旁注“平原”。句位、场景和词形三者一起回放；回忆时保留完整短词形 plain。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“measuring instrument for measuring temperature”反向定位 thermometer：线索词 temperature 指向“温度计”。说出中文后再完整看一遍词形；词形用外框 the…ter 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“Also common in English is another type of verb-noun (or noun-verb) compound, in which an argument of the verb is…”给 compound 留的是名词位；把这个位置换成“化合物”仍说得通。先复原句中事物，再认词；词形用外框 com…und 定位。","basis":"usage"},{"kind":"真实语境","text":"把 marvelous 记成“a marvelous collection of rare books”里的属性标签：它说明对象“极好的”。看到相同描述位就触发这个词；词形用外框 mar…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"paradox 是“悖论”，parade 是“游行”；把差异位 ox ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“an enclosed passageway; rooms usually open onto it”反向定位 corridor：线索词 passageway 指向“走廊”。说出中文后再完整看一遍词形；词形再钉住双写 rr。","basis":"definition"},{"kind":"形近对照","text":"coupon 是“优惠券”，cotton 是“棉花”；把差异位 up ↔ tt 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"patron 是“赞助人”，patrol 是“巡逻”；把差异位 n ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ski 是“滑雪板”，skim 是“浏览”；把差异位 ski ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"oval 是“椭圆形的”，oral 是“口头的”；把差异位 v ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词形联想","text":"appal 与 pale（苍白）做记忆联想：吓得脸色发白 → 使惊骇。英式 appal 单 l，美式 appall 双 l。","basis":"manual"},{"kind":"真实语境","text":"把 opaque 记成“opaque to X-rays”里的属性标签：它说明对象“不透明的”。看到相同描述位就触发这个词；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"神话人物","text":"Siren 是希腊神话中用歌声诱惑水手的海妖；她发出危险警报般的声音 → siren（汽笛、警报器）。","basis":"manual"},{"kind":"形近对照","text":"cement 是“水泥”，client 是“委托人”；把差异位 em ↔ li 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"prone 是“易于遭受…的”，probe 是“探查”；把差异位 n ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作画面","text":"mill 中间的 ill 被两侧 m/l 夹着反复碾；谷物被磨轮来回压碎 → mill（磨坊、磨粉机）。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：furnace = “an enclosed chamber in which heat is produced to heat buildings, destroy refuse, smelt or refine ores, etc.”。辨识时先提取关键词 buildings，确认核心义“炉子”；回忆时保留完整短词形 furnace。","basis":"definition"},{"kind":"形近对照","text":"patch 是“小块”，pitch 是“球场”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"scrape 是“刮掉”，scrap 是“碎片”；把差异位 e ↔ scrap 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 kin 固定在真实用法“he's kin”里：它在句中指向“亲戚”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 kin。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：frown = “look angry or sullen, wrinkle one's forehead, as if to signal disapproval”。辨识时先提取关键词 disapproval，确认核心义“皱眉”；回忆时保留完整短词形 frown。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a space into which an area is subdivided”反向定位 compartment：线索词 subdivided 指向“车厢”。说出中文后再完整看一遍词形；词形用外框 com…ent 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“quilt the skirt”给 quilt 留的是名词位；把这个位置换成“被子”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"形近对照","text":"clutch 是“紧握”，church 是“教堂”；把差异位 lut ↔ hur 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“he took a puff on his pipe”中直接圈出 puff，旁注“吸气”。句位、场景和词形三者一起回放；词形再钉住双写 ff。","basis":"usage"},{"kind":"形近对照","text":"rub 是“摩擦”，rib 是“肋骨”；把差异位 u ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"co-（共同）+ haer/hes（黏住，见 adhere、cohesive）+ -ent：各部分黏在一起不散 → 连贯的。","basis":"manual"},{"kind":"形近对照","text":"bail 是“保释”，bait 是“鱼饵”；把差异位 l ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"rot 是“腐烂”，rat 是“老鼠”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a barrier that serves to enclose an area”反向定位 fence：线索词 barrier 指向“栅栏”。说出中文后再完整看一遍词形；回忆时保留完整短词形 fence。","basis":"definition"},{"kind":"形近对照","text":"excerpt 是“摘录”，exempt 是“豁免的”；把差异位 cer ↔ em 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"cruise 是“航行”，crude 是“粗略的”；把差异位 is ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：temperament = “your usual mood”。辨识时先提取关键词 usual，确认核心义“性情”；词形用外框 tem…ent 定位。","basis":"definition"},{"kind":"形近对照","text":"jug 是“壶”，jog 是“慢跑”；把差异位 u ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“ridge the soil”给 ridge 留的是名词位；把这个位置换成“山脊”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 dge。","basis":"usage"},{"kind":"真实语境","text":"把 decay 固定在真实用法“The unoccupied house started to decay”里：它在句中指向“腐烂”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 decay。","basis":"usage"},{"kind":"形近对照","text":"rage 是“风靡一时”，rake 是“耙子”；把差异位 g ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“They speculate that there was a traffic accident”。speculate 在这里推动句子发生，核心动作是“推测”；词形用外框 spe…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“he fell prey to muggers”给 prey 留的是名词位；把这个位置换成“猎物”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 prey。","basis":"usage"},{"kind":"形近对照","text":"knob 是“球形把手”，knot 是“结”；把差异位 b ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"disperse 是“分散”，dispose 是“安排”；把差异位 er ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“the form of a word that is used to denote more than one”反向定位 plural：线索词 denote 指向“复数”。说出中文后再完整看一遍词形；回忆时保留完整短词形 plural。","basis":"definition"},{"kind":"真实语境","text":"在真实句“The bubble burst”里，burst 是正在发生的动作；把动作画面直接标成“爆裂”。以后先演动作，再叫出这个词；回忆时保留完整短词形 burst。","basis":"usage"},{"kind":"一词一画","text":"hatch 的 -tch 像蛋壳裂开的声音；小鸡啄破蛋壳出来 → 孵化、孵出。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：fragrant = “pleasant-smelling”。辨识时先提取关键词 pleasant-smelling，确认核心义“香的”；词形用外框 fra…ant 定位。","basis":"definition"},{"kind":"形近对照","text":"dine 是“吃饭”，dive 是“潜水”；把差异位 n ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"lamb 是“羔羊”，lame 是“跛的”；把差异位 b ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 petty 记成“petty officialdom”里的属性标签：它说明对象“琐碎的”。看到相同描述位就触发这个词；词形再钉住双写 tt。","basis":"usage"},{"kind":"形近对照","text":"grocer 是“食品杂货商”，grope 是“搜索”；把差异位 cer ↔ pe 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"医学词形","text":"abdom-/abdomen 是固定的医学“腹部”词干；看到腹肌训练 abdominal，就反推 abdomen（腹部）。","basis":"manual"},{"kind":"词义沿革","text":"拉丁语 contemplari 原指“划定一块区域仔细观察”；从端详、观察进一步变成在脑中反复看 → 思考、考虑。","basis":"manual"},{"kind":"形近对照","text":"crew 是“(全体) 船员”，crow 是“乌鸦”；把差异位 e ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“he is under an obligation to finish the job”中直接圈出 obligation，旁注“义务”。句位、场景和词形三者一起回放；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“The bad news will agitate him”。agitate 在这里推动句子发生，核心动作是“激怒”；回忆时保留完整短词形 agitate。","basis":"usage"},{"kind":"真实语境","text":"真实句“the whip raised a red welt”给 whip 留的是名词位；把这个位置换成“鞭子”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 whip。","basis":"usage"},{"kind":"释义锚点","text":"tobacco 暂无合适的例句，不编故事。用可核验定义“leaves of the tobacco plant dried and prepared for smoking or ingestion”做锚点，把 ingestion 与“烟草”成对回忆；词形再钉住双写 cc。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“They want to butcher the prisoners”中直接圈出 butcher，旁注“屠夫”。句位、场景和词形三者一起回放；词形再钉住辨识块 tch。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“increase in extent or intensity”反向定位 escalate：线索词 intensity 指向“逐步扩大”。说出中文后再完整看一遍词形；词形用外框 esc…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 nourish 定义为“provide with nourishment”。先抓定义中的 nourishment，再落到中文核心“抚养”；回忆时保留完整短词形 nourish。","basis":"definition"},{"kind":"形近对照","text":"evacuate 是“疏散”，evaluate 是“评价”；把差异位 c ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"optical 是“视力的”，optional 是“可以任选的”；把差异位 c ↔ on 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pinch 是“拧”，pitch 是“球场”；把差异位 n ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“a gorgeous Victorian gown”中，gorgeous 正在给对象贴上“非常漂亮的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 gor…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"breach 是“违背”，breast 是“乳房”；把差异位 ch ↔ st 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"slack 是“松弛的”，snack 是“快餐”；把差异位 l ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“(law) a gift of personal property by will”反向定位 legacy：线索词 personal 指向“遗产”。说出中文后再完整看一遍词形；回忆时保留完整短词形 legacy。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 calcium 定义为“a white metallic element that burns with a brilliant light; the fifth most abundant element in the earth's crust; an…”。先抓定义中的 brilliant，再落到中文核心“钙”；回忆时保留完整短词形 calcium。","basis":"definition"},{"kind":"形近对照","text":"steak 是“牛排”，sneak 是“偷偷地做”；把差异位 t ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"conceal 是“隐瞒”，concede 是“承认”；把差异位 al ↔ de 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a lay judge or civil authority who administers the law (especially one who conducts a court dealing with minor offenses)”反向定位 magistrate：线索词 administers 指向“地方执法官”。说出中文后再完整看一遍词形；词形用外框 mag…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 magnify 定义为“increase in size, volume or significance”。先抓定义中的 significance，再落到中文核心“放大”；回忆时保留完整短词形 magnify。","basis":"definition"},{"kind":"形近对照","text":"slim 是“苗条的”，skim 是“浏览”；把差异位 l ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：cripple = “deprive of strength or efficiency; make useless or worthless”。辨识时先提取关键词 efficiency，确认核心义“使跛”；词形再钉住双写 pp。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“intermittent rain showers”校准词义：intermittent 不是孤立标签，而是在说明“间歇的”的状态；词形再钉住双写 tt。","basis":"usage"},{"kind":"真实语境","text":"真实句“a terrific noise”中，terrific 正在给对象贴上“极好的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 rr。","basis":"usage"},{"kind":"真实语境","text":"把 intermediate 记成“an intermediate range plane”里的属性标签：它说明对象“中间的”。看到相同描述位就触发这个词；词形用外框 int…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：endow = “give qualities or abilities to”。辨识时先提取关键词 qualities，确认核心义“向…捐款”；回忆时保留完整短词形 endow。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“Sam and Sue choir”做记忆证据：其中 choir 承担名词成分，核心就是“合唱团”。闭眼复述句意后再看词；回忆时保留完整短词形 choir。","basis":"usage"},{"kind":"形近对照","text":"extinct 是“灭绝的”，extract 是“拔出”；把差异位 in ↔ ra 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"jargon 暂无合适的例句，不编故事。用可核验定义“a characteristic language of a particular group (as among thieves)”做锚点，把 characteristic 与“行话”成对回忆；回忆时保留完整短词形 jargon。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：crystal = “a solid formed by the solidification of a chemical and having a highly regular atomic structure”。辨识时先提取关键词 solidification，确认核心义“水晶”；回忆时保留完整短词形 crystal。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“the buzz of a bumble bee”做记忆证据：其中 buzz 承担名词成分，核心就是“嗡嗡声”。闭眼复述句意后再看词；词形再钉住双写 zz。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 architect 定义为“someone who creates plans to be used in making something (such as buildings)”。先抓定义中的 buildings，再落到中文核心“建筑师”；词形用外框 arc…ect 定位。","basis":"definition"},{"kind":"释义锚点","text":"slogan 暂无合适的例句，不编故事。用可核验定义“a favorite saying of a group, organization or individual”做锚点，把 organization 与“标题”成对回忆；回忆时保留完整短词形 slogan。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：remnant = “a small part or portion that remains after the main part no longer exists”。辨识时先提取关键词 portion，确认核心义“剩余部分”；词形再钉住辨识块 mn。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“They ascertain that there was a traffic accident”。ascertain 在这里推动句子发生，核心动作是“查明”；词形用外框 asc…ain 定位。","basis":"usage"},{"kind":"词根链","text":"aud- 表“听”（见 audio）：旧时账目由审计者听人逐项念出并核对 → audit（审计）。","basis":"manual"},{"kind":"形近对照","text":"bribe 是“贿赂”，bride 是“新娘”；把差异位 b ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：garlic = “bulbous herb of southern Europe widely naturalized; bulb breaks up into separate strong-flavored cloves”。辨识时先提取关键词 strong-flavored，确认核心义“大蒜”；回忆时保留完整短词形 garlic。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“the branch of pure mathematics dealing with the theory of numerical calculations”反向定位 arithmetic：线索词 calculations 指向“算术”。说出中文后再完整看一遍词形；词形用外框 ari…tic 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“a cunning baby”中，cunning 正在给对象贴上“狡猾的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 nn。","basis":"usage"},{"kind":"形近对照","text":"cluster 是“群聚”，counter 是“反驳”；把差异位 lus ↔ oun 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：niece = “a daughter of your brother or sister”。辨识时先提取关键词 daughter，确认核心义“侄女”；回忆时保留完整短词形 niece。","basis":"definition"},{"kind":"形近对照","text":"scout 是“侦察”，shout 是“大声说”；把差异位 c ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pledge 是“保证”，plunge 是“纵身投入”；把差异位 ed ↔ un 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"dynasty 暂无合适的例句，不编故事。用可核验定义“a sequence of powerful leaders in the same family”做锚点，把 sequence 与“王朝”成对回忆；回忆时保留完整短词形 dynasty。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：solidarity = “a union of interests or purposes or sympathies among members of a group”。辨识时先提取关键词 sympathies，确认核心义“团结”；词形用外框 sol…ity 定位。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“an orthodox view of the world”校准词义：orthodox 不是孤立标签，而是在说明“正统的”的状态；词形用外框 ort…dox 定位。","basis":"usage"},{"kind":"形近对照","text":"sack 是“麻袋”，slack 是“松弛的”；把差异位 a ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"resent 是“愤恨”，resist 是“抵抗”；把差异位 en ↔ is 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"discern 是“察觉出”，discard 是“抛弃”；把差异位 ern ↔ ard 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“They deposit the money”。deposit 在这里推动句子发生，核心动作是“放置”；回忆时保留完整短词形 deposit。","basis":"usage"},{"kind":"形近对照","text":"adhere 是“黏附”，ashore 是“在岸上”；把差异位 dhe ↔ sho 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"paralyze 暂无合适的例句，不编故事。用可核验定义“make powerless and unable to function”做锚点，把 powerless 与“使瘫痪”成对回忆；词形用外框 par…yze 定位。","basis":"definition"},{"kind":"真实语境","text":"在“wore conspicuous neckties”里圈出被修饰对象，再把 conspicuous 写成中文侧注“惹人注目的”。对象＋特征一起记；词形用外框 con…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"blast 是“爆炸”，beast 是“野兽”；把差异位 l ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tray 是“盘”，tram 是“有轨电车”；把差异位 y ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"prosecute 是“起诉”，persecute 是“迫害”；把差异位 ro ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：culprit = “someone who perpetrates wrongdoing”。辨识时先提取关键词 perpetrates，确认核心义“罪犯”；回忆时保留完整短词形 culprit。","basis":"definition"},{"kind":"形近对照","text":"belly 是“肚子”，bully 是“恐吓”；把差异位 e ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"accuse 是“指责”，amuse 是“逗笑”；把差异位 cc ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 stumble 放回“Sam and Sue stumble”：句中主语做的正是“绊脚”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 stumble。","basis":"usage"},{"kind":"部位对照","text":"chin 是下巴，cheek 是脸颊：chin 更短、更靠下；把末尾 n 当成下巴尖，和 cheek 分开。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“a diversion from the main highway”做记忆证据：其中 diversion 承担名词成分，核心就是“消遣”。闭眼复述句意后再看词；词形再钉住辨识块 sion。","basis":"usage"},{"kind":"真实语境","text":"在真实句“They weave the cape”里，weave 是正在发生的动作；把动作画面直接标成“编织”。以后先演动作，再叫出这个词；回忆时保留完整短词形 weave。","basis":"usage"},{"kind":"释义锚点","text":"ingredient 暂无合适的例句，不编故事。用可核验定义“a component of a mixture or compound”做锚点，把 component 与“成分”成对回忆；词形用外框 ing…ent 定位。","basis":"definition"},{"kind":"形近对照","text":"plough 是“犁”，plug 是“插头”；把差异位 ough ↔ ug 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dessert 是“餐后甜点”，descent 是“下降”；把差异位 ser ↔ cen 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"地名词源","text":"magnet 来自盛产磁石的 Magnesia 地区；Magnesia stone 能吸铁 → magnet（磁铁）。","basis":"manual"},{"kind":"释义锚点","text":"hostage 暂无合适的例句，不编故事。用可核验定义“a prisoner who is held by one party to insure that another party will meet specified terms”做锚点，把 specified 与“人质”成对回忆；回忆时保留完整短词形 hostage。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：foul = “highly offensive; arousing aversion or disgust”。辨识时先提取关键词 offensive，确认核心义“污秽的”；回忆时保留完整短词形 foul。","basis":"definition"},{"kind":"形近对照","text":"swear 是“发誓”，shear 是“剪”；把差异位 w ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“he added a column of numbers”给 column 留的是名词位；把这个位置换成“柱”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 mn。","basis":"usage"},{"kind":"形近对照","text":"trifle 是“小事”，trial 是“审讯”；把差异位 fle ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“They chill the water”比拆假词根可靠：定位其中的动词 chill，用“使寒冷”复述整句；词形再钉住双写 ll。","basis":"usage"},{"kind":"计量词源","text":"ounce 来自拉丁 uncia“十二分之一”；一磅的十六分之一仍是小重量单位。盯住开头 ou-，不要写成 once。","basis":"manual"},{"kind":"形近对照","text":"rake 是“耙子”，rage 是“风靡一时”；把差异位 k ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 slender 记成“she was slender as a willow shoot is slender”里的属性标签：它说明对象“修长的”。看到相同描述位就触发这个词；回忆时保留完整短词形 slender。","basis":"usage"},{"kind":"形近对照","text":"shrewd 是“机灵的”，shed 是“棚屋”；把差异位 rew ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“Satire is a sort of glass, wherein beholders do generally discover everybody's”做记忆证据：其中 satire 承担名词成分，核心就是“讽刺”。闭眼复述句意后再看词；回忆时保留完整短词形 satire。","basis":"usage"},{"kind":"形近对照","text":"cereal 是“谷类食物”，cream 是“奶油”；把差异位 ereal ↔ ream 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"rouse 是“唤醒”，rose 是“玫瑰花”；把差异位 u ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“the immigrants spoke an odd dialect of English”中直接圈出 dialect，旁注“方言”。句位、场景和词形三者一起回放；回忆时保留完整短词形 dialect。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a small smooth rounded rock”反向定位 pebble：线索词 rounded 指向“鹅卵石”。说出中文后再完整看一遍词形；词形再钉住双写 bb。","basis":"definition"},{"kind":"英美拼写","text":"cosy 是英式拼法，美式写 cozy；把中间 s/z 当作拉链拉上，形成温暖封闭的小空间 → 舒适的。","basis":"manual"},{"kind":"释义锚点","text":"pest 暂无合适的例句，不编故事。用可核验定义“a serious (sometimes fatal) infection of rodents caused by Yersinia pestis and accidentally transmitted to humans by the…”做锚点，把 accidentally 与“害虫”成对回忆；回忆时保留完整短词形 pest。","basis":"definition"},{"kind":"同族挂钩","text":"spectacular 可与 spectacle（壮观的景象）放在同一词族里对照；保留共同词形，同时把 spectacular 单独落到“壮观的”。","basis":"family"},{"kind":"形近对照","text":"bind 是“捆绑”，band 是“乐队”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“magnificent cathedrals”中，magnificent 正在给对象贴上“宏伟的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 mag…ent 定位。","basis":"usage"},{"kind":"形近对照","text":"heaven 是“天堂”，heave 是“举起”；把差异位 n ↔ heave 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“The streets creep with crowds”比拆假词根可靠：定位其中的动词 creep，用“悄悄行进”复述整句；词形再钉住双写 ee。","basis":"usage"},{"kind":"形近对照","text":"merry 是“愉快的”，mercy 是“仁慈”；把差异位 r ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 pension 定义为“a regular payment to a person that is intended to allow them to subsist without working”。先抓定义中的 intended，再落到中文核心“养老金”；词形再钉住辨识块 sion。","basis":"definition"},{"kind":"释义锚点","text":"drift 暂无合适的例句，不编故事。用可核验定义“be in motion due to some air or water current”做锚点，把 current 与“漂流”成对回忆；回忆时保留完整短词形 drift。","basis":"definition"},{"kind":"真实语境","text":"真实用法“hurl insults”比拆假词根可靠：定位其中的动词 hurl，用“用力投掷”复述整句；回忆时保留完整短词形 hurl。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“the effect was negligible”校准词义：negligible 不是孤立标签，而是在说明“微不足道的”的状态；词形用外框 neg…ble 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“a hollow wall”中，hollow 正在给对象贴上“中空的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"exempt 是“豁免的”，excerpt 是“摘录”；把差异位 em ↔ cer 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：mosquito = “two-winged insect whose female has a long proboscis to pierce the skin and suck the blood of humans and animals”。辨识时先提取关键词 two-winged，确认核心义“蚊子”；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"形近对照","text":"gaze 是“凝视”，graze 是“放牧”；把差异位 a ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"fuss 是“烦恼”，fuse 是“融合”；把差异位 s ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"hut 是“棚屋”，hum 是“哼”；把差异位 t ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“intrinsic muscles”里圈出被修饰对象，再把 intrinsic 写成中文侧注“内在的”。对象＋特征一起记；词形用外框 int…sic 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“an overt lie”校准词义：overt 不是孤立标签，而是在说明“公开的”的状态；回忆时保留完整短词形 overt。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 furnish 定义为“give something useful or necessary to”。先抓定义中的 necessary，再落到中文核心“布置房间”；回忆时保留完整短词形 furnish。","basis":"definition"},{"kind":"释义锚点","text":"lyric 暂无合适的例句，不编故事。用可核验定义“the text of a popular song or musical-comedy number”做锚点，把 musical-comedy 与“抒情诗”成对回忆；回忆时保留完整短词形 lyric。","basis":"definition"},{"kind":"词根链","text":"extra-（超出）+ vag（漫游、越界）+ -ant：花费越过正常界限 → extravagant（奢侈的、过度的）。","basis":"manual"},{"kind":"真实语境","text":"记一帧动作证据：“Great heat can ignite almost any dry matter”。ignite 在这里推动句子发生，核心动作是“燃烧”；回忆时保留完整短词形 ignite。","basis":"usage"},{"kind":"真实语境","text":"在真实句“They want to stab the prisoners”里，stab 是正在发生的动作；把动作画面直接标成“刺”。以后先演动作，再叫出这个词；回忆时保留完整短词形 stab。","basis":"usage"},{"kind":"真实语境","text":"把 swamp 固定在真实用法“he was trapped in a medical swamp”里：它在句中指向“沼泽”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 swamp。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：trolley = “a wheeled vehicle that runs on rails and is propelled by electricity”。辨识时先提取关键词 electricity，确认核心义“手推车”；词形再钉住双写 ll。","basis":"definition"},{"kind":"形近对照","text":"scar 是“伤疤”，soar 是“暴涨”；把差异位 c ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形状画面","text":"saddle 中间双 d 像马背两侧垂下的马镫；跨在马背上的座具 → 马鞍。","basis":"manual"},{"kind":"释义锚点","text":"beard 暂无合适的例句，不编故事。用可核验定义“the hair growing on the lower part of a man's face”做锚点，把 growing 与“胡须”成对回忆；回忆时保留完整短词形 beard。","basis":"definition"},{"kind":"真实语境","text":"真实用法“Stain this table a beautiful walnut color”比拆假词根可靠：定位其中的动词 stain，用“弄脏”复述整句；回忆时保留完整短词形 stain。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“it was so funny it was a circus”做记忆证据：其中 circus 承担名词成分，核心就是“马戏团”。闭眼复述句意后再看词；回忆时保留完整短词形 circus。","basis":"usage"},{"kind":"真实语境","text":"真实句“They cage the animals”给 cage 留的是名词位；把这个位置换成“笼子”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 cage。","basis":"usage"},{"kind":"真实语境","text":"把 incredible 记成“at incredible speed”里的属性标签：它说明对象“难以置信的”。看到相同描述位就触发这个词；词形用外框 inc…ble 定位。","basis":"usage"},{"kind":"真实语境","text":"在“stood resolute against the enemy”里圈出被修饰对象，再把 resolute 写成中文侧注“坚决的”。对象＋特征一起记；词形用外框 res…ute 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“provide with a joint”反向定位 articulate：线索词 provide 指向“明确表达”。说出中文后再完整看一遍词形；词形用外框 art…ate 定位。","basis":"definition"},{"kind":"形近对照","text":"rotten 是“腐烂的”，rotate 是“旋转”；把差异位 ten ↔ ate 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 redundant 记成“skills made redundant by technological advance”里的属性标签：它说明对象“被裁减的”。看到相同描述位就触发这个词；词形用外框 red…ant 定位。","basis":"usage"},{"kind":"形近对照","text":"limp 是“跛行”，lamp 是“灯”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“prevent from being included or considered or accepted”反向定位 omit：线索词 considered 指向“省略”。说出中文后再完整看一遍词形；回忆时保留完整短词形 omit。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 courtesy 定义为“a courteous or respectful or considerate act”。先抓定义中的 considerate，再落到中文核心“谦恭有礼的举止”；词形用外框 cou…esy 定位。","basis":"definition"},{"kind":"形近对照","text":"bully 是“恐吓”，belly 是“肚子”；把差异位 u ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“they had to plan for contingent expenses”里圈出被修饰对象，再把 contingent 写成中文侧注“依情况而定的”。对象＋特征一起记；词形用外框 con…ent 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“enormous expenses”校准词义：enormous 不是孤立标签，而是在说明“巨大的”的状态；词形用外框 eno…ous 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 endorse 定义为“be behind; approve of”。先抓定义中的 approve，再落到中文核心“公开支持”；回忆时保留完整短词形 endorse。","basis":"definition"},{"kind":"真实语境","text":"把 bleak 记成“prospects were bleak”里的属性标签：它说明对象“无望的”。看到相同描述位就触发这个词；回忆时保留完整短词形 bleak。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：dissipate = “to cause to separate and go in different directions”。辨识时先提取关键词 directions，确认核心义“消散”；词形再钉住双写 ss。","basis":"definition"},{"kind":"形近对照","text":"corrode 是“腐蚀”，comrade 是“共患难的朋友”；把差异位 rro ↔ mra 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“Lights glitter on the horizon”里，glitter 是正在发生的动作；把动作画面直接标成“闪耀”。以后先演动作，再叫出这个词；词形再钉住双写 tt。","basis":"usage"},{"kind":"形近对照","text":"knit 是“编织”，knot 是“结”；把差异位 i ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"perplex 是“迷惑”，purple 是“紫色的”；把差异位 erplex ↔ urple 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"reckon 是“认为”，region 是“区域”；把差异位 ck ↔ gi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tale 是“故事”，tame 是“驯化的”；把差异位 l ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"构词链","text":"dis-（打乱、否定）+ order（秩序）：秩序被打乱 → disorder（杂乱、失调）。","basis":"manual"},{"kind":"形近对照","text":"tame 是“驯化的”，tale 是“故事”；把差异位 m ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dealer 是“经销商”，deer 是“鹿”；把差异位 al ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"strap 是“带子”，scrap 是“碎片”；把差异位 t ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"glamour 暂无合适的例句，不编故事。用可核验定义“alluring beauty or charm (often with sex-appeal)”做锚点，把 sex-appeal 与“魅力”成对回忆；回忆时保留完整短词形 glamour。","basis":"definition"},{"kind":"真实语境","text":"在“domestic servant”里圈出被修饰对象，再把 domestic 写成中文侧注“家用的”。对象＋特征一起记；词形用外框 dom…tic 定位。","basis":"usage"},{"kind":"形近对照","text":"toll 是“伤亡人数”，toil 是“苦工”；把差异位 l ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"capable 是“有才干的”，capsule 是“胶囊”；把差异位 ab ↔ su 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"stool 是“凳子”，stoop 是“弯腰”；把差异位 l ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"字母画面","text":"peep 两个 ee 像一双从缝里露出的眼睛；只偷偷看一眼 → peep（偷看、窥视）。","basis":"manual"},{"kind":"词源实物","text":"canoe 源自加勒比海原住民的 canoa；词尾独特的 -oe 就像独木舟尖尖的两端 → 独木舟。","basis":"manual"},{"kind":"形近对照","text":"stimulate 是“促进”，stipulate 是“规定”；把差异位 m ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"stiff 是“僵硬的”，sniff 是“嗅”；把差异位 t ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：valve = “a structure in a hollow organ (like the heart) with a flap to insure one-way flow of fluid through it”。辨识时先提取关键词 structure，确认核心义“阀门”；回忆时保留完整短词形 valve。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“he is musically illiterate”校准词义：illiterate 不是孤立标签，而是在说明“不会读写的”的状态；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"elapse 是“流逝”，erase 是“抹去”；把差异位 lap ↔ ra 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"inhibit 是“妨碍”，inherit 是“继承”；把差异位 ib ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"双义挂钩","text":"pupil 既是“小学生”，也可指瞳孔；把老师眼中的小学生和眼睛里的小人影放在一起，固定 pu-pil。","basis":"manual"},{"kind":"词根链","text":"nost-（返乡）+ alg-（痛，见 neuralgia）+ -ic：想回到过去而产生的隐痛 → 怀旧的。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 encyclopedia 定义为“a reference work (often in several volumes) containing articles on various topics (often arranged in alphabetical order)…”。先抓定义中的 alphabetical，再落到中文核心“百科全书 - =<英>encyclopaedia”；词形用外框 enc…dia 定位。","basis":"definition"},{"kind":"形近对照","text":"pad 是“衬垫”，pan 是“平底锅”；把差异位 d ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tin 是“锡”，tan 是“晒黑”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“In the summer they like to go out and pearl”做记忆证据：其中 pearl 承担名词成分，核心就是“珍珠”。闭眼复述句意后再看词；回忆时保留完整短词形 pearl。","basis":"usage"},{"kind":"真实语境","text":"在真实句“The bad news will dismay him”里，dismay 是正在发生的动作；把动作画面直接标成“使惊愕”。以后先演动作，再叫出这个词；回忆时保留完整短词形 dismay。","basis":"usage"},{"kind":"释义锚点","text":"tomb 暂无合适的例句，不编故事。用可核验定义“a place for the burial of a corpse (especially beneath the ground and marked by a tombstone)”做锚点，把 tombstone 与“坟墓”成对回忆；回忆时保留完整短词形 tomb。","basis":"definition"},{"kind":"形近对照","text":"tease 是“戏弄”，tense 是“紧张的”；把差异位 a ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"rein 是“缰绳”，reign 是“统治期”；把差异位 n ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"indulge 是“沉溺于”，induce 是“导致”；把差异位 lg ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 renovate 放回“My wife wants us to renovate”：句中主语做的正是“修复”。先抓施事者与动作，再提取词形；词形用外框 ren…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"heap 是“一堆”，heal 是“治愈”；把差异位 p ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"detain 是“扣留”，detail 是“细节”；把差异位 n ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deputy 是“副手”，debut 是“初次亮相”；把差异位 puty ↔ but 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"trunk 是“树干”，truck 是“卡车”；把差异位 n ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"damp 是“有湿气的”，damn 是“批评”；把差异位 p ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“inspired by love for your country”反向定位 patriotic：线索词 inspired 指向“爱国的”。说出中文后再完整看一遍词形；词形用外框 pat…tic 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“a brilliant mind”中，brilliant 正在给对象贴上“聪明的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 ll。","basis":"usage"},{"kind":"真实语境","text":"把 discriminate 放回“discriminate people”：句中主语做的正是“区别”。先抓施事者与动作，再提取词形；词形用外框 dis…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“cushion the blow”中直接圈出 cushion，旁注“垫子”。句位、场景和词形三者一起回放；回忆时保留完整短词形 cushion。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“Lights beam on the horizon”做记忆证据：其中 beam 承担名词成分，核心就是“光线”。闭眼复述句意后再看词；回忆时保留完整短词形 beam。","basis":"usage"},{"kind":"夹具画面","text":"vice 作为“恶习”像台钳（vise）夹住人不放；用 c/s 区分：vice 是恶习，vise 是夹具。","basis":"manual"},{"kind":"形近对照","text":"sneak 是“偷偷地做”，steak 是“牛排”；把差异位 n ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"mortal 是“终有一死的”，mental 是“智力的”；把差异位 or ↔ en 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“short account of an incident (especially a biographical one)”反向定位 anecdote：线索词 biographical 指向“轶事”。说出中文后再完整看一遍词形；词形用外框 ane…ote 定位。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 blouse 定义为“a top worn by women”。先抓定义中的 women，再落到中文核心“衬衫”；回忆时保留完整短词形 blouse。","basis":"definition"},{"kind":"真实语境","text":"把 elaborate 记成“an elaborate lace pattern”里的属性标签：它说明对象“复杂的”。看到相同描述位就触发这个词；词形用外框 ela…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"melody 是“旋律”，melon 是“瓜”；把差异位 dy ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"blaze 是“火焰”，blame 是“把…归咎于”；把差异位 z ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"coil 是“缠绕”，coal 是“煤”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 levy 固定在真实用法“levy a fine”里：它在句中指向“税款”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 levy。","basis":"usage"},{"kind":"形近对照","text":"tremble 是“颤抖”，tumble 是“摔倒”；把差异位 re ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pin 是“大头针”，pan 是“平底锅”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"拟声＋分义","text":"cricket 的 crick-crick 模仿蟋蟀叫声；板球义另走一线。先用叫声锁住拼写，再按语境判“蟋蟀/板球”。","basis":"manual"},{"kind":"释义锚点","text":"allegiance 暂无合适的例句，不编故事。用可核验定义“the act of binding yourself (intellectually or emotionally) to a course of action”做锚点，把 intellectually 与“拥护”成对回忆；词形再钉住双写 ll。","basis":"definition"},{"kind":"英美拼写","text":"mould 是英式拼法，美式 mold；模具把材料“定型”，霉菌也形成一层形状。保留英式中间的 u。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“they took an oath of allegiance”做记忆证据：其中 oath 承担名词成分，核心就是“宣誓”。闭眼复述句意后再看词；回忆时保留完整短词形 oath。","basis":"usage"},{"kind":"形近对照","text":"blanket 是“毛毯”，bracket 是“括号”；把差异位 lan ↔ rac 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 furniture 固定在真实用法“there was only one piece of furniture in the room”里：它在句中指向“家具”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 fur…ure 定位。","basis":"usage"},{"kind":"形近对照","text":"analogy 是“类比”，analogue 是“模拟的”；把差异位 y ↔ ue 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shell 是“壳”，shall 是“将要”；把差异位 e ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“These cars won't brake”给 brake 留的是名词位；把这个位置换成“刹车”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 brake。","basis":"usage"},{"kind":"释义锚点","text":"naughty 暂无合适的例句，不编故事。用可核验定义“suggestive of sexual impropriety”做锚点，把 impropriety 与“顽皮的”成对回忆；词形再钉住辨识块 augh。","basis":"definition"},{"kind":"形近对照","text":"spite 是“恶意”，spine 是“脊柱”；把差异位 t ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“The meadows groan with animals”。groan 在这里推动句子发生，核心动作是“呻吟”；回忆时保留完整短词形 groan。","basis":"usage"},{"kind":"词根链","text":"co-（共同）+ hes（黏住，见 adhere）+ -ive：成员彼此黏合成整体 → 有凝聚力的、团结的。","basis":"manual"},{"kind":"形近对照","text":"brandy 是“白兰地”，band 是“乐队”；把差异位 randy ↔ and 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shiver 是“战栗”，sheer 是“完全的”；把差异位 iv ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“characterized by directness in manner or speech; without subtlety or evasion”反向定位 frank：线索词 directness 指向“坦白的”。说出中文后再完整看一遍词形；回忆时保留完整短词形 frank。","basis":"definition"},{"kind":"真实语境","text":"真实句“mere rhetoric”给 rhetoric 留的是名词位；把这个位置换成“花言巧语”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 rh。","basis":"usage"},{"kind":"形近对照","text":"belt 是“皮带”，bolt 是“插销”；把差异位 e ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“The business is going to flourish”比拆假词根可靠：定位其中的动词 flourish，用“繁荣”复述整句；词形用外框 flo…ish 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“a flood of requests”做记忆证据：其中 flood 承担名词成分，核心就是“洪水”。闭眼复述句意后再看词；词形再钉住双写 oo。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 stereotype 定义为“a conventional or formulaic conception or image”。先抓定义中的 conventional，再落到中文核心“刻板印象”；词形用外框 ste…ype 定位。","basis":"definition"},{"kind":"释义锚点","text":"commodity 暂无合适的例句，不编故事。用可核验定义“a raw material that is sold in large quantities, usually to other businesses for manufacturing or production purposes”做锚点，把 manufacturing 与“商品”成对回忆；词形再钉住双写 mm。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：chaos = “a state of extreme confusion and disorder”。辨识时先提取关键词 confusion，确认核心义“混乱”；回忆时保留完整短词形 chaos。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“the official name of some states in the United States (Massachusetts and Pennsylvania and Virginia and Kentucky) and…”反向定位 commonwealth：线索词 massachusetts 指向“联邦”。说出中文后再完整看一遍词形；词形再钉住双写 mm。","basis":"definition"},{"kind":"形近对照","text":"shuttle 是“航天飞机”，shutter 是“百叶窗”；把差异位 le ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"obey 暂无合适的例句，不编故事。用可核验定义“be obedient to”做锚点，把 obedient 与“遵守”成对回忆；回忆时保留完整短词形 obey。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：vanity = “feelings of excessive pride”。辨识时先提取关键词 excessive，确认核心义“虚荣心”；回忆时保留完整短词形 vanity。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a conceptual whole made up of complicated and related parts”反向定位 composite：线索词 complicated 指向“合成物”。说出中文后再完整看一遍词形；词形用外框 com…ite 定位。","basis":"definition"},{"kind":"形近对照","text":"cradle 是“摇篮”，candle 是“蜡烛”；把差异位 ra ↔ an 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 perpetual 记成“hell's perpetual fires”里的属性标签：它说明对象“不间断的”。看到相同描述位就触发这个词；词形用外框 per…ual 定位。","basis":"usage"},{"kind":"真实语境","text":"在“a faint outline”里圈出被修饰对象，再把 faint 写成中文侧注“微弱的”。对象＋特征一起记；回忆时保留完整短词形 faint。","basis":"usage"},{"kind":"形近对照","text":"integral 是“必需的”，interval 是“间隔”；把差异位 gr ↔ rv 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 chimney 定义为“a vertical flue that provides a path through which smoke from a fire is carried away through the wall or roof of a building”。先抓定义中的 vertical，再落到中文核心“烟囱”；词形再钉住辨识块 mn。","basis":"definition"},{"kind":"真实语境","text":"把 saturate 放回“They saturate the cloth with water and alcohol”：句中主语做的正是“使浸透”。先抓施事者与动作，再提取词形；词形用外框 sat…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：superstition = “an irrational belief arising from ignorance or fear”。辨识时先提取关键词 irrational，确认核心义“迷信”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a troop of children”做记忆证据：其中 troop 承担名词成分，核心就是“军队”。闭眼复述句意后再看词；词形再钉住双写 oo。","basis":"usage"},{"kind":"真实语境","text":"真实句“an affluent banker”中，affluent 正在给对象贴上“丰富的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 ff。","basis":"usage"},{"kind":"形近对照","text":"bulk 是“主体”，bull 是“公牛”；把差异位 k ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"discreet 是“谨慎的”，discrete 是“分离的”；把差异位 et ↔ te 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根画面","text":"dis-（来回、分开）+ cours（跑）：思想和话语在双方之间来回跑 → discourse（论述、谈话）。","basis":"manual"},{"kind":"形近对照","text":"swan 是“天鹅”，span 是“持续时间”；把差异位 w ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 spill 放回“spill the milk”：句中主语做的正是“洒出”。先抓施事者与动作，再提取词形；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"reed 是“芦苇”，reel 是“卷筒”；把差异位 d ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tile 是“瓷砖”，tale 是“故事”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"splash 是“泼洒”，smash 是“打碎”；把差异位 pl ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 eligible 记成“an eligible bachelor”里的属性标签：它说明对象“有资格的”。看到相同描述位就触发这个词；词形用外框 eli…ble 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“a roundabout paragraph”中直接圈出 roundabout，旁注“环岛”。句位、场景和词形三者一起回放；词形用外框 rou…out 定位。","basis":"usage"},{"kind":"形近对照","text":"loom 是“隐约出现”，loop 是“环”；把差异位 m ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"throne 是“宝座”，thrive 是“兴旺”；把差异位 on ↔ iv 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"palm 是“手掌”，pale 是“苍白的”；把差异位 m ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"infant 是“幼儿”，infect 是“感染”；把差异位 an ↔ ec 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a ditch dug as a fortification having a parapet of the excavated earth”反向定位 trench：线索词 fortification 指向“沟渠”。说出中文后再完整看一遍词形；回忆时保留完整短词形 trench。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 fiber 定义为“a slender and greatly elongated substance capable of being spun into yarn”。先抓定义中的 elongated，再落到中文核心“纤维”；回忆时保留完整短词形 fiber。","basis":"definition"},{"kind":"形近对照","text":"stack 是“一叠”，slack 是“松弛的”；把差异位 t ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"startle 是“惊吓”，staple 是“基本的”；把差异位 rt ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"steep 是“险峻的”，steel 是“钢”；把差异位 p ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源动作","text":"laps-/labi 表“滑落”：从应有标准上滑下去一次 → lapse（疏忽、过失）；一段时间滑过去也可指间隔。","basis":"manual"},{"kind":"真实语境","text":"把 drought 固定在真实用法“when England defeated Pakistan it ended a ten-year drought”里：它在句中指向“干旱”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 ough。","basis":"usage"},{"kind":"真实语境","text":"在“a close-knit homogeneous group”里圈出被修饰对象，再把 homogeneous 写成中文侧注“同种类的”。对象＋特征一起记；词形用外框 hom…ous 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“enter uninvited”反向定位 intrude：线索词 uninvited 指向“侵入”。说出中文后再完整看一遍词形；回忆时保留完整短词形 intrude。","basis":"definition"},{"kind":"形近对照","text":"candle 是“蜡烛”，castle 是“城堡”；把差异位 nd ↔ st 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 jail 固定在真实用法“They want to jail the prisoners”里：它在句中指向“监狱”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 jail。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：erupt = “start abruptly”。辨识时先提取关键词 abruptly，确认核心义“爆发”；回忆时保留完整短词形 erupt。","basis":"definition"},{"kind":"形近对照","text":"storey 是“楼层 - =<美>story”，stereo 是“立体声”；把差异位 orey ↔ ereo 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 ferry 定义为“a boat that transports people or vehicles across a body of water and operates on a regular schedule”。先抓定义中的 transports，再落到中文核心“渡船”；词形再钉住双写 rr。","basis":"definition"},{"kind":"释义锚点","text":"humidity 暂无合适的例句，不编故事。用可核验定义“wetness in the atmosphere”做锚点，把 atmosphere 与“潮湿”成对回忆；词形用外框 hum…ity 定位。","basis":"definition"},{"kind":"法英对照","text":"英语 pig 是活猪，法语来源的 pork 指餐桌上的猪肉；看到 p-or-k 就把猪从农场移到餐盘。","basis":"manual"},{"kind":"形近对照","text":"hum 是“哼”，ham 是“火腿”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“imperial colony”中，imperial 正在给对象贴上“帝国的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 imp…ial 定位。","basis":"usage"},{"kind":"释义锚点","text":"flavor 暂无合适的例句，不编故事。用可核验定义“the general atmosphere of a place or situation and the effect that it has on people”做锚点，把 atmosphere 与“味道”成对回忆；回忆时保留完整短词形 flavor。","basis":"definition"},{"kind":"词源场景","text":"pregnant 的拉丁核心带有“出生之前、怀着”的概念：孩子尚未出生而在体内 → 怀孕的。","basis":"manual"},{"kind":"形近对照","text":"dispute 是“争论”，dispose 是“安排”；把差异位 ut ↔ os 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"feat 是“功绩”，flat 是“平的”；把差异位 e ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"harass（骚扰）+ -ment（行为/结果）；双 s 属于词干 harass，不能在加后缀时丢掉 → harassment。","basis":"manual"},{"kind":"形近对照","text":"breeze 是“微风”，bronze 是“青铜”；把差异位 ee ↔ on 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"stalk 是“跟踪”，stack 是“一叠”；把差异位 l ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bruise 是“瘀伤”，bribe 是“贿赂”；把差异位 uis ↔ ib 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"rip 是“撕裂”，rib 是“肋骨”；把差异位 p ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"paddle 是“船桨”，pale 是“苍白的”；把差异位 dd ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"riot 是“暴乱”，rot 是“腐烂”；把差异位 i ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"loan 是“借出”，lean 是“倾斜身体”；把差异位 o ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 literature 固定在真实用法“the technical literature”里：它在句中指向“文学”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 lit…ure 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：pub = “tavern consisting of a building with a bar and public rooms; often provides light meals”。辨识时先提取关键词 consisting，确认核心义“酒吧”；回忆时保留完整短词形 pub。","basis":"definition"},{"kind":"历史画面","text":"free lance 原指不效忠固定领主、把长矛 lance 出售给任何雇主的佣兵；现代变成自由职业者。","basis":"manual"},{"kind":"形近对照","text":"adverse 是“不利的”，adhere 是“黏附”；把差异位 vers ↔ her 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"wrench 是“猛扭”，wreck 是“残骸”；把差异位 nch ↔ ck 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"conquest 是“征服”，conquer 是“攻克”；把差异位 st ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"district 是“地区”，distract 是“使分心”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"imminent 是“即将发生的”，eminent 是“卓越的”；把差异位 im ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 futile 记成“a futile effort”里的属性标签：它说明对象“徒劳的”。看到相同描述位就触发这个词；回忆时保留完整短词形 futile。","basis":"usage"},{"kind":"形近对照","text":"lamp 是“灯”，lamb 是“羔羊”；把差异位 p ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sin 是“罪”，sip 是“小口喝”；把差异位 n ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 shrug 定义为“raise one's shoulders to indicate indifference or resignation”。先抓定义中的 indifference，再落到中文核心“耸肩”；回忆时保留完整短词形 shrug。","basis":"definition"},{"kind":"真实语境","text":"把 melt 放回“melt butter”：句中主语做的正是“熔化”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 melt。","basis":"usage"},{"kind":"形近对照","text":"swell 是“肿胀”，shell 是“壳”；把差异位 w ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a person of subnormal intelligence”反向定位 idiot：线索词 intelligence 指向“蠢货”。说出中文后再完整看一遍词形；回忆时保留完整短词形 idiot。","basis":"definition"},{"kind":"形近对照","text":"tablet 是“平板电脑”，toilet 是“抽水马桶”；把差异位 ab ↔ oi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 dull 记成“he was so dull at parties”里的属性标签：它说明对象“枯燥的”。看到相同描述位就触发这个词；词形再钉住双写 ll。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：monument = “a structure erected to commemorate persons or events”。辨识时先提取关键词 commemorate，确认核心义“纪念碑”；词形用外框 mon…ent 定位。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“they have the illusion that I am very wealthy”做记忆证据：其中 illusion 承担名词成分，核心就是“错觉”。闭眼复述句意后再看词；词形再钉住双写 ll。","basis":"usage"},{"kind":"真实语境","text":"在真实句“The men mount the bookshelves”里，mount 是正在发生的动作；把动作画面直接标成“登上”。以后先演动作，再叫出这个词；回忆时保留完整短词形 mount。","basis":"usage"},{"kind":"形近对照","text":"peasant 是“农民”，pleasant 是“令人愉快的”；把差异位 e ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：ventilate = “expose to cool or cold air so as to cool or freshen”。辨识时先提取关键词 freshen，确认核心义“使通风”；词形用外框 ven…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“the time of day immediately following sunset”反向定位 dusk：线索词 immediately 指向“黄昏”。说出中文后再完整看一遍词形；回忆时保留完整短词形 dusk。","basis":"definition"},{"kind":"真实语境","text":"真实句“he pitched his tent near the creek”给 tent 留的是名词位；把这个位置换成“帐篷”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 tent。","basis":"usage"},{"kind":"释义锚点","text":"encounter 暂无合适的例句，不编故事。用可核验定义“come together”做锚点，把 together 与“遭遇”成对回忆；词形用外框 enc…ter 定位。","basis":"definition"},{"kind":"形近对照","text":"vein 是“静脉”，vain 是“徒劳的”；把差异位 e ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"nominal 是“名义上的”，nominate 是“提名”；把差异位 l ↔ te 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“incidentally, I won't go to the party”中，incidentally 修饰动作的方式或程度，落点是“附带地”。先复述动作怎样发生，再认词；词形再钉住双写 ll。","basis":"usage"},{"kind":"真实语境","text":"把 dwell 放回“The problems dwell in the social injustices in this country”：句中主语做的正是“居住”。先抓施事者与动作，再提取词形；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"mug 是“马克杯”，mud 是“泥”；把差异位 g ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“They dye their hair”。dye 在这里推动句子发生，核心动作是“给…染色”；回忆时保留完整短词形 dye。","basis":"usage"},{"kind":"真实语境","text":"真实句“drastic measures”中，drastic 正在给对象贴上“激烈的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 drastic。","basis":"usage"},{"kind":"真实语境","text":"把 paste 固定在真实用法“paste the sign on the wall”里：它在句中指向“面团”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 paste。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：sulfur = “an abundant tasteless odorless multivalent nonmetallic element; best known in yellow crystals; occurs in many sulphide and…”。辨识时先提取关键词 multivalent，确认核心义“硫”；回忆时保留完整短词形 sulfur。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“the alimentary canal”做记忆证据：其中 canal 承担名词成分，核心就是“运河”。闭眼复述句意后再看词；回忆时保留完整短词形 canal。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 hydrogen 定义为“a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and…”。先抓定义中的 nonmetallic，再落到中文核心“氢”；词形用外框 hyd…gen 定位。","basis":"definition"},{"kind":"真实语境","text":"把 scramble 放回“The chef wants to scramble the eggs”：句中主语做的正是“攀登”。先抓施事者与动作，再提取词形；词形用外框 scr…ble 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“pump the gas pedal”中直接圈出 pump，旁注“泵”。句位、场景和词形三者一起回放；回忆时保留完整短词形 pump。","basis":"usage"},{"kind":"形近对照","text":"spiral 是“螺旋形的”，spill 是“洒出”；把差异位 ra ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 discrepancy 定义为“a difference between conflicting facts or claims or opinions”。先抓定义中的 conflicting，再落到中文核心“差异”；词形用外框 dis…ncy 定位。","basis":"definition"},{"kind":"释义锚点","text":"camel 暂无合适的例句，不编故事。用可核验定义“cud-chewing mammal used as a draft or saddle animal in desert regions”做锚点，把 cud-chewing 与“骆驼”成对回忆；回忆时保留完整短词形 camel。","basis":"definition"},{"kind":"形近对照","text":"concise 是“简洁的”，concede 是“承认”；把差异位 is ↔ ed 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pretext 是“借口”，protest 是“抗议”；把差异位 etex ↔ otes 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 excursion 定义为“a journey taken for pleasure”。先抓定义中的 pleasure，再落到中文核心“远足”；词形再钉住辨识块 sion。","basis":"definition"},{"kind":"形近对照","text":"saw 是“锯”，sew 是“缝纫”；把差异位 a ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"inland 是“向内陆”，infant 是“幼儿”；把差异位 land ↔ fant 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"strip 是“条”，strap 是“带子”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 compassion 定义为“a deep awareness of and sympathy for another's suffering”。先抓定义中的 awareness，再落到中文核心“同情”；词形再钉住双写 ss。","basis":"definition"},{"kind":"形近对照","text":"cotton 是“棉花”，coupon 是“优惠券”；把差异位 tt ↔ up 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"cab 是“出租车”，crab 是“螃蟹”；把差异位 a ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“a neutral observer”校准词义：neutral 不是孤立标签，而是在说明“中立的”的状态；回忆时保留完整短词形 neutral。","basis":"usage"},{"kind":"真实语境","text":"真实句“harsh cognac”中，harsh 正在给对象贴上“残酷的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 harsh。","basis":"usage"},{"kind":"真实语境","text":"把 assimilate 放回“Immigrants often want to assimilate quickly”：句中主语做的正是“吸收”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“he stood on a high cliff overlooking the town”中直接圈出 cliff，旁注“悬崖”。句位、场景和词形三者一起回放；词形再钉住双写 ff。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a large entrance or reception room or area”反向定位 lobby：线索词 reception 指向“门厅”。说出中文后再完整看一遍词形；词形再钉住双写 bb。","basis":"definition"},{"kind":"形近对照","text":"suite 是“套房”，spite 是“恶意”；把差异位 u ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"periodical 暂无合适的例句，不编故事。用可核验定义“a publication that appears at fixed intervals”做锚点，把 publication 与“学术期刊”成对回忆；词形用外框 per…cal 定位。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“his body was in rebellion against fatigue”中直接圈出 rebellion，旁注“叛乱”。句位、场景和词形三者一起回放；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"recite 是“背诵”，recipe 是“食谱”；把差异位 t ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 augment 定义为“enlarge or increase”。先抓定义中的 increase，再落到中文核心“扩大”；回忆时保留完整短词形 augment。","basis":"definition"},{"kind":"形近对照","text":"rug 是小地毯，rag 是破布：u 像地毯铺出的弧面，a 像破布破洞；只盯中间元音。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：seminar = “any meeting for an exchange of ideas”。辨识时先提取关键词 exchange，确认核心义“研讨会”；回忆时保留完整短词形 seminar。","basis":"definition"},{"kind":"形近对照","text":"posture 是“姿势”，pasture 是“放牧”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 stationery 定义为“paper cut to an appropriate size for writing letters; usually with matching envelopes”。先抓定义中的 appropriate，再落到中文核心“文具”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"形近对照","text":"rod 是“杆”，rid 是“使摆脱”；把差异位 o ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“Sam cannot charm Sue”中直接圈出 charm，旁注“魅力”。句位、场景和词形三者一起回放；回忆时保留完整短词形 charm。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“he worked at the frontier of brain science”做记忆证据：其中 frontier 承担名词成分，核心就是“边境”。闭眼复述句意后再看词；词形用外框 fro…ier 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“he represented the craft of brewers”给 craft 留的是名词位；把这个位置换成“工艺”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 craft。","basis":"usage"},{"kind":"释义锚点","text":"symmetry 暂无合适的例句，不编故事。用可核验定义“(mathematics) an attribute of a shape or relation; exact reflection of form on opposite sides of a dividing line or plane”做锚点，把 mathematics 与“对称”成对回忆；词形再钉住双写 mm。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“every actor has a portfolio of photographs”中直接圈出 portfolio，旁注“文件夹”。句位、场景和词形三者一起回放；词形用外框 por…lio 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“in retrospect”做记忆证据：其中 retrospect 承担名词成分，核心就是“回顾”。闭眼复述句意后再看词；词形用外框 ret…ect 定位。","basis":"usage"},{"kind":"形近对照","text":"summit 是“最高点”，summon 是“传唤”；把差异位 it ↔ on 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源故事","text":"mort-（死）+ gage（抵押品/承诺）：债务还清或房产被收走时，这份承诺才“死” → mortgage（抵押贷款）。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：virtue = “the quality of doing what is right and avoiding what is wrong”。辨识时先提取关键词 avoiding，确认核心义“德行”；回忆时保留完整短词形 virtue。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“antique furniture”做记忆证据：其中 antique 承担名词成分，核心就是“古物”。闭眼复述句意后再看词；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 bowel 定义为“the part of the alimentary canal between the stomach and the anus”。先抓定义中的 alimentary，再落到中文核心“肠”；回忆时保留完整短词形 bowel。","basis":"definition"},{"kind":"形近对照","text":"rib 是“肋骨”，rid 是“使摆脱”；把差异位 b ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：indignation = “a feeling of righteous anger”。辨识时先提取关键词 righteous，确认核心义“愤慨”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"形近对照","text":"inherit 是“继承”，inhibit 是“妨碍”；把差异位 er ↔ ib 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“grant permission”里，grant 是正在发生的动作；把动作画面直接标成“同意”。以后先演动作，再叫出这个词；回忆时保留完整短词形 grant。","basis":"usage"},{"kind":"真实语境","text":"把 crude 记成“managed to make a crude splint”里的属性标签：它说明对象“粗略的”。看到相同描述位就触发这个词；回忆时保留完整短词形 crude。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：appendix = “supplementary material that is collected and appended at the back of a book”。辨识时先提取关键词 supplementary，确认核心义“附录”；词形再钉住双写 pp。","basis":"definition"},{"kind":"形近对照","text":"bronze 是“青铜”，breeze 是“微风”；把差异位 on ↔ ee 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 repertoire 定义为“the entire range of skills or aptitudes or devices used in a particular field or occupation”。先抓定义中的 particular，再落到中文核心“全部剧目”；词形用外框 rep…ire 定位。","basis":"definition"},{"kind":"真实语境","text":"把 odd 记成“invited 30-odd guests”里的属性标签：它说明对象“古怪的”。看到相同描述位就触发这个词；词形再钉住双写 dd。","basis":"usage"},{"kind":"人名故事","text":"boycott 来自被集体拒绝来往的英国地产代理 Captain Boycott；他的姓直接变成“联合抵制”。","basis":"manual"},{"kind":"形近对照","text":"oak 是“栎树”，oar 是“船桨”；把差异位 k ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"orphan 是“孤儿”，organ 是“器官”；把差异位 ph ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"sibling 暂无合适的例句，不编故事。用可核验定义“a person's brother or sister”做锚点，把 brother 与“兄弟姐妹”成对回忆；回忆时保留完整短词形 sibling。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：auction = “a variety of bridge in which tricks made in excess of the contract are scored toward game; now generally superseded by…”。辨识时先提取关键词 superseded，确认核心义“拍卖”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"形近对照","text":"tangible 是“实际的”，tangle 是“缠结的一团”；把差异位 ib ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"di-/dis-（分开）+ gest（携带、处理）：把食物分解并处理成身体能吸收的部分 → digest（消化）。","basis":"manual"},{"kind":"真实语境","text":"把 sue 放回“They sue to move”：句中主语做的正是“控告”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 sue。","basis":"usage"},{"kind":"形近对照","text":"flare 是“烧旺”，flame 是“火焰”；把差异位 r ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“a vacant expression”校准词义：vacant 不是孤立标签，而是在说明“空的”的状态；回忆时保留完整短词形 vacant。","basis":"usage"},{"kind":"形近对照","text":"staple 是“基本的”，stalk 是“跟踪”；把差异位 ple ↔ lk 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bunch 是“束”，bench 是“长椅”；把差异位 u ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：rude = “socially incorrect in behavior”。辨识时先提取关键词 incorrect，确认核心义“粗鲁的”；回忆时保留完整短词形 rude。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“lubricate my car”。lubricate 在这里推动句子发生，核心动作是“使润滑”；词形用外框 lub…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“may I take your beverage order?”给 beverage 留的是名词位；把这个位置换成“饮料”仍说得通。先复原句中事物，再认词；词形用外框 bev…age 定位。","basis":"usage"},{"kind":"形近对照","text":"feeble 是“无效的”，fable 是“寓言”；把差异位 ee ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"cor-/com-（共同、相互）+ relate（联系）：让两件事互相联系 → correlate（相关、相互关联）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a low woody perennial plant usually having several major stems”反向定位 bush：线索词 perennial 指向“灌木”。说出中文后再完整看一遍词形；回忆时保留完整短词形 bush。","basis":"definition"},{"kind":"形近对照","text":"haste 是“匆忙”，hasty 是“匆忙的”；把差异位 e ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"needle 暂无合适的例句，不编故事。用可核验定义“the leaf of a conifer”做锚点，把 conifer 与“针”成对回忆；词形再钉住双写 ee。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“metal fatigue”中直接圈出 fatigue，旁注“疲惫”。句位、场景和词形三者一起回放；回忆时保留完整短词形 fatigue。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a document attesting to the truth of certain stated facts”反向定位 credential：线索词 attesting 指向“凭证”。说出中文后再完整看一遍词形；词形用外框 cre…ial 定位。","basis":"definition"},{"kind":"形近对照","text":"correspondent 是“记者”，correspondence 是“通信联系”；把差异位 t ↔ ce 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"franchise 暂无合适的例句，不编故事。用可核验定义“an authorization to sell a company's goods or services in a particular place”做锚点，把 authorization 与“特许经营权”成对回忆；词形用外框 fra…ise 定位。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“wax the car”中直接圈出 wax，旁注“蜡”。句位、场景和词形三者一起回放；回忆时保留完整短词形 wax。","basis":"usage"},{"kind":"形近对照","text":"deplore 是“强烈反对”，declare 是“宣布”；把差异位 plo ↔ cla 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“he has a happy disposition”给 disposition 留的是名词位；把这个位置换成“性格”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"形近对照","text":"delicate 是“易受损的”，dedicate 是“致力于”；把差异位 l ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deny 是“否认”，defy 是“违抗”；把差异位 n ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a relatively flat highland”反向定位 plateau：线索词 relatively 指向“高原”。说出中文后再完整看一遍词形；词形再钉住辨识块 eau。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 dwarf 定义为“a person who is markedly small”。先抓定义中的 markedly，再落到中文核心“矮小的”；回忆时保留完整短词形 dwarf。","basis":"definition"},{"kind":"释义锚点","text":"embassy 暂无合适的例句，不编故事。用可核验定义“a diplomatic building where ambassadors live or work”做锚点，把 ambassadors 与“大使馆”成对回忆；词形再钉住双写 ss。","basis":"definition"},{"kind":"形近对照","text":"pope 是“教皇”，pipe 是“管道”；把差异位 o ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"名动统一","text":"cloak 本是披在外面遮住身体的斗篷；动词就是像披斗篷一样把真相遮住 → 遮盖、掩饰。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 porcelain 定义为“ceramic ware made of a more or less translucent ceramic”。先抓定义中的 translucent，再落到中文核心“瓷”；词形用外框 por…ain 定位。","basis":"definition"},{"kind":"真实语境","text":"把 gloomy 记成“the gloomy forest”里的属性标签：它说明对象“昏暗的”。看到相同描述位就触发这个词；词形再钉住双写 oo。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“he's a thorn in my flesh”中直接圈出 thorn，旁注“刺”。句位、场景和词形三者一起回放；回忆时保留完整短词形 thorn。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“empirical laws”校准词义：empirical 不是孤立标签，而是在说明“经验主义的”的状态；词形用外框 emp…cal 定位。","basis":"usage"},{"kind":"真实语境","text":"在真实句“They smuggle the people the food”里，smuggle 是正在发生的动作；把动作画面直接标成“偷运”。以后先演动作，再叫出这个词；词形再钉住双写 gg。","basis":"usage"},{"kind":"真实语境","text":"把 reciprocal 记成“reciprocal aid”里的属性标签：它说明对象“互惠的”。看到相同描述位就触发这个词；词形用外框 rec…cal 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“She asked her older brother to escort her to the ball”中直接圈出 escort，旁注“护卫者”。句位、场景和词形三者一起回放；回忆时保留完整短词形 escort。","basis":"usage"},{"kind":"形近对照","text":"estate 是“庄园”，estimate 是“估计”；把差异位 a ↔ im 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"preclude 是“妨碍”，precede 是“先于”；把差异位 lu ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 bolster 放回“bolster morale”：句中主语做的正是“增强”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 bolster。","basis":"usage"},{"kind":"真实语境","text":"在“hysterical amnesia”里圈出被修饰对象，再把 hysterical 写成中文侧注“歇斯底里的”。对象＋特征一起记；词形用外框 hys…cal 定位。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“They want to drown the prisoners”。drown 在这里推动句子发生，核心动作是“淹没”；回忆时保留完整短词形 drown。","basis":"usage"},{"kind":"形近对照","text":"recession 是“经济衰退”，repression 是“镇压”；把差异位 c ↔ pr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shear 是“剪”，sheer 是“完全的”；把差异位 a ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“shed tears”中直接圈出 shed，旁注“棚屋”。句位、场景和词形三者一起回放；回忆时保留完整短词形 shed。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a dramatic work intended for performance by actors on a stage”反向定位 drama：线索词 performance 指向“戏剧”。说出中文后再完整看一遍词形；回忆时保留完整短词形 drama。","basis":"definition"},{"kind":"形近对照","text":"hip 是“臀部”，hop 是“单脚跳行”；把差异位 i ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 trumpet 固定在真实用法“The birds trumpet in the woods”里：它在句中指向“喇叭”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 trumpet。","basis":"usage"},{"kind":"形近对照","text":"sway 是“摇摆”，swan 是“天鹅”；把差异位 y ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"devise 是“设计”，divine 是“神的”；把差异位 evis ↔ ivin 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“They wedge the books into the box”给 wedge 留的是名词位；把这个位置换成“楔子”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 dge。","basis":"usage"},{"kind":"形近对照","text":"shove 是“猛推”，shore 是“海岸”；把差异位 v ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“The men drag the area for animals”比拆假词根可靠：定位其中的动词 drag，用“拖拽”复述整句；回忆时保留完整短词形 drag。","basis":"usage"},{"kind":"动作对照","text":"hover 不是向前飞，而是停在同一点上方；想象直升机 hover 在空中不落地 → 盘旋、悬停。","basis":"manual"},{"kind":"形近对照","text":"sketch 是“草图”，snatch 是“一把抓起”；把差异位 ke ↔ na 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"forum 暂无合适的例句，不编故事。用可核验定义“a public meeting or assembly for open discussion”做锚点，把 discussion 与“论坛”成对回忆；回忆时保留完整短词形 forum。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“put honesty first in her hierarchy of values”中直接圈出 hierarchy，旁注“等级制度”。句位、场景和词形三者一起回放；词形用外框 hie…chy 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“bar from attention or consideration”反向定位 dismiss：线索词 consideration 指向“不予考虑”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 feudal 定义为“of or relating to or characteristic of feudalism”。先抓定义中的 characteristic，再落到中文核心“封建的”；回忆时保留完整短词形 feudal。","basis":"definition"},{"kind":"形近对照","text":"lid 是“盖子”，lip 是“嘴唇”；把差异位 d ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作场景","text":"alloy 是把不同金属熔在一起形成的新材料；一炉液态金属混合后凝固 → 合金，也可作“掺合”。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“a card shark”做记忆证据：其中 shark 承担名词成分，核心就是“鲨鱼”。闭眼复述句意后再看词；回忆时保留完整短词形 shark。","basis":"usage"},{"kind":"形近对照","text":"ham 是“火腿”，hum 是“哼”；把差异位 a ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"liver 是“肝脏”，liner 是“游轮”；把差异位 v ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：entrepreneur = “someone who organizes a business venture and assumes the risk for it”。辨识时先提取关键词 organizes，确认核心义“企业家”；词形用外框 ent…eur 定位。","basis":"definition"},{"kind":"形近对照","text":"ape 是“猿”，apt 是“恰当的”；把差异位 e ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"短语词源","text":"handicap 来自旧游戏 hand in cap（手放帽中抽签）；后来表示竞赛中的不利条件，再引申为障碍。","basis":"manual"},{"kind":"形近对照","text":"soap 是“肥皂”，slap 是“掌掴”；把差异位 o ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pillar 是“柱子”，pill 是“药丸”；把差异位 ar ↔ pill 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“amplify sound”。amplify 在这里推动句子发生，核心动作是“放大”；回忆时保留完整短词形 amplify。","basis":"usage"},{"kind":"真实语境","text":"真实句“splendid costumes”中，splendid 正在给对象贴上“壮丽的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 spl…did 定位。","basis":"usage"},{"kind":"形近对照","text":"competent 是“胜任的”，complement 是“补充”；把差异位 et ↔ lem 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“an act of ruthless ferocity”里圈出被修饰对象，再把 ruthless 写成中文侧注“残酷的”。对象＋特征一起记；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"sour 是“酸的”，soar 是“暴涨”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“intelligible pronunciation”中，intelligible 正在给对象贴上“可理解的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"corn 是“谷物”，cord 是“粗线”；把差异位 n ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pile 是“摞”，pale 是“苍白的”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"normal + -ize（使成为）+ -ation（过程）：使之正常的过程 → 正常化；英式也写 normalisation。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 hospitality 定义为“kindness in welcoming guests or strangers”。先抓定义中的 welcoming，再落到中文核心“殷勤款待”；词形用外框 hos…ity 定位。","basis":"definition"},{"kind":"形近对照","text":"spear 是“矛”，shear 是“剪”；把差异位 p ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“a huddle of frightened women”比拆假词根可靠：定位其中的动词 huddle，用“挤在一起”复述整句；词形再钉住双写 dd。","basis":"usage"},{"kind":"词根链","text":"demo-（人口、人民）+ graph（记录、描述）+ -ic：描述人口构成的 → demographic（人口统计的）。","basis":"manual"},{"kind":"真实语境","text":"真实句“the tragic spectacle of cripples trying to escape”给 spectacle 留的是名词位；把这个位置换成“壮观的景象”仍说得通。先复原句中事物，再认词；词形用外框 spe…cle 定位。","basis":"usage"},{"kind":"真实语境","text":"把 awful 记成“an awful voice”里的属性标签：它说明对象“糟糕的”。看到相同描述位就触发这个词；回忆时保留完整短词形 awful。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“They wrinkle the sheets”中直接圈出 wrinkle，旁注“皱纹”。句位、场景和词形三者一起回放；词形再钉住辨识块 wr。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“a ship in distress”做记忆证据：其中 distress 承担名词成分，核心就是“忧虑”。闭眼复述句意后再看词；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"fuse 是“融合”，fume 是“恼火”；把差异位 s ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 loyal 记成“loyal subjects”里的属性标签：它说明对象“忠诚的”。看到相同描述位就触发这个词；回忆时保留完整短词形 loyal。","basis":"usage"},{"kind":"形近对照","text":"fright 是“惊吓”，freight 是“运送”；把差异位 i ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a railcar where passengers ride”反向定位 carriage：线索词 passengers 指向“火车车厢”。说出中文后再完整看一遍词形；词形再钉住双写 rr。","basis":"definition"},{"kind":"形近对照","text":"dose 是“一份”，dove 是“鸽子”；把差异位 s ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"vulgar 暂无合适的例句，不编故事。用可核验定义“lacking refinement or cultivation or taste”做锚点，把 cultivation 与“粗俗的”成对回忆；回忆时保留完整短词形 vulgar。","basis":"definition"},{"kind":"真实语境","text":"真实用法“there's a drip through the roof”比拆假词根可靠：定位其中的动词 drip，用“滴下”复述整句；回忆时保留完整短词形 drip。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“go on board”反向定位 embark：线索词 board 指向“上船”。说出中文后再完整看一遍词形；回忆时保留完整短词形 embark。","basis":"definition"},{"kind":"形近对照","text":"spur 是“激励”，sour 是“酸的”；把差异位 p ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"sob 暂无合适的例句，不编故事。用可核验定义“weep convulsively”做锚点，把 convulsively 与“哭泣”成对回忆；回忆时保留完整短词形 sob。","basis":"definition"},{"kind":"形近对照","text":"soak 是“浸泡”，soap 是“肥皂”；把差异位 k ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"portrait 是“肖像”，portray 是“描绘”；把差异位 it ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"ex-（向外）+ pel/puls（推）：把人向外推出组织或学校 → expel（开除、驱逐）。","basis":"manual"},{"kind":"释义锚点","text":"penetrate 暂无合适的例句，不编故事。用可核验定义“pass into or through, often by overcoming resistance”做锚点，把 overcoming 与“穿过”成对回忆；词形用外框 pen…ate 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：epoch = “a period marked by distinctive character or reckoned from a fixed point or event”。辨识时先提取关键词 distinctive，确认核心义“时代”；回忆时保留完整短词形 epoch。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“commence officially”反向定位 inaugurate：线索词 officially 指向“为…举行就职典礼”。说出中文后再完整看一遍词形；词形用外框 ina…ate 定位。","basis":"definition"},{"kind":"形近对照","text":"steam 是“蒸气”，steak 是“牛排”；把差异位 m ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 allege 放回“They allege that there was a traffic accident”：句中主语做的正是“断言”。先抓施事者与动作，再提取词形；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"paw 是“爪子”，pad 是“衬垫”；把差异位 w ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he built a modest dwelling near the pond”做记忆证据：其中 dwelling 承担名词成分，核心就是“住宅”。闭眼复述句意后再看词；词形再钉住双写 ll。","basis":"usage"},{"kind":"形近对照","text":"lip 是“嘴唇”，lid 是“盖子”；把差异位 p ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"liner 是“游轮”，linen 是“亚麻布”；把差异位 r ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"linen 是“亚麻布”，liner 是“游轮”；把差异位 n ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a legislative assembly in certain countries”反向定位 parliament：线索词 legislative 指向“议会”。说出中文后再完整看一遍词形；词形用外框 par…ent 定位。","basis":"definition"},{"kind":"真实语境","text":"在真实句“tended to romanticize and exaggerate this ‘gracious Old South’ imagery”里，exaggerate 是正在发生的动作；把动作画面直接标成“夸大”。以后先演动作，再叫出这个词；词形再钉住双写 gg。","basis":"usage"},{"kind":"真实语境","text":"把 diet 固定在真实用法“He has high blood pressure and must stick to a low-salt diet”里：它在句中指向“日常饮食”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 diet。","basis":"usage"},{"kind":"形近对照","text":"fume 是“恼火”，fuse 是“融合”；把差异位 m ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"con-（共同）+ tag/tact（接触）+ -ious：通过人与人接触传播 → contagious（接触传染的）。","basis":"manual"},{"kind":"真实语境","text":"真实句“They storm the hill”给 storm 留的是名词位；把这个位置换成“暴风雨”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 storm。","basis":"usage"},{"kind":"形近对照","text":"scratch 是“抓”，stretch 是“撑大”；把差异位 cra ↔ tre 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deaf 是“聋的”，dean 是“院长”；把差异位 f ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"straw 是“稻草”，strap 是“带子”；把差异位 w ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 queer 定义为“beyond or deviating from the usual or expected”。先抓定义中的 deviating，再落到中文核心“异常的”；词形再钉住双写 ee。","basis":"definition"},{"kind":"形近对照","text":"snap 是“断裂”，slap 是“掌掴”；把差异位 n ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：fable = “a deliberately false or improbable account”。辨识时先提取关键词 deliberately，确认核心义“寓言”；回忆时保留完整短词形 fable。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“we won a chunk of money”做记忆证据：其中 chunk 承担名词成分，核心就是“相当大的数量”。闭眼复述句意后再看词；回忆时保留完整短词形 chunk。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 plumber 定义为“a craftsman who installs and repairs pipes and fixtures and appliances”。先抓定义中的 appliances，再落到中文核心“管道工”；回忆时保留完整短词形 plumber。","basis":"definition"},{"kind":"形近对照","text":"conceive 是“想象”，contrive 是“设法做到”；把差异位 ce ↔ tr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dam 是“水坝”，dim 是“暗淡的”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sheer 是“完全的”，shear 是“剪”；把差异位 e ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“subtract this amount from my paycheck”里，subtract 是正在发生的动作；把动作画面直接标成“减去”。以后先演动作，再叫出这个词；词形用外框 sub…act 定位。","basis":"usage"},{"kind":"形近对照","text":"tilt 是“倾斜”，tile 是“瓷砖”；把差异位 t ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“stimulated a surge of speculation”中直接圈出 surge，旁注“突发”。句位、场景和词形三者一起回放；回忆时保留完整短词形 surge。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“a noble and lofty concept”校准词义：lofty 不是孤立标签，而是在说明“高耸的”的状态；回忆时保留完整短词形 lofty。","basis":"usage"},{"kind":"形近对照","text":"concession 是“让步”，conversion 是“转变”；把差异位 ces ↔ ver 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"feasible 暂无合适的例句，不编故事。用可核验定义“capable of being done with means at hand and circumstances as they are”做锚点，把 circumstances 与“可行的”成对回忆；词形用外框 fea…ble 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：oven = “kitchen appliance used for baking or roasting”。辨识时先提取关键词 appliance，确认核心义“烤箱”；回忆时保留完整短词形 oven。","basis":"definition"},{"kind":"词族链","text":"ready（准备好的、随时可做）+ -ly：已经准备好，所以能立刻、欣然、容易地去做 → readily。","basis":"manual"},{"kind":"形状直记","text":"disc 就是一块扁平圆盘；想象唱片或光盘的圆形轮廓。英式多写 disc，计算机磁盘常见 disk。","basis":"manual"},{"kind":"真实语境","text":"把 benign 记成“a benign smile”里的属性标签：它说明对象“和善的”。看到相同描述位就触发这个词；回忆时保留完整短词形 benign。","basis":"usage"},{"kind":"形近对照","text":"mercury 是“水星”，mercy 是“仁慈”；把差异位 ur ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"metal 是“金属”，medal 是“奖章”；把差异位 t ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“a benevolent society”中，benevolent 正在给对象贴上“仁慈的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 ben…ent 定位。","basis":"usage"},{"kind":"形近对照","text":"avert 是“防止”，alert 是“机敏的”；把差异位 v ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：bacteria = “(microbiology) single-celled or noncellular spherical or spiral or rod-shaped organisms lacking chlorophyll that reproduce…”。辨识时先提取关键词 single-celled，确认核心义“细菌”；词形用外框 bac…ria 定位。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“fleet of foot”做记忆证据：其中 fleet 承担名词成分，核心就是“舰队”。闭眼复述句意后再看词；词形再钉住双写 ee。","basis":"usage"},{"kind":"真实语境","text":"真实句“They want to massacre the prisoners”给 massacre 留的是名词位；把这个位置换成“大屠杀”仍说得通。先复原句中事物，再认词；词形再钉住双写 ss。","basis":"usage"},{"kind":"释义锚点","text":"beer 暂无合适的例句，不编故事。用可核验定义“a general name for alcoholic beverages made by fermenting a cereal (or mixture of cereals) flavored with hops”做锚点，把 fermenting 与“啤酒”成对回忆；词形再钉住双写 ee。","basis":"definition"},{"kind":"真实语境","text":"在“the oak is implicit in the acorn”里圈出被修饰对象，再把 implicit 写成中文侧注“含蓄的”。对象＋特征一起记；词形用外框 imp…cit 定位。","basis":"usage"},{"kind":"形近对照","text":"thrift 是“节约”，tariff 是“关税”；把差异位 hrift ↔ ariff 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"拟声钩子","text":"cock 源自模仿公鸡叫声的词；cock-a-doodle-doo 一响就锁定“公鸡”。机械开关等义项来自公鸡抬头的形状。","basis":"manual"},{"kind":"概念画面","text":"hybrid 的核心是把两个不同来源接到一起；一半 A、一半 B 的后代或系统 → 杂交的、混合的。","basis":"manual"},{"kind":"形近对照","text":"barrel 是“桶”，barren 是“贫瘠的”；把差异位 l ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“The meadows moan with animals”。moan 在这里推动句子发生，核心动作是“呻吟”；回忆时保留完整短词形 moan。","basis":"usage"},{"kind":"真实语境","text":"真实句“a jealous lover”中，jealous 正在给对象贴上“忌恨的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 jealous。","basis":"usage"},{"kind":"词族链","text":"mission（被派出的任务）+ -ary（从事者）：被派出去执行宗教使命的人 → missionary（传教士）。","basis":"manual"},{"kind":"形近对照","text":"ritual 是“仪式”，rival 是“竞争者”；把差异位 tu ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"summon 是“传唤”，summit 是“最高点”；把差异位 on ↔ it 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 monarch 定义为“a nation's ruler or head of state usually by hereditary right”。先抓定义中的 hereditary，再落到中文核心“君主”；回忆时保留完整短词形 monarch。","basis":"definition"},{"kind":"真实语境","text":"把 adjacent 记成“had adjacent rooms”里的属性标签：它说明对象“毗连的”。看到相同描述位就触发这个词；词形用外框 adj…ent 定位。","basis":"usage"},{"kind":"词根链","text":"pre-（在前）+ ced/ceed（走）：走在另一件事前面 → precede（先于）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“rectangular block of clay baked by the sun or in a kiln; used as a building or paving material”反向定位 brick：线索词 rectangular 指向“砖块”。说出中文后再完整看一遍词形；回忆时保留完整短词形 brick。","basis":"definition"},{"kind":"形近对照","text":"confine 是“限制”，concise 是“简洁的”；把差异位 fin ↔ cis 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ashore 是“在岸上”，adhere 是“黏附”；把差异位 sho ↔ dhe 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"instinct 是“直觉”，instant 是“立即的”；把差异位 inc ↔ an 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"apt 是“恰当的”，ape 是“猿”；把差异位 t ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“The men restore the chairs”里，restore 是正在发生的动作；把动作画面直接标成“使复原”。以后先演动作，再叫出这个词；回忆时保留完整短词形 restore。","basis":"usage"},{"kind":"真实语境","text":"把 gasp 放回“she gave a gasp and fainted”：句中主语做的正是“喘息”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 gasp。","basis":"usage"},{"kind":"形近对照","text":"abound 是“大量存在”，absurd 是“荒谬的”；把差异位 oun ↔ sur 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"混成词","text":"motel = motor + hotel：专给开车旅行者住的 hotel → 汽车旅馆。两个母词直接解释了用途。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 germ 定义为“anything that provides inspiration for later work”。先抓定义中的 inspiration，再落到中文核心“细菌”；回忆时保留完整短词形 germ。","basis":"definition"},{"kind":"真实语境","text":"把 zeal 固定在真实用法“he felt a kind of religious zeal”里：它在句中指向“热情”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 zeal。","basis":"usage"},{"kind":"形近对照","text":"thunder 是“雷声”，tender 是“温柔的”；把差异位 hu ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“he could not suppress a yawn”。yawn 在这里推动句子发生，核心动作是“打哈欠”；回忆时保留完整短词形 yawn。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 glue 定义为“cement consisting of a sticky substance that is used as an adhesive”。先抓定义中的 consisting，再落到中文核心“胶”；回忆时保留完整短词形 glue。","basis":"definition"},{"kind":"真实语境","text":"把 timid 记成“problems that call for bold not timid responses”里的属性标签：它说明对象“羞怯的”。看到相同描述位就触发这个词；回忆时保留完整短词形 timid。","basis":"usage"},{"kind":"真实语境","text":"在“gracious living”里圈出被修饰对象，再把 gracious 写成中文侧注“和蔼慈祥的”。对象＋特征一起记；词形用外框 gra…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"robe 是“长袍”，rose 是“玫瑰花”；把差异位 b ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"seal 是“封住”，seam 是“接缝”；把差异位 l ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"wagon 暂无合适的例句，不编故事。用可核验定义“any of various kinds of wheeled vehicles drawn by an animal or a tractor”做锚点，把 vehicles 与“运货车”成对回忆；回忆时保留完整短词形 wagon。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：spectator = “a close observer; someone who looks at something (such as an exhibition of some kind)”。辨识时先提取关键词 exhibition，确认核心义“观众”；词形用外框 spe…tor 定位。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“The children stagger to the playground”。stagger 在这里推动句子发生，核心动作是“蹒跚”；词形再钉住双写 gg。","basis":"usage"},{"kind":"形近对照","text":"regime 是“政权”，recipe 是“食谱”；把差异位 gim ↔ cip 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作画面","text":"clasp 的 cl- 像合拢、-asp 像扣住；两端咔哒合在一起 → 搭扣，也可作“紧握”。","basis":"manual"},{"kind":"词族链","text":"penal（刑罚的）+ -ty（状态/结果）：违规后承担的处罚或罚金 → penalty。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“Google represents a new breed of entrepreneurs”做记忆证据：其中 breed 承担名词成分，核心就是“品种”。闭眼复述句意后再看词；词形再钉住双写 ee。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 tutor 定义为“a person who gives private instruction (as in singing, acting, etc.)”。先抓定义中的 instruction，再落到中文核心“家庭教师”；回忆时保留完整短词形 tutor。","basis":"definition"},{"kind":"真实语境","text":"把 sacred 记成“sacred texts”里的属性标签：它说明对象“神圣的”。看到相同描述位就触发这个词；回忆时保留完整短词形 sacred。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：hatred = “the emotion of intense dislike; a feeling of dislike so strong that it demands action”。辨识时先提取关键词 emotion，确认核心义“憎恨”；回忆时保留完整短词形 hatred。","basis":"definition"},{"kind":"形近对照","text":"triangle 是“三角形”，tangle 是“缠结的一团”；把差异位 ri ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"horror 是“惊恐”，harbor 是“海港”；把差异位 orr ↔ arb 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dedicate 是“致力于”，delicate 是“易受损的”；把差异位 d ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“nickel the plate”中直接圈出 nickel，旁注“镍”。句位、场景和词形三者一起回放；回忆时保留完整短词形 nickel。","basis":"usage"},{"kind":"形近对照","text":"scrap 是“碎片”，strap 是“带子”；把差异位 c ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“a neat room”中，neat 正在给对象贴上“整洁的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 neat。","basis":"usage"},{"kind":"真实语境","text":"把 hose 固定在真实用法“hose the lawn”里：它在句中指向“软管”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 hose。","basis":"usage"},{"kind":"真实语境","text":"真实用法“Sam and Sue mutter”比拆假词根可靠：定位其中的动词 mutter，用“嘀咕”复述整句；词形再钉住双写 tt。","basis":"usage"},{"kind":"词族链","text":"refrigerate（使冷却）+ -or（装置）：持续把食物冷却的装置 → refrigerator（冰箱）。","basis":"manual"},{"kind":"形近对照","text":"advent 是“来临”，accent 是“重音”；把差异位 dv ↔ cc 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 headquarters 固定在真实用法“many companies have their headquarters in New York”里：它在句中指向“司令部”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“the acquisition of wealth”中直接圈出 acquisition，旁注“获得”。句位、场景和词形三者一起回放；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“drinking alcohol is a health hazard”做记忆证据：其中 hazard 承担名词成分，核心就是“危险”。闭眼复述句意后再看词；回忆时保留完整短词形 hazard。","basis":"usage"},{"kind":"形近对照","text":"copper 是“铜”，compel 是“强迫”；把差异位 pper ↔ mpel 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"botan- 在希腊语里指植物、草木；研究植物的学科 → botany（植物学）。","basis":"manual"},{"kind":"形近对照","text":"propel 是“推动”，probe 是“探查”；把差异位 pel ↔ be 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tuck 是“把…塞进”，truck 是“卡车”；把差异位 u ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“the benefits are cumulative”中，cumulative 正在给对象贴上“聚积的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 cum…ive 定位。","basis":"usage"},{"kind":"真实语境","text":"把 towel 固定在真实用法“towel your hair dry”里：它在句中指向“毛巾”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 towel。","basis":"usage"},{"kind":"形近对照","text":"carve 是“雕刻”，curve 是“曲线”；把差异位 a ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“an animal with a very sensitive aural apparatus”校准词义：aural 不是孤立标签，而是在说明“听觉的”的状态；回忆时保留完整短词形 aural。","basis":"usage"},{"kind":"形近对照","text":"compel 是“强迫”，comply 是“遵从”；把差异位 el ↔ ly 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"bound 在这里取“界限”义（不是 be bound to 的“必然”）+ -ary：界限所在之处 → boundary（边界）。","basis":"manual"},{"kind":"真实语境","text":"不要硬编词根：在“the pleasure of his company”中直接圈出 pleasure，旁注“快乐”。句位、场景和词形三者一起回放；词形用外框 ple…ure 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“a schoolgirl fantasy”做记忆证据：其中 fantasy 承担名词成分，核心就是“幻想”。闭眼复述句意后再看词；回忆时保留完整短词形 fantasy。","basis":"usage"},{"kind":"真实语境","text":"真实句“a pedestrian movie plot”中，pedestrian 正在给对象贴上“行人的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 ped…ian 定位。","basis":"usage"},{"kind":"真实语境","text":"把 disturb 放回“Sam cannot disturb Sue”：句中主语做的正是“打扰”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 disturb。","basis":"usage"},{"kind":"形近对照","text":"wary 是“小心的”，ward 是“病房”；把差异位 y ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“flow back or recede”反向定位 ebb：线索词 recede 指向“退潮”。说出中文后再完整看一遍词形；词形再钉住双写 bb。","basis":"definition"},{"kind":"形近对照","text":"bark 是“吠叫”，barn 是“谷仓”；把差异位 k ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 spontaneous 记成“spontaneous laughter”里的属性标签：它说明对象“自然的”。看到相同描述位就触发这个词；词形用外框 spo…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"van 是“货车”，vain 是“徒劳的”；把差异位 n ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“a vulnerable bridge”校准词义：vulnerable 不是孤立标签，而是在说明“易受伤害的”的状态；词形用外框 vul…ble 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 diagram 定义为“a drawing intended to explain how something works; a drawing showing the relation between the parts”。先抓定义中的 intended，再落到中文核心“图解”；回忆时保留完整短词形 diagram。","basis":"definition"},{"kind":"释义锚点","text":"query 暂无合适的例句，不编故事。用可核验定义“an instance of questioning”做锚点，把 questioning 与“疑问”成对回忆；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"动作画面","text":"plug 是塞进孔里的塞子；电源插头也是把凸出的部分塞进插孔 → 插头、塞住。用“塞入”统一多义。","basis":"manual"},{"kind":"形近对照","text":"venture 是“冒险去”，venue 是“举办场所”；把差异位 tur ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源故事","text":"pamphlet 来自中世纪流行的小册诗 Pamphilus；篇幅小、便于传阅，词义固定为“小册子”。","basis":"manual"},{"kind":"形近对照","text":"strand 是“股”，strap 是“带子”；把差异位 nd ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“tissue textiles”中直接圈出 tissue，旁注“组织”。句位、场景和词形三者一起回放；词形再钉住双写 ss。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“They overhear that there was a traffic accident”。overhear 在这里推动句子发生，核心动作是“偶然听到”；词形再钉住辨识块 rh。","basis":"usage"},{"kind":"形近对照","text":"cop 是“警察”，chop 是“砍”；把差异位 o ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"opt（选择）+ -ion（选择的结果）+ -al（……的）：可以由你选择的 → optional（可选的）。","basis":"manual"},{"kind":"真实语境","text":"真实用法“fling the frisbee”比拆假词根可靠：定位其中的动词 fling，用“扔”复述整句；回忆时保留完整短词形 fling。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“flow or run over (a limit or brim)”反向定位 overflow：线索词 limit 指向“溢出”。说出中文后再完整看一遍词形；词形用外框 ove…low 定位。","basis":"definition"},{"kind":"真实语境","text":"在真实句“They anticipate moving”里，anticipate 是正在发生的动作；把动作画面直接标成“预料”。以后先演动作，再叫出这个词；词形用外框 ant…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"voltage 暂无合适的例句，不编故事。用可核验定义“the rate at which energy is drawn from a source that produces a flow of electricity in a circuit; expressed in volts”做锚点，把 electricity 与“电压”成对回忆；回忆时保留完整短词形 voltage。","basis":"definition"},{"kind":"形近对照","text":"reel 是“卷筒”，reed 是“芦苇”；把差异位 l ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a way of regarding situations or topics etc.”反向定位 perspective：线索词 situations 指向“视角”。说出中文后再完整看一遍词形；词形用外框 per…ive 定位。","basis":"definition"},{"kind":"形近对照","text":"transient 是“短暂的”，transcend 是“超出”；把差异位 ient ↔ cend 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 gratitude 固定在真实用法“he was overwhelmed with gratitude for their help”里：它在句中指向“感激”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 gra…ude 定位。","basis":"usage"},{"kind":"真实语境","text":"真实用法“They withhold the money”比拆假词根可靠：定位其中的动词 withhold，用“拒绝给”复述整句；词形再钉住双写 hh。","basis":"usage"},{"kind":"形近对照","text":"carbon 是“碳”，cannon 是“大炮”；把差异位 rb ↔ nn 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“aesthetic feeling”中，aesthetic 正在给对象贴上“美学的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 aes…tic 定位。","basis":"usage"},{"kind":"形近对照","text":"rid 是“使摆脱”，rib 是“肋骨”；把差异位 d ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：wicked = “morally bad in principle or practice”。辨识时先提取关键词 principle，确认核心义“邪恶的”；回忆时保留完整短词形 wicked。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a feminine ending”校准词义：feminine 不是孤立标签，而是在说明“女性的”的状态；词形用外框 fem…ine 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“a notorious gangster”中，notorious 正在给对象贴上“臭名昭著的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 not…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"despise 是“轻视”，dispose 是“安排”；把差异位 espi ↔ ispo 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“a spray of bullets”中直接圈出 spray，旁注“浪花”。句位、场景和词形三者一起回放；回忆时保留完整短词形 spray。","basis":"usage"},{"kind":"形近对照","text":"scarcely 是“刚刚”，scarce 是“缺乏的”；把差异位 ly ↔ scarce 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“The children kneel in the rocking chair”里，kneel 是正在发生的动作；把动作画面直接标成“跪下”。以后先演动作，再叫出这个词；词形再钉住双写 ee。","basis":"usage"},{"kind":"真实语境","text":"把 perceive 放回“I could perceive the ship coming over the horizon”：句中主语做的正是“意识到”。先抓施事者与动作，再提取词形；词形用外框 per…ive 定位。","basis":"usage"},{"kind":"形近对照","text":"pound 是“英镑”，pond 是“池塘”；把差异位 u ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he had doubts about the whole enterprise”做记忆证据：其中 enterprise 承担名词成分，核心就是“企业”。闭眼复述句意后再看词；词形用外框 ent…ise 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 slight 定义为“(quantifier used with mass nouns) small in quantity or degree; not much or almost none or (with ‘a’) at least some”。先抓定义中的 quantifier，再落到中文核心“少量的”；词形再钉住辨识块 ght。","basis":"definition"},{"kind":"释义锚点","text":"candidate 暂无合适的例句，不编故事。用可核验定义“a politician who is running for public office”做锚点，把 politician 与“申请人”成对回忆；词形用外框 can…ate 定位。","basis":"definition"},{"kind":"真实语境","text":"真实用法“haul nets”比拆假词根可靠：定位其中的动词 haul，用“拖”复述整句；回忆时保留完整短词形 haul。","basis":"usage"},{"kind":"语气钩子","text":"in earnest 表示不是玩笑、而是当真；由“当真”锁定 earnest（认真的、诚恳的）。","basis":"manual"},{"kind":"形近对照","text":"propose 是“提出”，proposal 是“提议”；把差异位 e ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"thrust 是“猛推”，thrift 是“节约”；把差异位 us ↔ if 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：fairy = “a small being, human in form, playful and having magical powers”。辨识时先提取关键词 playful，确认核心义“小仙子”；回忆时保留完整短词形 fairy。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“numerical value”校准词义：numerical 不是孤立标签，而是在说明“数字的”的状态；词形用外框 num…cal 定位。","basis":"usage"},{"kind":"形近对照","text":"defect 是“缺点”，deceit 是“欺骗”；把差异位 fec ↔ cei 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deed 是“行为”，deer 是“鹿”；把差异位 d ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：elicit = “call forth (emotions, feelings, and responses)”。辨识时先提取关键词 responses，确认核心义“引出”；回忆时保留完整短词形 elicit。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“reason by deduction; establish by deduction”反向定位 deduce：线索词 deduction 指向“推论”。说出中文后再完整看一遍词形；回忆时保留完整短词形 deduce。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 senate 定义为“assembly possessing high legislative powers”。先抓定义中的 legislative，再落到中文核心“参议院”；回忆时保留完整短词形 senate。","basis":"definition"},{"kind":"容器画面","text":"bucket 的 -ket 像提手扣在桶口；抓住上方把手提起一个深容器 → 桶。此条是形状联想。","basis":"manual"},{"kind":"形近对照","text":"punish 是“惩罚”，perish 是“死亡”；把差异位 un ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"fund 是“基金”，fond 是“喜爱的”；把差异位 u ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ascend 是“上升”，accent 是“重音”；把差异位 scend ↔ ccent 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"diploma 暂无合适的例句，不编故事。用可核验定义“a document certifying the successful completion of a course of study”做锚点，把 certifying 与“毕业文凭”成对回忆；回忆时保留完整短词形 diploma。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“he had an intuition that something had gone wrong”中直接圈出 intuition，旁注“直觉”。句位、场景和词形三者一起回放；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“an assurance of help when needed”做记忆证据：其中 assurance 承担名词成分，核心就是“担保”。闭眼复述句意后再看词；词形再钉住双写 ss。","basis":"usage"},{"kind":"英美拼写","text":"cheque 是英式“支票”，美式写 check；银行把 check 扩写成更法语化的 cheque，盯住结尾 -que。","basis":"manual"},{"kind":"词根链","text":"dia-（分开、透彻）+ gnos（知道、识别）：把症状逐项分开看清并识别疾病 → diagnose（诊断）。","basis":"manual"},{"kind":"形近对照","text":"deck 是“甲板”，dock 是“码头”；把差异位 e ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“They reap rye in the field”。reap 在这里推动句子发生，核心动作是“获得”；回忆时保留完整短词形 reap。","basis":"usage"},{"kind":"形近对照","text":"convention 是“习俗”，conversion 是“转变”；把差异位 nt ↔ rs 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"lavatory 暂无合适的例句，不编故事。用可核验定义“a room or building equipped with one or more toilets”做锚点，把 building 与“厕所”成对回忆；词形用外框 lav…ory 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：redeem = “save from sins”。辨识时先提取关键词 save，确认核心义“弥补”；词形再钉住双写 ee。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a bankrupt company”校准词义：bankrupt 不是孤立标签，而是在说明“破产的”的状态；词形用外框 ban…upt 定位。","basis":"usage"},{"kind":"形近对照","text":"intact 是“完好无损的”，infant 是“幼儿”；把差异位 tac ↔ fan 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 anonymous 记成“anonymous donors”里的属性标签：它说明对象“匿名的”。看到相同描述位就触发这个词；词形用外框 ano…ous 定位。","basis":"usage"},{"kind":"真实语境","text":"真实用法“Sam and Sue mourn”比拆假词根可靠：定位其中的动词 mourn，用“悲伤”复述整句；回忆时保留完整短词形 mourn。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a woman of refinement”反向定位 madam：线索词 refinement 指向“夫人”。说出中文后再完整看一遍词形；回忆时保留完整短词形 madam。","basis":"definition"},{"kind":"真实语境","text":"真实句“frost a cake”给 frost 留的是名词位；把这个位置换成“霜”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 frost。","basis":"usage"},{"kind":"释义锚点","text":"landlord 暂无合适的例句，不编故事。用可核验定义“a landowner who leases to others”做锚点，把 landowner 与“房东”成对回忆；词形用外框 lan…ord 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：bibliography = “a list of writings with time and place of publication (such as the writings of a single author or the works referred to in…”。辨识时先提取关键词 publication，确认核心义“系列书目”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"形近对照","text":"stipulate 是“规定”，stimulate 是“促进”；把差异位 p ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"dawn 是“黎明”，damn 是“批评”；把差异位 w ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"curl 是“卷曲”，curb 是“把事物限制在边界内”；把差异位 l ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"medal 是“奖章”，metal 是“金属”；把差异位 d ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"复合词","text":"out + skirts（边缘）：像裙边围在城市最外圈的地区 → outskirts（郊区、外围）。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 wheat 定义为“annual or biennial grass having erect flower spikes and light brown grains”。先抓定义中的 biennial，再落到中文核心“小麦”；回忆时保留完整短词形 wheat。","basis":"definition"},{"kind":"形近对照","text":"counsel 是“律师”，council 是“议会”；把差异位 se ↔ ci 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"receive（接收）对应的名词角色是 recipient；共同的 reci-/recei- 提醒你这是“接受者”。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a precious or semiprecious stone incorporated into a piece of jewelry”反向定位 jewel：线索词 semiprecious 指向“宝石”。说出中文后再完整看一遍词形；回忆时保留完整短词形 jewel。","basis":"definition"},{"kind":"真实语境","text":"真实句“arrogant claims”中，arrogant 正在给对象贴上“傲慢的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 rr。","basis":"usage"},{"kind":"真实语境","text":"把 obstruct 放回“obstruct the path”：句中主语做的正是“阻挡”。先抓施事者与动作，再提取词形；词形用外框 obs…uct 定位。","basis":"usage"},{"kind":"形近对照","text":"reign 是“统治期”，rein 是“缰绳”；把差异位 g ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“mineral elements”做记忆证据：其中 mineral 承担名词成分，核心就是“矿物”。闭眼复述句意后再看词；回忆时保留完整短词形 mineral。","basis":"usage"},{"kind":"动作统一","text":"clip 的核心动作是快速夹住或剪掉；回形针夹住纸，剪刀 clip 掉一小段 → 夹子、修剪。","basis":"manual"},{"kind":"释义锚点","text":"owl 暂无合适的例句，不编故事。用可核验定义“nocturnal bird of prey with hawk-like beak and claws and large head with front-facing eyes”做锚点，把 front-facing 与“猫头鹰”成对回忆；回忆时保留完整短词形 owl。","basis":"definition"},{"kind":"形近对照","text":"sustain 是“保持”，stain 是“弄脏”；把差异位 us ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“flour fish or meat before frying it”做记忆证据：其中 flour 承担名词成分，核心就是“面粉”。闭眼复述句意后再看词；回忆时保留完整短词形 flour。","basis":"usage"},{"kind":"真实语境","text":"真实句“he climbed the career ladder”给 ladder 留的是名词位；把这个位置换成“梯子”仍说得通。先复原句中事物，再认词；词形再钉住双写 dd。","basis":"usage"},{"kind":"词义沿革","text":"rare 早期有“稀疏、数量少”的意思；数量少到不常遇见 → 稀有的。食物“半熟”是另一条同形义。","basis":"manual"},{"kind":"形近对照","text":"knot 是“结”，knit 是“编织”；把差异位 o ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“become ground down or deteriorate”反向定位 erode：线索词 deteriorate 指向“侵蚀”。说出中文后再完整看一遍词形；回忆时保留完整短词形 erode。","basis":"definition"},{"kind":"真实语境","text":"真实句“a swift current”中，swift 正在给对象贴上“迅速的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 swift。","basis":"usage"},{"kind":"释义锚点","text":"worm 暂无合适的例句，不编故事。用可核验定义“any of numerous relatively small elongated soft-bodied animals especially of the phyla Annelida and Chaetognatha and…”做锚点，把 chaetognatha 与“蠕虫”成对回忆；回忆时保留完整短词形 worm。","basis":"definition"},{"kind":"形近对照","text":"refine 是“精炼”，recipe 是“食谱”；把差异位 fin ↔ cip 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"flame 是“火焰”，flare 是“烧旺”；把差异位 m ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"radiant 是“容光焕发的”，radiate 是“辐射”；把差异位 nt ↔ te 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 sympathetic 记成“sympathetic neurons”里的属性标签：它说明对象“同情的”。看到相同描述位就触发这个词；词形用外框 sym…tic 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“They shampoo their hair”中直接圈出 shampoo，旁注“洗发水”。句位、场景和词形三者一起回放；词形再钉住双写 oo。","basis":"usage"},{"kind":"形近对照","text":"flow 是“流动”，flaw 是“错误”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"surgery 是“外科”，surge 是“突发”；把差异位 ry ↔ surge 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 landscape 固定在真实用法“Let's landscape the yard”里：它在句中指向“风景”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 lan…ape 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：contradict = “be in contradiction with”。辨识时先提取关键词 contradiction，确认核心义“反驳”；词形用外框 con…ict 定位。","basis":"definition"},{"kind":"形状画面","text":"slot 是细长的开口；硬币沿窄缝滑进去，也可指安排表中的一个时间格 → 窄缝、时段。","basis":"manual"},{"kind":"形近对照","text":"correspondence 是“通信联系”，correspondent 是“记者”；把差异位 ce ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"transit 是“过境”，trait 是“特征”；把差异位 ns ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"found 在“创办”义上来自 foundation（地基）：先打地基，再把机构建立起来 → 创办。不要与 find 的过去式 found 混。","basis":"manual"},{"kind":"词族链","text":"rely（依靠、信赖）变 y 为 i 再加 -ance（状态）：依靠的状态 → reliance（信赖、依赖）。","basis":"manual"},{"kind":"形近对照","text":"racket 是“喧哗”，rake 是“耙子”；把差异位 cket ↔ ke 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"deficit 是“赤字”，defect 是“缺点”；把差异位 ici ↔ ec 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“The bad news will anguish him”中直接圈出 anguish，旁注“极度痛苦”。句位、场景和词形三者一起回放；回忆时保留完整短词形 anguish。","basis":"usage"},{"kind":"形近对照","text":"accent 是“重音”，advent 是“来临”；把差异位 cc ↔ dv 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"skim 是“浏览”，slim 是“苗条的”；把差异位 k ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"racial 是“种族的”，radical 是“根本的”；把差异位 ci ↔ dic 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"marble 是“大理石”，marine 是“海洋的”；把差异位 bl ↔ in 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“an examination consisting of a few short questions”反向定位 quiz：线索词 examination 指向“小测验”。说出中文后再完整看一遍词形；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"真实语境","text":"真实句“vocal organs”中，vocal 正在给对象贴上“嗓音的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 vocal。","basis":"usage"},{"kind":"真实语境","text":"把 intervene 放回“Why did the U.S. not intervene earlier in WW II?”：句中主语做的正是“干预”。先抓施事者与动作，再提取词形；词形用外框 int…ene 定位。","basis":"usage"},{"kind":"形近对照","text":"bride 是“新娘”，bribe 是“贿赂”；把差异位 d ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“she was exhausted by her misery and grief”做记忆证据：其中 misery 承担名词成分，核心就是“痛苦”。闭眼复述句意后再看词；回忆时保留完整短词形 misery。","basis":"usage"},{"kind":"同族挂钩","text":"instantaneous 可与 instant（立即的）放在同一词族里对照；保留共同词形，同时把 instantaneous 单独落到“瞬间的”。","basis":"family"},{"kind":"形近对照","text":"constant 是“连续不断的”，consultant 是“顾问”；把差异位 t ↔ ul 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“my hiking sticks telescope and can be put into the backpack”中直接圈出 telescope，旁注“望远镜”。句位、场景和词形三者一起回放；词形用外框 tel…ope 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“reproductive organ of angiosperm plants especially one having showy or colorful parts”反向定位 blossom：线索词 reproductive 指向“花”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"形近对照","text":"jar 是“罐子”，jaw 是“颌骨”；把差异位 r ↔ w 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"de-（向下）+ scend（攀爬）+ -ant（人）：沿家谱向下一代走的人 → descendant（后裔）。","basis":"manual"},{"kind":"真实语境","text":"真实用法“Sam cannot betray Sue”比拆假词根可靠：定位其中的动词 betray，用“泄密”复述整句；回忆时保留完整短词形 betray。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“external pressures”校准词义：external 不是孤立标签，而是在说明“外来的”的状态；词形用外框 ext…nal 定位。","basis":"usage"},{"kind":"形近对照","text":"bolt 是“插销”，belt 是“皮带”；把差异位 o ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"condense 是“压缩”，convene 是“召集”；把差异位 dens ↔ ven 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“amend the document”比拆假词根可靠：定位其中的动词 amend，用“修改”复述整句；回忆时保留完整短词形 amend。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a man who has never been married”反向定位 bachelor：线索词 married 指向“单身汉”。说出中文后再完整看一遍词形；词形用外框 bac…lor 定位。","basis":"definition"},{"kind":"形近对照","text":"proposition 是“提议”，preposition 是“介词”；把差异位 o ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 subordinate 记成“a subordinate kingdom”里的属性标签：它说明对象“隶属的”。看到相同描述位就触发这个词；词形用外框 sub…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：comet = “(astronomy) a relatively small extraterrestrial body consisting of a frozen mass that travels around the sun in a highly…”。辨识时先提取关键词 extraterrestrial，确认核心义“彗星”；回忆时保留完整短词形 comet。","basis":"definition"},{"kind":"形近对照","text":"conversion 是“转变”，concession 是“让步”；把差异位 ver ↔ ces 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词义沿革","text":"parade 最初是为展示而准备、列队检阅；队伍公开展示着前进 → parade（游行、阅兵）。","basis":"manual"},{"kind":"形近对照","text":"cultivate 是“种植”，culminate 是“以…告终”；把差异位 tiv ↔ min 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“from blank to blank a threadless way I pushed mechanic feet”中直接圈出 mechanic，旁注“技工”。句位、场景和词形三者一起回放；词形用外框 mec…nic 定位。","basis":"usage"},{"kind":"形近对照","text":"chase 是“追逐”，cease 是“停止”；把差异位 h ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"lateral 是“侧面的”，liberal 是“思想开明的”；把差异位 at ↔ ib 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形状联想","text":"stub 是短而硬的残桩；像树桩一样顶住不动的人 → stubborn（固执的）。中间双 b 要保留。","basis":"manual"},{"kind":"形近对照","text":"thrive 是“兴旺”，thrift 是“节约”；把差异位 ve ↔ ft 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a soft whitish calcite”反向定位 chalk：线索词 whitish 指向“粉笔”。说出中文后再完整看一遍词形；回忆时保留完整短词形 chalk。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 semester 定义为“one of two divisions of an academic year”。先抓定义中的 divisions，再落到中文核心“学期”；词形用外框 sem…ter 定位。","basis":"definition"},{"kind":"形近对照","text":"alert 是“机敏的”，avert 是“防止”；把差异位 l ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：album = “one or more recordings issued together; originally released on 12-inch phonograph records (usually with attractive record…”。辨识时先提取关键词 recordings，确认核心义“专辑”；回忆时保留完整短词形 album。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“the visual percept of a region”反向定位 panorama：线索词 percept 指向“全景”。说出中文后再完整看一遍词形；词形用外框 pan…ama 定位。","basis":"definition"},{"kind":"形近对照","text":"resume 是“重新开始”，regime 是“政权”；把差异位 su ↔ gi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 promising 记成“a promising young man”里的属性标签：它说明对象“有希望的”。看到相同描述位就触发这个词；词形用外框 pro…ing 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“academic protocol”中直接圈出 protocol，旁注“礼节”。句位、场景和词形三者一起回放；词形用外框 pro…col 定位。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“Sam and Sue prohibit the movie”。prohibit 在这里推动句子发生，核心动作是“禁止”；词形用外框 pro…bit 定位。","basis":"usage"},{"kind":"形近对照","text":"tropic 是“回归线”，tragic 是“悲惨的”；把差异位 op ↔ ag 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"aisle 暂无合适的例句，不编故事。用可核验定义“a long narrow passage (as in a cave or woods)”做锚点，把 passage 与“过道”成对回忆；回忆时保留完整短词形 aisle。","basis":"definition"},{"kind":"真实语境","text":"在“an ultraviolet lamp”里圈出被修饰对象，再把 ultraviolet 写成中文侧注“紫外线的”。对象＋特征一起记；词形用外框 ult…let 定位。","basis":"usage"},{"kind":"形近对照","text":"equity 是“资产净值”，enquiry 是“询问”；把差异位 quit ↔ nquir 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 liquor 定义为“an alcoholic beverage that is distilled rather than fermented”。先抓定义中的 alcoholic，再落到中文核心“烈性酒”；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"形近对照","text":"priest 是“牧师”，protest 是“抗议”；把差异位 i ↔ ot 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“the President likes to jog every morning”中直接圈出 president，旁注“总统”。句位、场景和词形三者一起回放；词形用外框 pre…ent 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“the thick short innermost digit of the forelimb”反向定位 thumb：线索词 innermost 指向“拇指”。说出中文后再完整看一遍词形；回忆时保留完整短词形 thumb。","basis":"definition"},{"kind":"真实语境","text":"真实句“slippery sidewalks”中，slippery 正在给对象贴上“滑的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 pp。","basis":"usage"},{"kind":"形近对照","text":"border 是“国界”，barber 是“理发师”；把差异位 ord ↔ arb 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“We don't segregate in this county”比拆假词根可靠：定位其中的动词 segregate，用“分开”复述整句；词形用外框 seg…ate 定位。","basis":"usage"},{"kind":"形近对照","text":"bench 是“长椅”，bunch 是“束”；把差异位 e ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"字母＋场景","text":"wreck 开头 wr- 中 w 不发音；海难后留下扭坏、不能动的残体 → wreck（残骸、毁坏）。","basis":"manual"},{"kind":"原句词源","text":"veto 在拉丁语中就是第一人称“我禁止”；掌权者说出 veto，提案立即被否决 → 否决权。","basis":"manual"},{"kind":"真实语境","text":"不要硬编词根：在“he opened the bomb bay”中直接圈出 bay，旁注“湾”。句位、场景和词形三者一起回放；回忆时保留完整短词形 bay。","basis":"usage"},{"kind":"形近对照","text":"dump 是“丢弃”，damp 是“有湿气的”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“tourism was their economic salvation”给 salvation 留的是名词位；把这个位置换成“拯救”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"形近对照","text":"pepper 是“胡椒粉”，puppet 是“木偶”；把差异位 epper ↔ uppet 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：leather = “an animal skin made smooth and flexible by removing the hair and then tanning”。辨识时先提取关键词 flexible，确认核心义“皮革”；回忆时保留完整短词形 leather。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a person who inhabits a particular place”反向定位 inhabitant：线索词 particular 指向“居民”。说出中文后再完整看一遍词形；词形用外框 inh…ant 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“the owl's faint monotonous hooting”中，monotonous 正在给对象贴上“单调乏味的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 mon…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"domain 是“领域”，detain 是“扣留”；把差异位 om ↔ et 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：wine = “fermented juice (of grapes especially)”。辨识时先提取关键词 fermented，确认核心义“葡萄酒”；回忆时保留完整短词形 wine。","basis":"definition"},{"kind":"形近对照","text":"weep 是“流泪”，weed 是“杂草”；把差异位 p ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"英美拼写","text":"grey 与 gray 都是灰色；英式常用 grey。用 E = England 记 grey 偏英式，A = America 记 gray 偏美式。","basis":"manual"},{"kind":"真实语境","text":"把 tentative 记成“just a tentative schedule”里的属性标签：它说明对象“暂定的”。看到相同描述位就触发这个词；词形用外框 ten…ive 定位。","basis":"usage"},{"kind":"拟声钩子","text":"howl 拉长读音就像狼“嗷——”地长叫；声音本身直接锁定“嗥叫、嚎叫”。","basis":"manual"},{"kind":"真实语境","text":"记一帧动作证据：“Sam cannot flatter Sue”。flatter 在这里推动句子发生，核心动作是“奉承”；词形再钉住双写 tt。","basis":"usage"},{"kind":"形近对照","text":"flaw 是“错误”，flap 是“振翅”；把差异位 w ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"brochure 暂无合适的例句，不编故事。用可核验定义“a small book usually having a paper cover”做锚点，把 usually 与“小册子”成对回忆；词形用外框 bro…ure 定位。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：bowling = “a game in which balls are rolled at an object or group of objects with the aim of knocking them over or moving them”。辨识时先提取关键词 knocking，确认核心义“保龄球”；回忆时保留完整短词形 bowling。","basis":"definition"},{"kind":"形近对照","text":"oar 是“船桨”，oak 是“栎树”；把差异位 r ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"split 是“分裂”，spit 是“吐”；把差异位 l ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 crack 放回“The glass tubes crack”：句中主语做的正是“破裂”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 crack。","basis":"usage"},{"kind":"形近对照","text":"shelf 是“架子”，shell 是“壳”；把差异位 f ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“obsolete words”校准词义：obsolete 不是孤立标签，而是在说明“已过时的”的状态；词形用外框 obs…ete 定位。","basis":"usage"},{"kind":"形近对照","text":"premium 是“保险费”，premier 是“首要的”；把差异位 um ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"dictate 暂无合适的例句，不编故事。用可核验定义“issue commands or orders for”做锚点，把 commands 与“口述”成对回忆；回忆时保留完整短词形 dictate。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：suburb = “a residential district located on the outskirts of a city”。辨识时先提取关键词 residential，确认核心义“市郊”；回忆时保留完整短词形 suburb。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a brief bikini”校准词义：brief 不是孤立标签，而是在说明“简洁的”的状态；回忆时保留完整短词形 brief。","basis":"usage"},{"kind":"真实语境","text":"真实句“a bean plot”给 plot 留的是名词位；把这个位置换成“阴谋”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 plot。","basis":"usage"},{"kind":"真实语境","text":"把 compass 固定在真实用法“within the compass of this article”里：它在句中指向“指南针”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"doze 是“瞌睡”，dose 是“一份”；把差异位 z ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“Sam and Sue gossip”做记忆证据：其中 gossip 承担名词成分，核心就是“流言蜚语”。闭眼复述句意后再看词；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"plea 是“恳求”，pea 是“豌豆”；把差异位 l ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 chronic 记成“a chronic invalid”里的属性标签：它说明对象“慢性的”。看到相同描述位就触发这个词；回忆时保留完整短词形 chronic。","basis":"usage"},{"kind":"形近对照","text":"conscientious 是“认真的”，conscious 是“意识到的”；把差异位 enti ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“rotary engine in which the kinetic energy of a moving fluid is converted into mechanical energy by causing a bladed rotor to…”反向定位 turbine：线索词 mechanical 指向“涡轮机”。说出中文后再完整看一遍词形；回忆时保留完整短词形 turbine。","basis":"definition"},{"kind":"形近对照","text":"perish 是“死亡”，punish 是“惩罚”；把差异位 er ↔ un 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"span 是“持续时间”，spin 是“快速旋转”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：brass = “an alloy of copper and zinc”。辨识时先提取关键词 copper，确认核心义“黄铜”；词形再钉住双写 ss。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“Medieval times”校准词义：medieval 不是孤立标签，而是在说明“中世纪的”的状态；词形用外框 med…val 定位。","basis":"usage"},{"kind":"形近对照","text":"tropical 是“热带的”，tropic 是“回归线”；把差异位 al ↔ tropic 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"heal 是“治愈”，heap 是“一堆”；把差异位 l ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"saucer 是“茶托”，sauce 是“酱汁”；把差异位 r ↔ sauce 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"scarce 是“缺乏的”，sauce 是“酱汁”；把差异位 car ↔ au 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"fond 是“喜爱的”，fund 是“基金”；把差异位 o ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"slap 是“掌掴”，slam 是“砰地关上”；把差异位 p ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“Sam and Sue hike”比拆假词根可靠：定位其中的动词 hike，用“远足”复述整句；回忆时保留完整短词形 hike。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“hoist the flags”。hoist 在这里推动句子发生，核心动作是“提升”；回忆时保留完整短词形 hoist。","basis":"usage"},{"kind":"形近对照","text":"hop 是“单脚跳行”，hip 是“臀部”；把差异位 o ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"复合词","text":"hence（从这里/此时）+ forth（向前）：从此刻向前的全部时间 → henceforth（从今以后）。","basis":"manual"},{"kind":"形近对照","text":"grin 是“咧嘴笑”，grim 是“严肃的”；把差异位 n ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he made a great maneuver”做记忆证据：其中 maneuver 承担名词成分，核心就是“策略”。闭眼复述句意后再看词；词形用外框 man…ver 定位。","basis":"usage"},{"kind":"形近对照","text":"burger 是“汉堡包”，barber 是“理发师”；把差异位 urg ↔ arb 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"beast 是“野兽”，blast 是“爆炸”；把差异位 e ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：dilemma = “state of uncertainty or perplexity especially as requiring a choice between equally unfavorable options”。辨识时先提取关键词 uncertainty，确认核心义“进退两难的窘境”；词形再钉住双写 mm。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“clear or deep perception of a situation”反向定位 insight：线索词 perception 指向“深刻的见解”。说出中文后再完整看一遍词形；词形再钉住辨识块 ght。","basis":"definition"},{"kind":"真实语境","text":"在真实句“Did he manipulate his foot?”里，manipulate 是正在发生的动作；把动作画面直接标成“操纵”。以后先演动作，再叫出这个词；词形用外框 man…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"fabricate 暂无合适的例句，不编故事。用可核验定义“put together out of artificial or natural components or parts”做锚点，把 artificial 与“捏造”成对回忆；词形用外框 fab…ate 定位。","basis":"definition"},{"kind":"形近对照","text":"extract 是“拔出”，extinct 是“灭绝的”；把差异位 ra ↔ in 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"ex-（向外）+ spir（呼吸）：呼出最后一口气 → 死亡；期限走到尽头也就是 expire（到期、失效）。","basis":"manual"},{"kind":"真实语境","text":"在真实句“The King will proclaim an amnesty”里，proclaim 是正在发生的动作；把动作画面直接标成“宣布”。以后先演动作，再叫出这个词；词形用外框 pro…aim 定位。","basis":"usage"},{"kind":"形近对照","text":"sheet 是“床单”，sheer 是“完全的”；把差异位 t ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：influenza = “an acute febrile highly contagious viral disease”。辨识时先提取关键词 contagious，确认核心义“流感”；词形用外框 inf…nza 定位。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“in Christianity, clergymen collectively (as distinguished from the laity)”反向定位 clergy：线索词 distinguished 指向“神职人员”。说出中文后再完整看一遍词形；回忆时保留完整短词形 clergy。","basis":"definition"},{"kind":"真实语境","text":"真实句“the habit of meditation is the basis for all real knowledge”给 meditation 留的是名词位；把这个位置换成“沉思”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"把 approve 放回“I approve of his educational policies”：句中主语做的正是“赞成”。先抓施事者与动作，再提取词形；词形再钉住双写 pp。","basis":"usage"},{"kind":"真实语境","text":"在“a spicy sauce”里圈出被修饰对象，再把 spicy 写成中文侧注“辛辣的”。对象＋特征一起记；回忆时保留完整短词形 spicy。","basis":"usage"},{"kind":"形近对照","text":"beg 是“乞讨”，bet 是“赌博”；把差异位 g ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 cargo 定义为“goods carried by a large vehicle”。先抓定义中的 carried，再落到中文核心“货物”；回忆时保留完整短词形 cargo。","basis":"definition"},{"kind":"形近对照","text":"infect 是“感染”，infant 是“幼儿”；把差异位 ec ↔ an 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“narrative poetry”中直接圈出 narrative，旁注“叙事”。句位、场景和词形三者一起回放；词形再钉住双写 rr。","basis":"usage"},{"kind":"形近对照","text":"deviate 是“偏离”，debate 是“辩论”；把差异位 vi ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“the car's momentum carried it off the road”给 momentum 留的是名词位；把这个位置换成“动力”仍说得通。先复原句中事物，再认词；词形用外框 mom…tum 定位。","basis":"usage"},{"kind":"释义锚点","text":"memorandum 暂无合适的例句，不编故事。用可核验定义“a written proposal or reminder”做锚点，把 proposal 与“备忘录”成对回忆；词形用外框 mem…dum 定位。","basis":"definition"},{"kind":"词根链","text":"de-（明确地）+ sign（标记）+ -ate：给某人或某物做上明确标记 → 指定、命名。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“give what is desired or needed, especially support, food or sustenance”反向定位 cater：线索词 sustenance 指向“提供饮食”。说出中文后再完整看一遍词形；回忆时保留完整短词形 cater。","basis":"definition"},{"kind":"真实语境","text":"在真实句“the truck gave him a tow to the garage”里，tow 是正在发生的动作；把动作画面直接标成“牵引”。以后先演动作，再叫出这个词；回忆时保留完整短词形 tow。","basis":"usage"},{"kind":"形近对照","text":"defy 是“违抗”，deny 是“否认”；把差异位 f ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：layman = “a man who is not a clergyman or a professional person”。辨识时先提取关键词 professional，确认核心义“普通信徒”；回忆时保留完整短词形 layman。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“irony is wasted on the stupid”做记忆证据：其中 irony 承担名词成分，核心就是“有讽刺意味的情况”。闭眼复述句意后再看词；回忆时保留完整短词形 irony。","basis":"usage"},{"kind":"真实语境","text":"在真实句“The buildings in Rome manifest a high level of architectural sophistication”里，manifest 是正在发生的动作；把动作画面直接标成“表明”。以后先演动作，再叫出这个词；词形用外框 man…est 定位。","basis":"usage"},{"kind":"形近对照","text":"damn 是“批评”，damp 是“有湿气的”；把差异位 n ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"advise（建议）去 e + -able（值得/可以）：值得被建议采用的做法 → advisable（明智的、可取的）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“an aircraft that has a fixed wing and is powered by propellers or jets”反向定位 aeroplane：线索词 propellers 指向“飞机”。说出中文后再完整看一遍词形；词形用外框 aer…ane 定位。","basis":"definition"},{"kind":"词根链","text":"cosm-/kosmos（宇宙、秩序）+ -ic（……的）：与宇宙有关的 → cosmic。","basis":"manual"},{"kind":"真实语境","text":"把 anchor 固定在真实用法“faith is his anchor”里：它在句中指向“锚”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 anchor。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：dinosaur = “any of numerous extinct terrestrial reptiles of the Mesozoic era”。辨识时先提取关键词 terrestrial，确认核心义“恐龙”；词形用外框 din…aur 定位。","basis":"definition"},{"kind":"形近对照","text":"bang 是“猛击”，band 是“乐队”；把差异位 g ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"barber 是“理发师”，banner 是“横幅”；把差异位 rb ↔ nn 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"battery 是“电池”，bitter 是“苦的”；把差异位 attery ↔ itter 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"linger 是“继续存留”，liner 是“游轮”；把差异位 g ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"complement 是“补充”，competent 是“胜任的”；把差异位 lem ↔ et 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"boil 是“沸腾”，bail 是“保释”；把差异位 o ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"briefcase 暂无合适的例句，不编故事。用可核验定义“a case with a handle; for carrying papers or files or books”做锚点，把 carrying 与“公文包”成对回忆；词形用外框 bri…ase 定位。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“the sun set behind the brow of distant hills”中直接圈出 brow，旁注“额头”。句位、场景和词形三者一起回放；回忆时保留完整短词形 brow。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a particular environment or walk of life”反向定位 arena：线索词 environment 指向“竞技场”。说出中文后再完整看一遍词形；回忆时保留完整短词形 arena。","basis":"definition"},{"kind":"形近对照","text":"cast 是“投”，cash 是“现金”；把差异位 t ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"castle 是“城堡”，cattle 是“牛”；把差异位 s ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源链","text":"cata-（逐项）+ log（列举、记录）：把物品逐项记录下来 → catalog（目录）。","basis":"manual"},{"kind":"形近对照","text":"cattle 是“牛”，castle 是“城堡”；把差异位 t ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"transcend 是“超出”，transient 是“短暂的”；把差异位 cend ↔ ient 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"cease 是“停止”，chase 是“追逐”；把差异位 e ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"charter 是“宪章”，cater 是“提供饮食”；把差异位 har ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“temporal processing”校准词义：temporal 不是孤立标签，而是在说明“世俗的”的状态；词形用外框 tem…ral 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“catholic in one's tastes”给 catholic 留的是名词位；把这个位置换成“天主教徒”仍说得通。先复原句中事物，再认词；词形用外框 cat…lic 定位。","basis":"usage"},{"kind":"真实语境","text":"把 circumference 固定在真实用法“he had walked the full circumference of his land”里：它在句中指向“圆周”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 cir…nce 定位。","basis":"usage"},{"kind":"真实语境","text":"在“civil strife”里圈出被修饰对象，再把 civil 写成中文侧注“公民的”。对象＋特征一起记；回忆时保留完整短词形 civil。","basis":"usage"},{"kind":"形近对照","text":"statute 是“法令”，salute 是“敬礼”；把差异位 tat ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sip 是“小口喝”，sin 是“罪”；把差异位 p ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bandage 是“绷带”，badge 是“徽章”；把差异位 nda ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“a committee is a group that keeps minutes and loses hours”中直接圈出 committee，旁注“委员会”。句位、场景和词形三者一起回放；词形再钉住双写 mm。","basis":"usage"},{"kind":"形近对照","text":"bald 是“秃的”，band 是“乐队”；把差异位 l ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 communism 定义为“a form of socialism that abolishes private ownership”。先抓定义中的 socialism，再落到中文核心“共产主义”；词形再钉住双写 mm。","basis":"definition"},{"kind":"真实语境","text":"把 ambiguous 记成“the polling had a complex and equivocal (or ambiguous) message for potential female candidates”里的属性标签：它说明对象“模棱两可的”。看到相同描述位就触发这个词；词形用外框 amb…ous 定位。","basis":"usage"},{"kind":"形近对照","text":"conscious 是“意识到的”，conscientious 是“认真的”；把差异位 o ↔ enti 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"convey 是“表达”，convene 是“召集”；把差异位 y ↔ ne 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“coordinate our efforts”里，coordinate 是正在发生的动作；把动作画面直接标成“配合”。以后先演动作，再叫出这个词；词形再钉住双写 oo。","basis":"usage"},{"kind":"真实语境","text":"把 abide 放回“Sam cannot abide Sue”：句中主语做的正是“忍受”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 abide。","basis":"usage"},{"kind":"形近对照","text":"corner 是“角”，copper 是“铜”；把差异位 rn ↔ pp 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a sudden noisy expulsion of air from the lungs that clears the air passages; a common symptom of upper respiratory infection…”反向定位 cough：线索词 respiratory 指向“咳嗽”。说出中文后再完整看一遍词形；词形再钉住辨识块 ough。","basis":"definition"},{"kind":"真实语境","text":"真实句“a criminal waste of talent”中，criminal 正在给对象贴上“犯罪的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 cri…nal 定位。","basis":"usage"},{"kind":"形近对照","text":"curse 是“诅咒”，curve 是“曲线”；把差异位 s ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：withdraw = “pull back or move away or backward”。辨识时先提取关键词 backward，确认核心义“撤回”；词形用外框 wit…raw 定位。","basis":"definition"},{"kind":"形近对照","text":"curve 是“曲线”，carve 是“雕刻”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"declare 是“宣布”，deplore 是“强烈反对”；把差异位 cla ↔ plo 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 mediate 放回“Sam and Sue mediate”：句中主语做的正是“调解”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 mediate。","basis":"usage"},{"kind":"形近对照","text":"deer 是“鹿”，deed 是“行为”；把差异位 r ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“the narrowing of the body between the ribs and hips”反向定位 waist：线索词 narrowing 指向“腰”。说出中文后再完整看一遍词形；回忆时保留完整短词形 waist。","basis":"definition"},{"kind":"形近对照","text":"definite 是“肯定的”，deficit 是“赤字”；把差异位 nite ↔ cit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"dict（说，见 dictate）+ -ation（过程）：一个人说、另一个人按所听写下 → dictation（听写）。","basis":"manual"},{"kind":"形近对照","text":"dispose 是“安排”，despise 是“轻视”；把差异位 ispo ↔ espi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ease 是“容易”，erase 是“抹去”；把差异位 a ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 victim 定义为“an unfortunate person who suffers from some adverse circumstance”。先抓定义中的 circumstance，再落到中文核心“受害者”；回忆时保留完整短词形 victim。","basis":"definition"},{"kind":"真实语境","text":"把 evoke 放回“evoke sympathy”：句中主语做的正是“唤起”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 evoke。","basis":"usage"},{"kind":"真实语境","text":"在“elementary, my dear Watson”里圈出被修饰对象，再把 elementary 写成中文侧注“最基础的”。对象＋特征一起记；词形用外框 ele…ary 定位。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“Sam cannot entertain Sue”。entertain 在这里推动句子发生，核心动作是“款待”；词形用外框 ent…ain 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“an enthusiastic response”中，enthusiastic 正在给对象贴上“热情的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 ent…tic 定位。","basis":"usage"},{"kind":"形近对照","text":"estimate 是“估计”，estate 是“庄园”；把差异位 im ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：vase = “an open jar of glass or porcelain used as an ornament or to hold flowers”。辨识时先提取关键词 porcelain，确认核心义“花瓶”；回忆时保留完整短词形 vase。","basis":"definition"},{"kind":"词族链","text":"value（价值）前加 e-、后加 -ate 构成动作：判断某事的 value → evaluate（评价、估价）。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 exclude 定义为“prevent from being included or considered or accepted”。先抓定义中的 considered，再落到中文核心“把…排斥在外”；回忆时保留完整短词形 exclude。","basis":"definition"},{"kind":"真实语境","text":"把 execute 放回“They want to execute the prisoners”：句中主语做的正是“处决”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 execute。","basis":"usage"},{"kind":"真实语境","text":"真实用法“They exhaust the money”比拆假词根可靠：定位其中的动词 exhaust，用“使精疲力竭”复述整句；回忆时保留完整短词形 exhaust。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“show an attribute, property, knowledge, or skill”反向定位 exhibit：线索词 attribute 指向“展览”。说出中文后再完整看一遍词形；回忆时保留完整短词形 exhibit。","basis":"definition"},{"kind":"真实语境","text":"在真实句“we must exploit the resources we are given wisely”里，exploit 是正在发生的动作；把动作画面直接标成“利用”。以后先演动作，再叫出这个词；回忆时保留完整短词形 exploit。","basis":"usage"},{"kind":"真实语境","text":"把 underneath 固定在真实用法“a house with a good foundation underneath”里：它在句中指向“在…下面”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 und…ath 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：farewell = “an acknowledgment or expression of goodwill at parting”。辨识时先提取关键词 acknowledgment，确认核心义“再会”；词形再钉住双写 ll。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“the use of brief expressions”反向定位 brevity：线索词 expressions 指向“简洁”。说出中文后再完整看一遍词形；回忆时保留完整短词形 brevity。","basis":"definition"},{"kind":"真实语境","text":"真实句“the tunnel reduced congestion at that intersection”给 tunnel 留的是名词位；把这个位置换成“隧道”仍说得通。先复原句中事物，再认词；词形再钉住双写 nn。","basis":"usage"},{"kind":"真实语境","text":"把 tuition 固定在真实用法“tuition and room and board were more than $25,000”里：它在句中指向“学费”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"形近对照","text":"tube 是“管子”，tub 是“浴缸”；把差异位 e ↔ tub 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“go or come after and bring or take back”反向定位 fetch：线索词 bring 指向“拿来”。说出中文后再完整看一遍词形；词形再钉住辨识块 tch。","basis":"definition"},{"kind":"形近对照","text":"flat 是“平的”，feat 是“功绩”；把差异位 l ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 freeze 放回“They freeze the money”：句中主语做的正是“冻结”。先抓施事者与动作，再提取词形；词形再钉住双写 ee。","basis":"usage"},{"kind":"真实语境","text":"真实用法“fry the pancakes”比拆假词根可靠：定位其中的动词 fry，用“油煎”复述整句；回忆时保留完整短词形 fry。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“The cars glide down the avenue”。glide 在这里推动句子发生，核心动作是“滑翔”；回忆时保留完整短词形 glide。","basis":"usage"},{"kind":"真实语境","text":"真实句“a glorious work of art”中，glorious 正在给对象贴上“辉煌的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 glo…ous 定位。","basis":"usage"},{"kind":"真实语境","text":"把 toss 放回“They toss the coin”：句中主语做的正是“扔”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"grape 是“葡萄”，graph 是“图表”；把差异位 e ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“verbal ability”校准词义：verbal 不是孤立标签，而是在说明“口头的”的状态；回忆时保留完整短词形 verbal。","basis":"usage"},{"kind":"形近对照","text":"vegetation 是“植物”，vegetarian 是“素食主义者”；把差异位 tio ↔ ria 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"同族挂钩","text":"underlying 可与 underlie（构成…的基础）放在同一词族里对照；保留共同词形，同时把 underlying 单独落到“根本的”。","basis":"family"},{"kind":"形近对照","text":"tide 是“潮汐”，tile 是“瓷砖”；把差异位 d ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"greedy 是“贪婪的”，grey 是“灰色的”；把差异位 ed ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"gum 是“口香糖”，gut 是“直觉”；把差异位 m ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 handful 固定在真实用法“only a handful of responses were received”里：它在句中指向“一把 (的量)”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 handful。","basis":"usage"},{"kind":"形近对照","text":"simulate 是“模仿”，stimulate 是“促进”；把差异位 i ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"hasty 是“匆忙的”，haste 是“匆忙”；把差异位 y ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“a biochemical profile of blood”给 profile 留的是名词位；把这个位置换成“侧面像”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 profile。","basis":"usage"},{"kind":"释义锚点","text":"presume 暂无合适的例句，不编故事。用可核验定义“take to be the case or to be true; accept without verification or proof”做锚点，把 verification 与“推测”成对回忆；回忆时保留完整短词形 presume。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“They telegraph them the information”中直接圈出 telegraph，旁注“电报”。句位、场景和词形三者一起回放；词形再钉住辨识块 ph。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“Social relations impose courtesy”。impose 在这里推动句子发生，核心动作是“强制实行”；回忆时保留完整短词形 impose。","basis":"usage"},{"kind":"真实语境","text":"真实句“a teenager's naive ignorance of life”中，naive 正在给对象贴上“无经验的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 naive。","basis":"usage"},{"kind":"真实语境","text":"把 monetary 记成“monetary rewards”里的属性标签：它说明对象“金融的”。看到相同描述位就触发这个词；词形用外框 mon…ary 定位。","basis":"usage"},{"kind":"形近对照","text":"instant 是“立即的”，infant 是“幼儿”；把差异位 st ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“suitable for use as food”反向定位 edible：线索词 suitable 指向“可食用的”。说出中文后再完整看一遍词形；回忆时保留完整短词形 edible。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 curriculum 定义为“an integrated course of academic studies”。先抓定义中的 integrated，再落到中文核心“全部课程”；词形再钉住双写 rr。","basis":"definition"},{"kind":"词根链","text":"mir- 表“惊奇、观看”（见 admire）+ -acle（事物）：让人看见后惊叹的事 → miracle（奇迹）。","basis":"manual"},{"kind":"形近对照","text":"tan 是“晒黑”，tap 是“轻拍”；把差异位 n ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“prudent rulers”校准词义：prudent 不是孤立标签，而是在说明“谨慎的”的状态；回忆时保留完整短词形 prudent。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 mist 定义为“a thin fog with condensation near the ground”。先抓定义中的 condensation，再落到中文核心“薄雾”；回忆时保留完整短词形 mist。","basis":"definition"},{"kind":"形近对照","text":"mud 是“泥”，mad 是“发疯的”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"构词链","text":"non-（没有）+ sense（意义、道理）：没有意义和道理的话 → nonsense（胡说、废话）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a thermoplastic polyamide; a family of strong resilient synthetic fibers”反向定位 nylon：线索词 thermoplastic 指向“尼龙”。说出中文后再完整看一遍词形；回忆时保留完整短词形 nylon。","basis":"definition"},{"kind":"形近对照","text":"casualty 是“伤亡人员”，casual 是“随意的”；把差异位 ty ↔ casual 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"capsule 是“胶囊”，capable 是“有才干的”；把差异位 su ↔ ab 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：overlook = “look past, fail to notice”。辨识时先提取关键词 notice，确认核心义“忽略”；词形再钉住双写 oo。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“substitute regular milk for fat-free milk”做记忆证据：其中 substitute 承担名词成分，核心就是“代替者”。闭眼复述句意后再看词；词形用外框 sub…ute 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 rectangle 定义为“a parallelogram with four right angles”。先抓定义中的 parallelogram，再落到中文核心“长方形”；词形用外框 rec…gle 定位。","basis":"definition"},{"kind":"形近对照","text":"pan 是“平底锅”，pad 是“衬垫”；把差异位 n ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"peak 是“山峰”，pea 是“豌豆”；把差异位 k ↔ pea 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“keep company with; hang out with”反向定位 affiliate：线索词 company 指向“使隶属”。说出中文后再完整看一遍词形；词形再钉住双写 ff。","basis":"definition"},{"kind":"真实语境","text":"在真实句“the relay was successful”里，relay 是正在发生的动作；把动作画面直接标成“转发”。以后先演动作，再叫出这个词；回忆时保留完整短词形 relay。","basis":"usage"},{"kind":"释义锚点","text":"kindergarten 暂无合适的例句，不编故事。用可核验定义“a preschool for children age 4 to 6 to prepare them for primary school”做锚点，把 preschool 与“幼儿园”成对回忆；词形用外框 kin…ten 定位。","basis":"definition"},{"kind":"真实语境","text":"真实用法“irrigate the wound”比拆假词根可靠：定位其中的动词 irrigate，用“灌溉”复述整句；词形再钉住双写 rr。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“the poison of fascism”做记忆证据：其中 poison 承担名词成分，核心就是“毒药”。闭眼复述句意后再看词；回忆时保留完整短词形 poison。","basis":"usage"},{"kind":"真实语境","text":"真实句“They warehouse the goods”给 warehouse 留的是名词位；把这个位置换成“仓库”仍说得通。先复原句中事物，再认词；词形用外框 war…use 定位。","basis":"usage"},{"kind":"形近对照","text":"pond 是“池塘”，pound 是“英镑”；把差异位 n ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"proposal 是“提议”，propose 是“提出”；把差异位 al ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“someone who manages property or other affairs for someone else”反向定位 steward：线索词 property 指向“乘务员”。说出中文后再完整看一遍词形；回忆时保留完整短词形 steward。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 squirrel 定义为“a kind of arboreal rodent having a long bushy tail”。先抓定义中的 arboreal，再落到中文核心“松鼠”；词形再钉住双写 rr。","basis":"definition"},{"kind":"释义锚点","text":"thesis 暂无合适的例句，不编故事。用可核验定义“an unproved statement put forward as a premise in an argument”做锚点，把 statement 与“论文”成对回忆；回忆时保留完整短词形 thesis。","basis":"definition"},{"kind":"形近对照","text":"tanker 是“油罐车”，tender 是“温柔的”；把差异位 ank ↔ end 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sphere 是“球体”，scheme 是“计划”；把差异位 pher ↔ chem 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“representative moviegoers”给 representative 留的是名词位；把这个位置换成“代表”仍说得通。先复原句中事物，再认词；词形用外框 rep…ive 定位。","basis":"usage"},{"kind":"形近对照","text":"resign 是“辞职”，reign 是“统治期”；把差异位 s ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"restrain 是“抑制”，refrain 是“克制”；把差异位 st ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“pull back or move away or backward”反向定位 retreat：线索词 backward 指向“撤退”。说出中文后再完整看一遍词形；回忆时保留完整短词形 retreat。","basis":"definition"},{"kind":"形近对照","text":"ripe 是“成熟的”，rip 是“撕裂”；把差异位 e ↔ rip 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 rival 固定在真实用法“Nothing can rival cotton for durability”里：它在句中指向“竞争者”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 rival。","basis":"usage"},{"kind":"形近对照","text":"scarf 是“围巾”，scar 是“伤疤”；把差异位 f ↔ scar 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作画面","text":"scatter 中双 t 像两股东西被向左右弹开；从集中一点散到四周 → 撒播、分散。","basis":"manual"},{"kind":"真实语境","text":"真实句“such poise is singular in one so young”中，singular 正在给对象贴上“单数的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 sin…lar 定位。","basis":"usage"},{"kind":"形近对照","text":"scream 是“尖叫”，scrap 是“碎片”；把差异位 eam ↔ ap 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“These fabrics shrink easily”比拆假词根可靠：定位其中的动词 shrink，用“收缩”复述整句；回忆时保留完整短词形 shrink。","basis":"usage"},{"kind":"形近对照","text":"shutter 是“百叶窗”，shatter 是“破碎”；把差异位 u ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“his pension gave him security in his old age”给 security 留的是名词位；把这个位置换成“安全”仍说得通。先复原句中事物，再认词；词形用外框 sec…ity 定位。","basis":"usage"},{"kind":"形近对照","text":"shame 是“羞耻”，shade 是“阴凉处”；把差异位 m ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shade 是“阴凉处”，shake 是“摇动”；把差异位 d ↔ k 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“he was held in contempt”做记忆证据：其中 contempt 承担名词成分，核心就是“轻视”。闭眼复述句意后再看词；词形用外框 con…mpt 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“cable trees”给 cable 留的是名词位；把这个位置换成“缆绳”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 cable。","basis":"usage"},{"kind":"真实语境","text":"把 grief 固定在真实用法“her death was a great grief to John”里：它在句中指向“悲伤”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 grief。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：skyscraper = “a very tall building with many stories”。辨识时先提取关键词 building，确认核心义“摩天大楼”；词形用外框 sky…per 定位。","basis":"definition"},{"kind":"形状词源","text":"corona 是“王冠”：显微镜下病毒表面的刺突像一圈冠冕，因此叫 coronavirus（冠状病毒）。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 simultaneous 定义为“occurring or operating at the same time”。先抓定义中的 occurring，再落到中文核心“同时发生的”；词形用外框 sim…ous 定位。","basis":"definition"},{"kind":"真实语境","text":"把 signify 放回“What does his strange behavior signify?”：句中主语做的正是“意味着”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 signify。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：outing = “a journey taken for pleasure”。辨识时先提取关键词 pleasure，确认核心义“郊游”；回忆时保留完整短词形 outing。","basis":"definition"},{"kind":"形近对照","text":"repression 是“镇压”，recession 是“经济衰退”；把差异位 pr ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 whatsoever 定义为“one or some or every or all without specification; entity, elective existential pronoun; quantifier, elective existential”。先抓定义中的 specification，再落到中文核心“任何”；词形用外框 wha…ver 定位。","basis":"definition"},{"kind":"形近对照","text":"snack 是“快餐”，slack 是“松弛的”；把差异位 n ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"flap 是“振翅”，flat 是“平的”；把差异位 p ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“the activity of exerting your muscles in various ways to keep fit”反向定位 workout：线索词 activity 指向“体育锻炼”。说出中文后再完整看一遍词形；回忆时保留完整短词形 workout。","basis":"definition"},{"kind":"词义沿革","text":"archive 源自希腊语表示“政府公文存放处”的词；从存放公文的地点发展为档案、档案馆。","basis":"manual"},{"kind":"真实语境","text":"把 sovereign 记成“a sovereign state”里的属性标签：它说明对象“有主权的”。看到相同描述位就触发这个词；词形用外框 sov…ign 定位。","basis":"usage"},{"kind":"复合词","text":"fire（火）+ place（地方）：室内专门生火取暖的位置 → fireplace（壁炉）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“money paid out; an amount spent”反向定位 expenditure：线索词 amount 指向“花费”。说出中文后再完整看一遍词形；词形用外框 exp…ure 定位。","basis":"definition"},{"kind":"形近对照","text":"scheme 是“计划”，sphere 是“球体”；把差异位 chem ↔ pher 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"illuminate 暂无合适的例句，不编故事。用可核验定义“introduce light into”做锚点，把 introduce 与“照亮”成对回忆；词形再钉住双写 ll。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“a prison term”中直接圈出 term，旁注“术语”。句位、场景和词形三者一起回放；回忆时保留完整短词形 term。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“rough skin”校准词义：rough 不是孤立标签，而是在说明“粗糙的”的状态；词形再钉住辨识块 ough。","basis":"usage"},{"kind":"形近对照","text":"rotate 是“旋转”，rotten 是“腐烂的”；把差异位 ate ↔ ten 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 viable 记成“viable seeds”里的属性标签：它说明对象“可行的”。看到相同描述位就触发这个词；回忆时保留完整短词形 viable。","basis":"usage"},{"kind":"真实语境","text":"真实用法“roast the turkey”比拆假词根可靠：定位其中的动词 roast，用“烤”复述整句；回忆时保留完整短词形 roast。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“the choicest or most essential or most vital part of some idea or experience”反向定位 essence：线索词 experience 指向“本质”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"形近对照","text":"immerse 是“沉浸在”，immense 是“巨大的”；把差异位 r ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"方位画面","text":"beneath 把 be- 和 neath（下方）整体看；位置被另一物覆盖在其下 → 在……下面。","basis":"manual"},{"kind":"真实语境","text":"在“solid comfort”里圈出被修饰对象，再把 solid 写成中文侧注“固体的”。对象＋特征一起记；回忆时保留完整短词形 solid。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“it changed the ecology of the island”做记忆证据：其中 ecology 承担名词成分，核心就是“生态”。闭眼复述句意后再看词；回忆时保留完整短词形 ecology。","basis":"usage"},{"kind":"形近对照","text":"setback 是“倒退”，stack 是“一叠”；把差异位 etb ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"debate 是“辩论”，debut 是“初次亮相”；把差异位 ate ↔ ut 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源链","text":"re-（再次、相应）+ sembl（相像，见 similar）：两样东西呈现相似外观 → resemble（像、类似）。","basis":"manual"},{"kind":"形近对照","text":"distract 是“使分心”，district 是“地区”；把差异位 a ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"容器词源","text":"gallon 原先就是液体容器/容量名称；把一个大壶标上 gal-lon，双 l 固定计量单位“加仑”。","basis":"manual"},{"kind":"真实语境","text":"把 suppress 放回“suppress a nascent uprising”：句中主语做的正是“镇压”。先抓施事者与动作，再提取词形；词形再钉住双写 pp。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：plaintiff = “a person who brings an action in a court of law”。辨识时先提取关键词 person，确认核心义“原告”；词形再钉住双写 ff。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“station where transport vehicles load or unload passengers or goods”反向定位 terminal：线索词 passengers 指向“终点站”。说出中文后再完整看一遍词形；词形用外框 ter…nal 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“we heard the Vienna symphony”给 symphony 留的是名词位；把这个位置换成“交响乐”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 ph。","basis":"usage"},{"kind":"释义锚点","text":"ozone 暂无合适的例句，不编故事。用可核验定义“a colorless gas (O3) soluble in alkalis and cold water; a strong oxidizing agent; can be produced by electric discharge in…”做锚点，把 colorless 与“臭氧”成对回忆；回忆时保留完整短词形 ozone。","basis":"definition"},{"kind":"形近对照","text":"synthesis 是“综合”，synthetic 是“合成的”；把差异位 sis ↔ tic 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“infectious hospital”校准词义：infectious 不是孤立标签，而是在说明“传染的”的状态；词形用外框 inf…ous 定位。","basis":"usage"},{"kind":"真实语境","text":"在真实句“They sprinkle the bread with melted butter”里，sprinkle 是正在发生的动作；把动作画面直接标成“洒”。以后先演动作，再叫出这个词；词形用外框 spr…kle 定位。","basis":"usage"},{"kind":"释义锚点","text":"trait 暂无合适的例句，不编故事。用可核验定义“a distinguishing feature of your personal nature”做锚点，把 distinguishing 与“特征”成对回忆；回忆时保留完整短词形 trait。","basis":"definition"},{"kind":"复合词","text":"there（那件事/那时）+ after（之后）：在那以后 → thereafter（此后）。","basis":"manual"},{"kind":"形近对照","text":"mentor 是“导师”，mental 是“智力的”；把差异位 or ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“crushing the blooms with regardless tread”中，regardless 修饰动作的方式或程度，落点是“不管”。先复述动作怎样发生，再认词；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"rat 是“老鼠”，rag 是“破布”；把差异位 t ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"radiate 是“辐射”，radiant 是“容光焕发的”；把差异位 te ↔ nt 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“The King only can decree”做记忆证据：其中 decree 承担名词成分，核心就是“法令”。闭眼复述句意后再看词；词形再钉住双写 ee。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 utter 定义为“without qualification; used informally as (often pejorative) intensifiers”。先抓定义中的 qualification，再落到中文核心“完全的”；词形再钉住双写 tt。","basis":"definition"},{"kind":"释义锚点","text":"verse 暂无合适的例句，不编故事。用可核验定义“literature in metrical form”做锚点，把 literature 与“诗”成对回忆；回忆时保留完整短词形 verse。","basis":"definition"},{"kind":"真实语境","text":"真实用法“Inhale deeply”比拆假词根可靠：定位其中的动词 inhale，用“吸入”复述整句；回忆时保留完整短词形 inhale。","basis":"usage"},{"kind":"词根链","text":"alt-（高，见 alto）+ -itude（程度/状态）：高度的数值或状态 → altitude（海拔、高度）。","basis":"manual"},{"kind":"真实语境","text":"真实句“I'll sell it to you retail only”给 retail 留的是名词位；把这个位置换成“零售”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 retail。","basis":"usage"},{"kind":"真实语境","text":"把 console 放回“The good news will console her”：句中主语做的正是“安慰”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 console。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“the procedure of obtaining a driver's license”中直接圈出 procedure，旁注“程序”。句位、场景和词形三者一起回放；词形用外框 pro…ure 定位。","basis":"usage"},{"kind":"原词直记","text":"ego 在拉丁语里就是“我”；把“我”放得过大就成了自我、自尊甚至自负 → ego。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 princess 定义为“a female member of a royal family other than the queen (especially the daughter of a sovereign)”。先抓定义中的 sovereign，再落到中文核心“公主”；词形再钉住双写 ss。","basis":"definition"},{"kind":"真实语境","text":"把 primitive 记成“primitive movies of the 1890s”里的属性标签：它说明对象“远古的”。看到相同描述位就触发这个词；词形用外框 pri…ive 定位。","basis":"usage"},{"kind":"真实语境","text":"真实用法“distill the essence of this compound”比拆假词根可靠：定位其中的动词 distill，用“蒸馏”复述整句；词形再钉住双写 ll。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“he put an ice pack on the injury as a precaution”做记忆证据：其中 precaution 承担名词成分，核心就是“预防措施”。闭眼复述句意后再看词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"真实句“a book not appropriate for children”中，appropriate 正在给对象贴上“适当的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 pp。","basis":"usage"},{"kind":"真实语境","text":"把 postpone 放回“let's postpone the exam”：句中主语做的正是“推迟”。先抓施事者与动作，再提取词形；词形用外框 pos…one 定位。","basis":"usage"},{"kind":"形近对照","text":"assess 是“评估”，asset 是“有价值的人或物”；把差异位 ss ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pop 是“流行音乐”，pope 是“教皇”；把差异位 pop ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ward 是“病房”，wary 是“小心的”；把差异位 d ↔ y 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 assign 放回“They assign cars to the tourists”：句中主语做的正是“分配”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“he supervised the stocking of the stream with trout”中直接圈出 stocking，旁注“长筒袜”。句位、场景和词形三者一起回放；词形用外框 sto…ing 定位。","basis":"usage"},{"kind":"形近对照","text":"stretch 是“撑大”，scratch 是“抓”；把差异位 tre ↔ cra 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“wholesome food”中，wholesome 正在给对象贴上“有益健康的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 who…ome 定位。","basis":"usage"},{"kind":"真实语境","text":"把 assignment 固定在真实用法“hazardous assignment”里：它在句中指向“任务”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 ss。","basis":"usage"},{"kind":"词族联想","text":"leaf（一片叶/一页纸）+ -let（小）：一小片可散发的纸页 → leaflet（传单、小册页）。","basis":"manual"},{"kind":"形近对照","text":"comply 是“遵从”，comedy 是“喜剧”；把差异位 pl ↔ ed 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"颜色沿革","text":"blank 与法语 blanc“白”同源：白纸上什么也没有 → blank（空白的、茫然的）。","basis":"manual"},{"kind":"真实语境","text":"把 commonplace 记成“commonplace everyday activities”里的属性标签：它说明对象“平凡的”。看到相同描述位就触发这个词；词形再钉住双写 mm。","basis":"usage"},{"kind":"形近对照","text":"breast 是“乳房”，beast 是“野兽”；把差异位 r ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“Sam and Sue picnic”做记忆证据：其中 picnic 承担名词成分，核心就是“野餐”。闭眼复述句意后再看词；回忆时保留完整短词形 picnic。","basis":"usage"},{"kind":"真实语境","text":"真实句“bright dress”中，bright 正在给对象贴上“明亮的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住辨识块 ght。","basis":"usage"},{"kind":"形近对照","text":"buffer 是“缓冲物”，burger 是“汉堡包”；把差异位 ff ↔ rg 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"lun-（月亮，见 luna）+ -ar（……的）：与月球有关的 → lunar（月球的）。","basis":"manual"},{"kind":"词义沿革","text":"commend 最初有“托付、交付照管”之意；把某人郑重托付给众人认可 → 推荐、称赞。","basis":"manual"},{"kind":"词根链","text":"pen-/paene（几乎）+ insula（岛）：几乎是岛、只有一边连着陆地 → peninsula（半岛）。","basis":"manual"},{"kind":"真实语境","text":"把 substantial 记成“the substantial world”里的属性标签：它说明对象“大量的”。看到相同描述位就触发这个词；词形用外框 sub…ial 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：cafeteria = “a restaurant where you serve yourself and pay a cashier”。辨识时先提取关键词 restaurant，确认核心义“自助餐厅”；词形用外框 caf…ria 定位。","basis":"definition"},{"kind":"形近对照","text":"campus 是“大学校园”，camp 是“营地”；把差异位 us ↔ camp 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“rectify a curve”里，rectify 是正在发生的动作；把动作画面直接标成“纠正”。以后先演动作，再叫出这个词；回忆时保留完整短词形 rectify。","basis":"usage"},{"kind":"形近对照","text":"pale 是“苍白的”，palm 是“手掌”；把差异位 e ↔ m 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"captive 是“俘虏”，capture 是“捕获”；把差异位 iv ↔ ur 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"构词链","text":"reck（在意、顾及）+ -less（不）：做事不顾后果 → reckless（鲁莽的）。","basis":"manual"},{"kind":"空间转义","text":"out + standing：从一群人中“站出来”、显得高于周围 → outstanding（杰出的）。","basis":"manual"},{"kind":"形近对照","text":"casual 是“随意的”，canal 是“运河”；把差异位 su ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"co-（共同）+ incid（发生、落到）+ -e：两件事落在同一点或同一时刻 → coincide（同时发生、相符）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“a habitual or characteristic mental attitude that determines how you will interpret and respond to situations”反向定位 outlook：线索词 characteristic 指向“世界观”。说出中文后再完整看一遍词形；词形再钉住双写 oo。","basis":"definition"},{"kind":"形近对照","text":"closet 是“储藏室”，comet 是“彗星”；把差异位 los ↔ om 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"client 是“委托人”，cement 是“水泥”；把差异位 li ↔ em 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"部位对照","text":"cheek 是脸颊，chin 是下巴：cheek 两个 ee 像左右两边鼓起的脸颊；用双眼/双颊锁住双 e。","basis":"manual"},{"kind":"形近对照","text":"bracket 是“括号”，blanket 是“毛毯”；把差异位 rac ↔ lan 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"organism 是“有机体”，organic 是“有机的”；把差异位 sm ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"migr-（移动、迁移）+ -ate（做）：从一个地区移到另一个地区 → migrate（迁徙）。","basis":"manual"},{"kind":"真实语境","text":"不要硬编词根：在“the organ of the communist party”中直接圈出 organ，旁注“器官”。句位、场景和词形三者一起回放；回忆时保留完整短词形 organ。","basis":"usage"},{"kind":"形近对照","text":"chop 是“砍”，crop 是“收成”；把差异位 h ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“a subsidy for research in artificial intelligence”给 subsidy 留的是名词位；把这个位置换成“补贴”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 subsidy。","basis":"usage"},{"kind":"形近对照","text":"oral 是“口头的”，oval 是“椭圆形的”；把差异位 r ↔ v 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“a miniature camera”中直接圈出 miniature，旁注“微型画”。句位、场景和词形三者一起回放；词形用外框 min…ure 定位。","basis":"usage"},{"kind":"真实语境","text":"记一帧动作证据：“The wooden sticks swing”。swing 在这里推动句子发生，核心动作是“摇摆”；回忆时保留完整短词形 swing。","basis":"usage"},{"kind":"词根链","text":"com-（共同、加强）+ memor（记忆）+ -ate：共同把某人某事记住 → commemorate（纪念）。","basis":"manual"},{"kind":"释义锚点","text":"navy 暂无合适的例句，不编故事。用可核验定义“an organization of military vessels belonging to a country and available for sea warfare”做锚点，把 organization 与“海军”成对回忆；回忆时保留完整短词形 navy。","basis":"definition"},{"kind":"真实语境","text":"在“naval history”里圈出被修饰对象，再把 naval 写成中文侧注“海军的”。对象＋特征一起记；回忆时保留完整短词形 naval。","basis":"usage"},{"kind":"形近对照","text":"budget 是“预算”，bucket 是“桶”；把差异位 dg ↔ ck 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“honor comes to bless the turf that wraps their clay”给 clay 留的是名词位；把这个位置换成“黏土”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 clay。","basis":"usage"},{"kind":"同族概念","text":"mood 与 mind 的古老“心智、精神状态”概念相连；某一时刻心里所处的状态 → 心情。","basis":"manual"},{"kind":"形近对照","text":"soar 是“暴涨”，scar 是“伤疤”；把差异位 o ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“an adulterous woman; a woman who has an ongoing extramarital sexual relationship with a man”反向定位 mistress：线索词 extramarital 指向“情妇”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"真实语境","text":"真实句“the climate of opinion”给 climate 留的是名词位；把这个位置换成“气候”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 climate。","basis":"usage"},{"kind":"释义锚点","text":"colonel 暂无合适的例句，不编故事。用可核验定义“a commissioned military officer in the United States Army or Air Force or Marines who ranks above a lieutenant colonel and…”做锚点，把 commissioned 与“上校”成对回忆；回忆时保留完整短词形 colonel。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“of no avail”中直接圈出 avail，旁注“益处”。句位、场景和词形三者一起回放；回忆时保留完整短词形 avail。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“grow progressively worse”反向定位 degenerate：线索词 progressively 指向“退化”。说出中文后再完整看一遍词形；词形用外框 deg…ate 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“the metric system”中，metric 正在给对象贴上“米制的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 metric。","basis":"usage"},{"kind":"释义锚点","text":"comprise 暂无合适的例句，不编故事。用可核验定义“be composed of”做锚点，把 composed 与“由…组成”成对回忆；词形用外框 com…ise 定位。","basis":"definition"},{"kind":"形近对照","text":"congress 是“代表大会”，confess 是“承认”；把差异位 gr ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"conquer 是“攻克”，conquest 是“征服”；把差异位 r ↔ st 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“Sam cannot adore Sue”里，adore 是正在发生的动作；把动作画面直接标成“爱慕”。以后先演动作，再叫出这个词；回忆时保留完整短词形 adore。","basis":"usage"},{"kind":"真实语境","text":"把 muscular 记成“a muscular boxer”里的属性标签：它说明对象“肌肉的”。看到相同描述位就触发这个词；词形用外框 mus…lar 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“the quota for Japanese imports was negotiated”中直接圈出 quota，旁注“定额”。句位、场景和词形三者一起回放；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a business firm whose articles of incorporation have been approved in some state”反向定位 corporation：线索词 incorporation 指向“公司”。说出中文后再完整看一遍词形；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 lung 定义为“either of two saclike respiratory organs in the chest of vertebrates; serves to remove carbon dioxide and provide oxygen to…”。先抓定义中的 respiratory，再落到中文核心“肺”；回忆时保留完整短词形 lung。","basis":"definition"},{"kind":"释义锚点","text":"lorry 暂无合适的例句，不编故事。用可核验定义“a large low horse-drawn wagon without sides”做锚点，把 horse-drawn 与“卡车”成对回忆；词形再钉住双写 rr。","basis":"definition"},{"kind":"航海故事","text":"船员把测速木块 log 抛入海中并把数据写进 logbook；后来 log 就从木块发展为“记录、日志”。","basis":"manual"},{"kind":"形近对照","text":"workshop 是“研讨会”，worship 是“崇拜”；把差异位 ksho ↔ shi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"critic 是“评论家”，clinic 是“诊所”；把差异位 rit ↔ lin 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"crop 是“收成”，chop 是“砍”；把差异位 r ↔ h 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“he lacked the leisure for golf”中直接圈出 leisure，旁注“休闲”。句位、场景和词形三者一起回放；回忆时保留完整短词形 leisure。","basis":"usage"},{"kind":"形近对照","text":"weed 是“杂草”，weep 是“流泪”；把差异位 d ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"场景直记","text":"lawn 专指修剪平整、供人活动的草地；想象割草机沿 lawn 留下整齐平行纹路，锁定“草坪”。","basis":"manual"},{"kind":"真实语境","text":"把 depress 放回“The bad news will depress him”：句中主语做的正是“使沮丧”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"真实语境","text":"在“a desperate cry for help”里圈出被修饰对象，再把 desperate 写成中文侧注“绝望的”。对象＋特征一起记；词形用外框 des…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“what the devil”做记忆证据：其中 devil 承担名词成分，核心就是“魔鬼”。闭眼复述句意后再看词；回忆时保留完整短词形 devil。","basis":"usage"},{"kind":"形近对照","text":"jaw 是“颌骨”，jar 是“罐子”；把差异位 w ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 dial 固定在真实用法“dial a telephone number”里：它在句中指向“刻度盘”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 dial。","basis":"usage"},{"kind":"形近对照","text":"dialog 是“对话”，dial 是“刻度盘”；把差异位 og ↔ dial 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"dia-（穿过）+ meter（测量）：穿过圆心从一边量到另一边的线 → diameter（直径）。","basis":"manual"},{"kind":"真实语境","text":"真实句“he led a small diamond”给 diamond 留的是名词位；把这个位置换成“钻石”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 diamond。","basis":"usage"},{"kind":"形近对照","text":"jewelry 是“珠宝”，jewel 是“宝石”；把差异位 ry ↔ jewel 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：inn = “a hotel providing overnight lodging for travelers”。辨识时先提取关键词 providing，确认核心义“小旅馆”；词形再钉住双写 nn。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“showed a Marxist orientation”做记忆证据：其中 orientation 承担名词成分，核心就是“方向”。闭眼复述句意后再看词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"形近对照","text":"probe 是“探查”，prone 是“易于遭受…的”；把差异位 b ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 inferior 记成“inferior alveolar artery”里的属性标签：它说明对象“级别低的”。看到相同描述位就触发这个词；词形用外框 inf…ior 定位。","basis":"usage"},{"kind":"形近对照","text":"dish 是“碟子”，disc 是“圆盘”；把差异位 h ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a traditional story accepted as history; serves to explain the world view of a people”反向定位 myth：线索词 traditional 指向“神话”。说出中文后再完整看一遍词形；回忆时保留完整短词形 myth。","basis":"definition"},{"kind":"人名单位","text":"volt 以发明电池的意大利科学家 Alessandro Volta 命名；看到 Volt-a 就锁定电压单位“伏特”。","basis":"manual"},{"kind":"真实语境","text":"把 dissolve 放回“The recipe says that we should dissolve a cup of sugar in two cups of water”：句中主语做的正是“溶解”。先抓施事者与动作，再提取词形；词形再钉住双写 ss。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：elbow = “push one's way with the elbows”。辨识时先提取关键词 elbows，确认核心义“用肘推挤”；回忆时保留完整短词形 elbow。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“Our vacations overlap”。overlap 在这里推动句子发生，核心动作是“重叠”；回忆时保留完整短词形 overlap。","basis":"usage"},{"kind":"真实语境","text":"真实句“he never knew what to do in an emergency”给 emergency 留的是名词位；把这个位置换成“紧急情况”仍说得通。先复原句中事物，再认词；词形用外框 eme…ncy 定位。","basis":"usage"},{"kind":"真实语境","text":"把 identical 记成“rows of identical houses”里的属性标签：它说明对象“完全相同的”。看到相同描述位就触发这个词；词形用外框 ide…cal 定位。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：enclose = “enclose or enfold completely with or as if with a covering”。辨识时先提取关键词 completely，确认核心义“围起”；回忆时保留完整短词形 enclose。","basis":"definition"},{"kind":"真实语境","text":"记一帧动作证据：“The fighter managed to overwhelm his opponent”。overwhelm 在这里推动句子发生，核心动作是“使不知所措”；词形用外框 ove…elm 定位。","basis":"usage"},{"kind":"词族画面","text":"vertical 与 vertex（顶点）同族：从脚下直指头顶最高点的方向 → 垂直的。","basis":"manual"},{"kind":"构词链","text":"en-（使拥有）+ title（头衔、权利）：给某人一个名分或资格 → entitle（使有权、给标题）。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：holy = “belonging to or derived from or associated with a divine power”。辨识时先提取关键词 associated，确认核心义“神圣的”；回忆时保留完整短词形 holy。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a wish that was equivalent to a command”校准词义：equivalent 不是孤立标签，而是在说明“等同的”的状态；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"真实语境","text":"真实句“a valid argument”中，valid 正在给对象贴上“有效的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 valid。","basis":"usage"},{"kind":"真实语境","text":"把 exact 记成“an exact mind”里的属性标签：它说明对象“精确的”。看到相同描述位就触发这个词；回忆时保留完整短词形 exact。","basis":"usage"},{"kind":"真实语境","text":"在真实用法“presumably, he missed the train”里删掉 presumably 再补回：缺少的正是“推测起来”这一语气或方式；词形用外框 pre…bly 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“he wore his national costume”做记忆证据：其中 costume 承担名词成分，核心就是“戏服”。闭眼复述句意后再看词；回忆时保留完整短词形 costume。","basis":"usage"},{"kind":"真实语境","text":"真实句“the word for a pedal extremity is ‘foot’”给 pedal 留的是名词位；把这个位置换成“踏板”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 pedal。","basis":"usage"},{"kind":"真实语境","text":"把 prescription 固定在真实用法“a prescription drug”里：它在句中指向“处方”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：savage = “(of persons or their actions) able or disposed to inflict pain or suffering”。辨识时先提取关键词 suffering，确认核心义“凶恶的”；回忆时保留完整短词形 savage。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“one of the inherent cognitive or perceptual powers of the mind”反向定位 faculty：线索词 perceptual 指向“天赋”。说出中文后再完整看一遍词形；回忆时保留完整短词形 faculty。","basis":"definition"},{"kind":"真实语境","text":"在真实句“The coins twinkle”里，twinkle 是正在发生的动作；把动作画面直接标成“闪耀”。以后先演动作，再叫出这个词；回忆时保留完整短词形 twinkle。","basis":"usage"},{"kind":"释义锚点","text":"fertilizer 暂无合适的例句，不编故事。用可核验定义“any substance such as manure or a mixture of nitrates used to make soil more fertile”做锚点，把 substance 与“肥料 - =<英>fertiliser”成对回忆；词形用外框 fer…zer 定位。","basis":"definition"},{"kind":"形近对照","text":"truck 是“卡车”，trunk 是“树干”；把差异位 c ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"awe 是“敬畏”，ape 是“猿”；把差异位 w ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tense 是“紧张的”，tease 是“戏弄”；把差异位 n ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"混成构词","text":"transistor 由 transfer（传递）+ resistor（电阻器）组合命名：控制并传递电信号的器件 → 晶体管。","basis":"manual"},{"kind":"形状画面","text":"frog 短而有弹性；把 fr- 当蹲伏前腿、-og 当鼓起的身体，整只青蛙一下跳出 → 蛙。此条是形状联想，不是词源。","basis":"manual"},{"kind":"动作对照","text":"glance 是目光轻轻擦过，不是停下来 stare；想象眼睛只扫过 gl- 的一道亮光 → 一瞥。","basis":"manual"},{"kind":"真实语境","text":"真实句“They guarantee them the money”给 guarantee 留的是名词位；把这个位置换成“保证”仍说得通。先复原句中事物，再认词；词形再钉住双写 ee。","basis":"usage"},{"kind":"真实语境","text":"把 testimony 固定在真实用法“his effort was testimony to his devotion”里：它在句中指向“证词”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 tes…ony 定位。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“heat therapy gave the best relief”中直接圈出 therapy，旁注“疗法”。句位、场景和词形三者一起回放；回忆时保留完整短词形 therapy。","basis":"usage"},{"kind":"形近对照","text":"throat 是“咽喉”，thrift 是“节约”；把差异位 oa ↔ if 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"toilet 是“抽水马桶”，tablet 是“平板电脑”；把差异位 oi ↔ ab 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"vegetarian 是“素食主义者”，vegetation 是“植物”；把差异位 ria ↔ tio 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源圆环","text":"tour 与 turn 同源，最早带有“转一圈”的概念：绕一圈参观再回来 → 旅行、游览。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“a tough character”校准词义：tough 不是孤立标签，而是在说明“艰苦的”的状态；词形再钉住辨识块 ough。","basis":"usage"},{"kind":"形近对照","text":"gramme 是“克 - =<美>gram”，grape 是“葡萄”；把差异位 mm ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 outer 记成“outer reality”里的属性标签：它说明对象“外表的”。看到相同描述位就触发这个词；回忆时保留完整短词形 outer。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：highway = “a major road for any form of motor transport”。辨识时先提取关键词 transport，确认核心义“公路”；回忆时保留完整短词形 highway。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“(law) the findings of a jury on issues of fact submitted to it for decision; can be used in formulating a judgment”反向定位 verdict：线索词 formulating 指向“裁决”。说出中文后再完整看一遍词形；回忆时保留完整短词形 verdict。","basis":"definition"},{"kind":"形近对照","text":"tongue 是“舌头”，tangle 是“缠结的一团”；把差异位 ongu ↔ angl 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"ponder 是“沉思”，pond 是“池塘”；把差异位 er ↔ pond 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：guest = “a visitor to whom hospitality is extended”。辨识时先提取关键词 hospitality，确认核心义“客人”；回忆时保留完整短词形 guest。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a wheeled vehicle with large wheels; used in farming and other applications”反向定位 tractor：线索词 applications 指向“拖拉机”。说出中文后再完整看一遍词形；回忆时保留完整短词形 tractor。","basis":"definition"},{"kind":"形近对照","text":"guilty 是“犯罪的”，guild 是“协会”；把差异位 ty ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 gulf 固定在真实用法“he felt a gulf between himself and his former friends”里：它在句中指向“海湾”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 gulf。","basis":"usage"},{"kind":"真实语境","text":"在“formal dress”里圈出被修饰对象，再把 formal 写成中文侧注“正式的”。对象＋特征一起记；回忆时保留完整短词形 formal。","basis":"usage"},{"kind":"词义沿革","text":"asset 来自古法语 assez“足够”；足以偿还债务的东西就是可用财产 → asset（资产、有价值的人或物）。","basis":"manual"},{"kind":"真实语境","text":"真实句“the fluid motion of a cat”给 fluid 留的是名词位；把这个位置换成“流体”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 fluid。","basis":"usage"},{"kind":"真实语境","text":"把 hammer 固定在真实用法“hammer the metal flat”里：它在句中指向“锤子”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 mm。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“a sample for ten days free trial”中直接圈出 trial，旁注“审讯”。句位、场景和词形三者一起回放；回忆时保留完整短词形 trial。","basis":"usage"},{"kind":"形近对照","text":"filter 是“筛选”，fiber 是“纤维”；把差异位 lt ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"pre-（在前）+ domin（主人、支配）+ -ant：像主人一样处在前面并支配全局 → predominant（占主导的、显著的）。","basis":"manual"},{"kind":"真实语境","text":"把 temptation 固定在真实用法“he felt the temptation and his will power weakened”里：它在句中指向“诱惑”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"形近对照","text":"feast 是“盛宴”，feat 是“功绩”；把差异位 s ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a square piece of cloth used for wiping the eyes or nose or as a costume accessory”反向定位 handkerchief：线索词 accessory 指向“手帕”。说出中文后再完整看一遍词形；词形用外框 han…ief 定位。","basis":"definition"},{"kind":"动作画面","text":"twist 的 tw- 提醒“两股”：把两股线相互绕转就会扭紧 → twist（扭、使弯曲）。此条是构形联想。","basis":"manual"},{"kind":"真实语境","text":"把 fancy 放回“Sam cannot fancy Sue”：句中主语做的正是“想要”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 fancy。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：harmony = “compatibility in opinion and action”。辨识时先提取关键词 compatibility，确认核心义“和谐”；回忆时保留完整短词形 harmony。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“extreme cold”校准词义：extreme 不是孤立标签，而是在说明“极度的”的状态；回忆时保留完整短词形 extreme。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 conspiracy 定义为“a secret agreement between two or more people to perform an unlawful act”。先抓定义中的 agreement，再落到中文核心“密谋”；词形用外框 con…acy 定位。","basis":"definition"},{"kind":"真实语境","text":"把 urge 放回“Sam cannot urge Sue”：句中主语做的正是“敦促”。先抓施事者与动作，再提取词形；回忆时保留完整短词形 urge。","basis":"usage"},{"kind":"形近对照","text":"heel 是“脚后跟”，heal 是“治愈”；把差异位 e ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“utmost contempt”校准词义：utmost 不是孤立标签，而是在说明“最大的”的状态；回忆时保留完整短词形 utmost。","basis":"usage"},{"kind":"真实语境","text":"真实句“their descriptions of human behavior become vague, dull, and unclear”中，vague 正在给对象贴上“模糊的”这一特征。先想被描述的对象，再恢复形容词；回忆时保留完整短词形 vague。","basis":"usage"},{"kind":"真实语境","text":"把 publicity 固定在真实用法“the publicity of the court room”里：它在句中指向“宣传”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 pub…ity 定位。","basis":"usage"},{"kind":"形近对照","text":"vain 是“徒劳的”，vein 是“静脉”；把差异位 a ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“Sam and Sue examine the movie”。examine 在这里推动句子发生，核心动作是“审查”；回忆时保留完整短词形 examine。","basis":"usage"},{"kind":"真实语境","text":"真实句“trash these old chairs”给 trash 留的是名词位；把这个位置换成“垃圾”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 trash。","basis":"usage"},{"kind":"真实语境","text":"把 hint 固定在真实用法“a hint mockery in her manner”里：它在句中指向“暗示”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 hint。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：parachute = “rescue equipment consisting of a device that fills with air and retards your fall”。辨识时先提取关键词 consisting，确认核心义“降落伞”；词形用外框 par…ute 定位。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“his car has a lot of pickup”做记忆证据：其中 pickup 承担名词成分，核心就是“改善”。闭眼复述句意后再看词；回忆时保留完整短词形 pickup。","basis":"usage"},{"kind":"形近对照","text":"equality 是“平等”，equity 是“资产净值”；把差异位 al ↔ i 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 horn 固定在真实用法“the horn of an anvil”里：它在句中指向“喇叭”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 horn。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“It was a good Christian household”中直接圈出 household，旁注“家庭”。句位、场景和词形三者一起回放；词形用外框 hou…old 定位。","basis":"usage"},{"kind":"形近对照","text":"outfit 是“全套服装”，outset 是“开始”；把差异位 fi ↔ se 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在真实句“What does this move entail?”里，entail 是正在发生的动作；把动作画面直接标成“牵涉”。以后先演动作，再叫出这个词；回忆时保留完整短词形 entail。","basis":"usage"},{"kind":"真实语境","text":"把 energy 固定在真实用法“he plays tennis with great energy”里：它在句中指向“活力”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 energy。","basis":"usage"},{"kind":"真实语境","text":"在“a poem or essay may be typical of its period in idea or ideal content”里圈出被修饰对象，再把 ideal 写成中文侧注“理想的”。对象＋特征一起记；回忆时保留完整短词形 ideal。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“obstruction of justice”做记忆证据：其中 obstruction 承担名词成分，核心就是“阻挡”。闭眼复述句意后再看词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"真实句“oriental civilization”中，oriental 正在给对象贴上“东方的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 ori…tal 定位。","basis":"usage"},{"kind":"形近对照","text":"immense 是“巨大的”，immerse 是“沉浸在”；把差异位 n ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：nutrition = “(physiology) the organic process of nourishing or being nourished; the processes by which an organism assimilates food and…”。辨识时先提取关键词 assimilates，确认核心义“营养”；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“exotic cuisine”校准词义：exotic 不是孤立标签，而是在说明“外来的”的状态；回忆时保留完整短词形 exotic。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 vitamin 定义为“any of a group of organic substances essential in small quantities to normal metabolism”。先抓定义中的 substances，再落到中文核心“维生素”；回忆时保留完整短词形 vitamin。","basis":"definition"},{"kind":"真实语境","text":"把 drunk 记成“drunk with excitement”里的属性标签：它说明对象“醉酒的”。看到相同描述位就触发这个词；回忆时保留完整短词形 drunk。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：technique = “a practical method or art applied to some particular task”。辨识时先提取关键词 particular，确认核心义“技艺”；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“national independence takes priority over class struggle”做记忆证据：其中 priority 承担名词成分，核心就是“优先考虑的事”。闭眼复述句意后再看词；词形用外框 pri…ity 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“the inevitable result”中，inevitable 正在给对象贴上“必然发生的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 ine…ble 定位。","basis":"usage"},{"kind":"真实语境","text":"把 discharge 放回“discharge liquids”：句中主语做的正是“允许离开”。先抓施事者与动作，再提取词形；词形用外框 dis…rge 定位。","basis":"usage"},{"kind":"真实语境","text":"在“infinite wealth”里圈出被修饰对象，再把 infinite 写成中文侧注“无限的”。对象＋特征一起记；词形用外框 inf…ite 定位。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a daily written record of (usually personal) experiences and observations”反向定位 diary：线索词 observations 指向“日记”。说出中文后再完整看一遍词形；回忆时保留完整短词形 diary。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 projector 定义为“an optical device for projecting a beam of light”。先抓定义中的 projecting，再落到中文核心“放映机”；词形用外框 pro…tor 定位。","basis":"definition"},{"kind":"真实语境","text":"把 insult 固定在真实用法“Sam cannot insult Sue”里：它在句中指向“侮辱”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 insult。","basis":"usage"},{"kind":"形近对照","text":"interval 是“间隔”，integral 是“必需的”；把差异位 rv ↔ gr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“The chemist managed to isolate the compound”。isolate 在这里推动句子发生，核心动作是“使隔离”；回忆时保留完整短词形 isolate。","basis":"usage"},{"kind":"真实语境","text":"真实句“in the morning the grass was wet with dew”给 dew 留的是名词位；把这个位置换成“露水”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 dew。","basis":"usage"},{"kind":"真实语境","text":"把 joint 记成“joint owners”里的属性标签：它说明对象“联合的”。看到相同描述位就触发这个词；回忆时保留完整短词形 joint。","basis":"usage"},{"kind":"形近对照","text":"detail 是“细节”，detain 是“扣留”；把差异位 l ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“They want to judge the prisoners”。judge 在这里推动句子发生，核心动作是“评价”；词形再钉住辨识块 dge。","basis":"usage"},{"kind":"复合词","text":"land（房产）+ lady（女士）：拥有并出租房屋的女性 → landlady（女房东）。","basis":"manual"},{"kind":"真实语境","text":"把 democratic 记成“a democratic country”里的属性标签：它说明对象“民主的”。看到相同描述位就触发这个词；词形用外框 dem…tic 定位。","basis":"usage"},{"kind":"真实语境","text":"在“a legitimate government”里圈出被修饰对象，再把 legitimate 写成中文侧注“合法的”。对象＋特征一起记；词形用外框 leg…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“the volume of exports”做记忆证据：其中 volume 承担名词成分，核心就是“体积”。闭眼复述句意后再看词；回忆时保留完整短词形 volume。","basis":"usage"},{"kind":"真实语境","text":"在真实句“Wake old feelings of hatred”里，wake 是正在发生的动作；把动作画面直接标成“醒来”。以后先演动作，再叫出这个词；回忆时保留完整短词形 wake。","basis":"usage"},{"kind":"形近对照","text":"league 是“联盟”，lease 是“租约”；把差异位 gu ↔ s 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词源短语","text":"whisky 来自盖尔语 uisge beatha“生命之水”；把烈酒当作 water of life，锁定威士忌。美式常写 whiskey。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“despite anything to the contrary (usually preceding a concession)”反向定位 notwithstanding：线索词 concession 指向“虽然”。说出中文后再完整看一遍词形；词形用外框 not…ing 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“The bad news will outrage him”给 outrage 留的是名词位；把这个位置换成“愤怒”仍说得通。先复原句中事物，再认词；回忆时保留完整短词形 outrage。","basis":"usage"},{"kind":"词根链","text":"noti-（知道，见 notice）+ -fy（使成为）：使对方知道 → notify（通知）。","basis":"manual"},{"kind":"形近对照","text":"liberal 是“思想开明的”，lateral 是“侧面的”；把差异位 ib ↔ at 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"erase 是“抹去”，ease 是“容易”；把差异位 r ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 notable 定义为“widely known and esteemed”。先抓定义中的 esteemed，再落到中文核心“值得注意的”；回忆时保留完整短词形 notable。","basis":"definition"},{"kind":"真实语境","text":"把 cream 固定在真实用法“Cream the butter”里：它在句中指向“奶油”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 cream。","basis":"usage"},{"kind":"形近对照","text":"county 是“郡”，counter 是“反驳”；把差异位 y ↔ er 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"counter 是“反驳”，cluster 是“群聚”；把差异位 oun ↔ lus 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"council 是“议会”，counsel 是“律师”；把差异位 ci ↔ se 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"短语词源","text":"endeavor 来自 put oneself in devoir“使自己尽到责任”：全力去完成应做之事 → 努力、尽力。","basis":"manual"},{"kind":"形近对照","text":"tax 是“对…征税”，tan 是“晒黑”；把差异位 x ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"worship 是“崇拜”，workshop 是“研讨会”；把差异位 shi ↔ ksho 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“he was charged with being accessory to the crime”给 accessory 留的是名词位；把这个位置换成“附件”仍说得通。先复原句中事物，再认词；词形再钉住双写 cc。","basis":"usage"},{"kind":"形近对照","text":"mad 是“发疯的”，mud 是“泥”；把差异位 a ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"maid 是“女仆”，mad 是“发疯的”；把差异位 i ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作画面","text":"hinge 是门绕着转动的连接点；把中间 in 想成轴销插进去，门便能开合 → 铰链。","basis":"manual"},{"kind":"真实语境","text":"在真实句“The men construct the bookshelves”里，construct 是正在发生的动作；把动作画面直接标成“建造”。以后先演动作，再叫出这个词；词形用外框 con…uct 定位。","basis":"usage"},{"kind":"释义锚点","text":"mayor 暂无合适的例句，不编故事。用可核验定义“the head of a city government”做锚点，把 government 与“市长”成对回忆；回忆时保留完整短词形 mayor。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：melon = “any of numerous fruits of the gourd family having a hard rind and sweet juicy flesh”。辨识时先提取关键词 numerous，确认核心义“瓜”；回忆时保留完整短词形 melon。","basis":"definition"},{"kind":"形近对照","text":"refund 是“退款”，refine 是“精炼”；把差异位 und ↔ ine 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"mental 是“智力的”，metal 是“金属”；把差异位 n ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"confess 是“承认”，congress 是“代表大会”；把差异位 f ↔ gr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"concert 是“音乐会”，conceal 是“隐瞒”；把差异位 rt ↔ al 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“become worse or disintegrate”反向定位 deteriorate：线索词 disintegrate 指向“恶化”。说出中文后再完整看一遍词形；词形用外框 det…ate 定位。","basis":"definition"},{"kind":"真实语境","text":"真实句“the composition is written in four movements”给 composition 留的是名词位；把这个位置换成“组成方式”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"真实语境","text":"把 task 固定在真实用法“the endless task of classifying the samples”里：它在句中指向“工作”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 task。","basis":"usage"},{"kind":"真实语境","text":"真实用法“boys in mock battle”比拆假词根可靠：定位其中的动词 mock，用“嘲笑”复述整句；回忆时保留完整短词形 mock。","basis":"usage"},{"kind":"形近对照","text":"commit 是“投入”，cosmic 是“宇宙的”；把差异位 mmit ↔ smic 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“commercial TV”中，commercial 正在给对象贴上“商业的”这一特征。先想被描述的对象，再恢复形容词；词形再钉住双写 mm。","basis":"usage"},{"kind":"真实语境","text":"把 bearing 固定在真实用法“those issues have no bearing on our situation”里：它在句中指向“影响”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 bearing。","basis":"usage"},{"kind":"形近对照","text":"tap 是“轻拍”，tan 是“晒黑”；把差异位 p ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“Can you quantify your results?”。quantify 在这里推动句子发生，核心动作是“量化”；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"形近对照","text":"consultant 是“顾问”，constant 是“连续不断的”；把差异位 ul ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"tail 是“尾巴”，toil 是“苦工”；把差异位 a ↔ o 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bid 是“出价”，bind 是“捆绑”；把差异位 d ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"记一帧动作证据：“multiply 10 by 15”。multiply 在这里推动句子发生，核心动作是“乘”；词形用外框 mul…ply 定位。","basis":"usage"},{"kind":"形近对照","text":"radical 是“根本的”，racial 是“种族的”；把差异位 dic ↔ ci 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"church 是“教堂”，clutch 是“紧握”；把差异位 hur ↔ lut 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"sweat 是“汗水”，swear 是“发誓”；把差异位 t ↔ r 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"人名构词","text":"Christ + -ian（追随者/相关的人）：追随基督的人 → Christian（基督徒、基督教的）。","basis":"manual"},{"kind":"真实语境","text":"真实句“a superficial mind”中，superficial 正在给对象贴上“肤浅的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 sup…ial 定位。","basis":"usage"},{"kind":"形近对照","text":"organic 是“有机的”，organism 是“有机体”；把差异位 c ↔ sm 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：chess = “weedy annual native to Europe but widely distributed as a weed especially in wheat”。辨识时先提取关键词 distributed，确认核心义“国际象棋”；词形再钉住双写 ss。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“a blunt instrument”校准词义：blunt 不是孤立标签，而是在说明“率直的”的状态；回忆时保留完整短词形 blunt。","basis":"usage"},{"kind":"真实语境","text":"在真实句“Sam and Sue cherish the movie”里，cherish 是正在发生的动作；把动作画面直接标成“珍爱”。以后先演动作，再叫出这个词；回忆时保留完整短词形 cherish。","basis":"usage"},{"kind":"真实语境","text":"把 overthrow 固定在真实用法“she was unprepared for this sudden overthrow of their normal way of living”里：它在句中指向“推翻”这一事物。下次先找名词位置，再由场景提取词义；词形用外框 ove…row 定位。","basis":"usage"},{"kind":"形近对照","text":"plead 是“恳求”，plea 是“恳求”；把差异位 d ↔ plea 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“the priest sank to his knees in prayer”做记忆证据：其中 prayer 承担名词成分，核心就是“祈祷”。闭眼复述句意后再看词；回忆时保留完整短词形 prayer。","basis":"usage"},{"kind":"形近对照","text":"axe 是“斧”，ape 是“猿”；把差异位 x ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"outset 是“开始”，outfit 是“全套服装”；把差异位 se ↔ fi 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"comedy 是“喜剧”，comply 是“遵从”；把差异位 ed ↔ pl 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"maiden 是“少女”，maid 是“女仆”；把差异位 en ↔ maid 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"cash 是“现金”，cast 是“投”；把差异位 h ↔ t 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"capture 是“捕获”，capsule 是“胶囊”；把差异位 tur ↔ sul 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实用法“These cars won't overtake”比拆假词根可靠：定位其中的动词 overtake，用“超过”复述整句；词形用外框 ove…ake 定位。","basis":"usage"},{"kind":"形近对照","text":"cancer 是“癌症”，canoe 是“独木舟”；把差异位 cer ↔ oe 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"commence 是“开始发生”，commend 是“公开称赞”；把差异位 ce ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"aluminum 暂无合适的例句，不编故事。用可核验定义“a silvery ductile metallic element found primarily in bauxite”做锚点，把 primarily 与“铝 - =<英>aluminium”成对回忆；词形用外框 alu…num 定位。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“the whole camp laughed at his mistake”中直接圈出 camp，旁注“营地”。句位、场景和词形三者一起回放；回忆时保留完整短词形 camp。","basis":"usage"},{"kind":"形近对照","text":"pardon 是“抱歉”，patron 是“赞助人”；把差异位 rd ↔ tr 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shall 是“将要”，shell 是“壳”；把差异位 a ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 bundle 固定在真实用法“she made a bundle selling real estate”里：它在句中指向“捆”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 bundle。","basis":"usage"},{"kind":"形近对照","text":"agenda 是“议题”，amend 是“修改”；把差异位 genda ↔ mend 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“an exile who flees for safety”反向定位 refugee：线索词 safety 指向“难民”。说出中文后再完整看一遍词形；词形再钉住双写 ee。","basis":"definition"},{"kind":"真实语境","text":"真实句“phase a withdrawal”给 phase 留的是名词位；把这个位置换成“时期”仍说得通。先复原句中事物，再认词；词形再钉住辨识块 ph。","basis":"usage"},{"kind":"释义锚点","text":"broad 暂无合适的例句，不编故事。用可核验定义“having great (or a certain) extent from one side to the other”做锚点，把 certain 与“宽阔的”成对回忆；回忆时保留完整短词形 broad。","basis":"definition"},{"kind":"释义锚点","text":"记定义而不乱拆词：phenomenon = “any state or process known through the senses rather than by intuition or reasoning”。辨识时先提取关键词 intuition，确认核心义“现象”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“an essential structural component of living cells and source of energy for animals; includes simple sugars with small…”反向定位 carbohydrate：线索词 structural 指向“碳水化合物”。说出中文后再完整看一遍词形；词形用外框 car…ate 定位。","basis":"definition"},{"kind":"形近对照","text":"pill 是“药丸”，pile 是“摞”；把差异位 l ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bounce 是“弹跳”，bound 是“必然的”；把差异位 ce ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词族链","text":"remain（留下）+ -der（名词结果）：其余部分拿走后仍留下的东西 → remainder（剩余物）。","basis":"manual"},{"kind":"释义锚点","text":"用英文定义“give a benediction to”反向定位 bless：线索词 benediction 指向“祝福”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"词根链","text":"sub-（在下）+ marine（海洋的）：在海面下航行的船 → submarine（潜水艇）。","basis":"manual"},{"kind":"形近对照","text":"blame 是“把…归咎于”，blaze 是“火焰”；把差异位 m ↔ z 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"bet 是“赌博”，beg 是“乞讨”；把差异位 t ↔ g 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"pipe 是“管道”，pile 是“摞”；把差异位 p ↔ l 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 liability 定义为“the state of being legally obliged and responsible”。先抓定义中的 responsible，再落到中文核心“责任”；词形用外框 lia…ity 定位。","basis":"definition"},{"kind":"形近对照","text":"pity 是“怜悯”，pit 是“洞”；把差异位 y ↔ pit 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“an award for bravery”中直接圈出 award，旁注“奖金”。句位、场景和词形三者一起回放；回忆时保留完整短词形 award。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“the aggregation of a country's military aircraft”反向定位 aviation：线索词 aggregation 指向“航空”。说出中文后再完整看一遍词形；词形再钉住辨识块 tion。","basis":"definition"},{"kind":"形近对照","text":"pleasant 是“令人愉快的”，peasant 是“农民”；把差异位 l ↔ e 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"stick 是“刺”，stack 是“一叠”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：visa = “an endorsement made in a passport that allows the bearer to enter the country issuing it”。辨识时先提取关键词 endorsement，确认核心义“签证”；回忆时保留完整短词形 visa。","basis":"definition"},{"kind":"词根链","text":"con-（共同）+ fid（信任，见 fidelity）+ -ential：只在彼此信任者之间传递 → confidential（机密的）。","basis":"manual"},{"kind":"词根直记","text":"graph- 表“写、画、记录”；把数据画成可读的线条 → graph（图表）。","basis":"manual"},{"kind":"形近对照","text":"premier 是“首要的”，premium 是“保险费”；把差异位 er ↔ um 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"在“gave applicable examples to support her argument”里圈出被修饰对象，再把 applicable 写成中文侧注“适当的”。对象＋特征一起记；词形再钉住双写 pp。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“a device or control that is very useful for a particular job”反向定位 appliance：线索词 particular 指向“家用电器”。说出中文后再完整看一遍词形；词形再钉住双写 pp。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 prior 定义为“earlier in time”。先抓定义中的 earlier，再落到中文核心“先前的”；回忆时保留完整短词形 prior。","basis":"definition"},{"kind":"真实语境","text":"把 procession 固定在真实用法“the doctrine of the procession of the Holy Spirit from the Father and the Son”里：它在句中指向“行列”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 ss。","basis":"usage"},{"kind":"形近对照","text":"trivial 是“琐碎的”，trial 是“审讯”；把差异位 vi ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a solid bounded by a cylindrical surface and two parallel planes (the bases)”反向定位 cylinder：线索词 cylindrical 指向“圆柱体”。说出中文后再完整看一遍词形；词形用外框 cyl…der 定位。","basis":"definition"},{"kind":"形近对照","text":"jog 是“慢跑”，jug 是“壶”；把差异位 o ↔ u 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 admission 固定在真实用法“the surgery was performed on his second admission to the clinic”里：它在句中指向“准入”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住双写 ss。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：genre = “a kind of literary or artistic work”。辨识时先提取关键词 literary，确认核心义“体裁”；回忆时保留完整短词形 genre。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“a unit of area (4840 square yards) used in English-speaking countries”反向定位 acre：线索词 english-speaking 指向“英亩”。说出中文后再完整看一遍词形；回忆时保留完整短词形 acre。","basis":"definition"},{"kind":"真实语境","text":"真实句“she acted accordingly”中，accordingly 修饰动作的方式或程度，落点是“因此”。先复述动作怎样发生，再认词；词形再钉住双写 cc。","basis":"usage"},{"kind":"释义锚点","text":"accord 暂无合适的例句，不编故事。用可核验定义“go together”做锚点，把 together 与“赋予”成对回忆；词形再钉住双写 cc。","basis":"definition"},{"kind":"真实语境","text":"不要硬编词根：在“his declaration of innocence”中直接圈出 declaration，旁注“宣布”。句位、场景和词形三者一起回放；词形再钉住辨识块 tion。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“communication between individuals”反向定位 intercourse：线索词 communication 指向“性交”。说出中文后再完整看一遍词形；词形用外框 int…rse 定位。","basis":"definition"},{"kind":"形近对照","text":"purple 是“紫色的”，pursue 是“追求”；把差异位 pl ↔ su 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"diffuse 暂无合适的例句，不编故事。用可核验定义“move outward”做锚点，把 outward 与“传播”成对回忆；词形再钉住双写 ff。","basis":"definition"},{"kind":"形近对照","text":"pursue 是“追求”，purple 是“紫色的”；把差异位 su ↔ pl 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"用英文定义“a United States liquid unit equal to 32 fluid ounces; four quarts equal one gallon”反向定位 quart：线索词 united 指向“夸脱”。说出中文后再完整看一遍词形；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 queue 定义为“a line of people or vehicles waiting for something”。先抓定义中的 vehicles，再落到中文核心“行列”；词形再钉住辨识块 qu。","basis":"definition"},{"kind":"释义锚点","text":"layoff 暂无合适的例句，不编故事。用可核验定义“the act of laying off an employee or a work force”做锚点，把 employee 与“解雇”成对回忆；词形再钉住双写 ff。","basis":"definition"},{"kind":"真实语境","text":"在“innumerable difficulties”里圈出被修饰对象，再把 innumerable 写成中文侧注“数不清的”。对象＋特征一起记；词形再钉住双写 nn。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“he made a deliberate decision not to respond negatively”校准词义：deliberate 不是孤立标签，而是在说明“故意的”的状态；词形用外框 del…ate 定位。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 biography 定义为“an account of the series of events making up a person's life”。先抓定义中的 account，再落到中文核心“传记”；词形再钉住辨识块 ph。","basis":"definition"},{"kind":"形近对照","text":"detach 是“拆卸”，detail 是“细节”；把差异位 ch ↔ il 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"squeeze 是“挤压”，sneeze 是“打喷嚏”；把差异位 qu ↔ n 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"region 是“区域”，reckon 是“认为”；把差异位 gi ↔ ck 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"真实句“militant nations”中，militant 正在给对象贴上“好战的”这一特征。先想被描述的对象，再恢复形容词；词形用外框 mil…ant 定位。","basis":"usage"},{"kind":"形近对照","text":"remedy 是“解决方法”，recede 是“渐渐远去”；把差异位 medy ↔ cede 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"记定义而不乱拆词：directory = “an alphabetical list of names and addresses”。辨识时先提取关键词 alphabetical，确认核心义“目录”；词形用外框 dir…ory 定位。","basis":"definition"},{"kind":"释义锚点","text":"用英文定义“an irrational motive for performing trivial or repetitive actions, even against your will”反向定位 obsession：线索词 irrational 指向“痴迷”。说出中文后再完整看一遍词形；词形再钉住双写 ss。","basis":"definition"},{"kind":"释义锚点","text":"Open English WordNet 把 symptom 定义为“(medicine) any sensation or change in bodily function that is experienced by a patient and is associated with a particular…”。先抓定义中的 experienced，再落到中文核心“症状”；回忆时保留完整短词形 symptom。","basis":"definition"},{"kind":"场景双义","text":"rent 作名词是定期交出的“租金”；作动词是付钱换取暂时使用。用“每月交钱换钥匙”统一两义。","basis":"manual"},{"kind":"释义锚点","text":"记定义而不乱拆词：surplus = “a quantity much larger than is needed”。辨识时先提取关键词 quantity，确认核心义“过剩”；回忆时保留完整短词形 surplus。","basis":"definition"},{"kind":"真实语境","text":"用真实语境“panel the walls with wood”做记忆证据：其中 panel 承担名词成分，核心就是“专题讨论小组”。闭眼复述句意后再看词；回忆时保留完整短词形 panel。","basis":"usage"},{"kind":"原义直记","text":"古英语 pal 就是“桩、杆、柱”；词形演变为 pole，核心物体没有改变 → 杆子。不要和大写 Pole（波兰人）混。","basis":"manual"},{"kind":"词族链","text":"practice（实践、从业）变为 practit- + -ioner（从事者）：实际从事某专业的人 → practitioner。","basis":"manual"},{"kind":"形近对照","text":"prose 是“散文”，probe 是“探查”；把差异位 s ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"persist 是“坚持”，perish 是“死亡”；把差异位 sist ↔ ish 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"induce 是“导致”，indulge 是“沉溺于”；把差异位 c ↔ lg 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 specialize 放回“specialize one's research”：句中主语做的正是“专门研究”。先抓施事者与动作，再提取词形；词形用外框 spe…ize 定位。","basis":"usage"},{"kind":"词根链","text":"re-（再次）+ naissance（出生）：文化与艺术再次出生 → Renaissance（文艺复兴）。","basis":"manual"},{"kind":"真实语境","text":"用真实语境“words of reproach”做记忆证据：其中 reproach 承担名词成分，核心就是“责备”。闭眼复述句意后再看词；词形用外框 rep…ach 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“they managed somehow”中，somehow 修饰动作的方式或程度，落点是“以某种方式”。先复述动作怎样发生，再认词；回忆时保留完整短词形 somehow。","basis":"usage"},{"kind":"真实语境","text":"把 alien 固定在真实用法“an economic theory alien to the spirit of capitalism”里：它在句中指向“外国人”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 alien。","basis":"usage"},{"kind":"释义锚点","text":"记定义而不乱拆词：drawback = “the quality of being a hindrance”。辨识时先提取关键词 hindrance，确认核心义“缺点”；词形用外框 dra…ack 定位。","basis":"definition"},{"kind":"形近对照","text":"resist 是“抵抗”，relish 是“享受”；把差异位 sist ↔ lish 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"动作转义","text":"band 最初是把东西束在一起的带子；一群乐手也像被一条带子绑成一个整体 → 乐队。","basis":"manual"},{"kind":"真实语境","text":"把 soluble 记成“the puzzle is soluble”里的属性标签：它说明对象“可溶的”。看到相同描述位就触发这个词；回忆时保留完整短词形 soluble。","basis":"usage"},{"kind":"词根链","text":"sens-（感觉）+ -ation（过程/结果）：感官受到刺激后产生的体验 → sensation（感觉、轰动）。","basis":"manual"},{"kind":"燃烧画面","text":"ash 只有三个字母，像火焰熄灭后只剩轻短的一撮；burn → ash（灰烬）。用完整短词直连场景。","basis":"manual"},{"kind":"释义锚点","text":"Open English WordNet 把 enroll 定义为“register formally as a participant or member”。先抓定义中的 participant，再落到中文核心“登记”；词形再钉住双写 ll。","basis":"definition"},{"kind":"真实语境","text":"把 annoy 放回“The bad news will annoy him”：句中主语做的正是“使心烦”。先抓施事者与动作，再提取词形；词形再钉住双写 nn。","basis":"usage"},{"kind":"真实语境","text":"真实用法“Sam cannot amuse Sue”比拆假词根可靠：定位其中的动词 amuse，用“逗笑”复述整句；回忆时保留完整短词形 amuse。","basis":"usage"},{"kind":"词义统一","text":"implement 的核心是“使计划充实并完成”：动词是实施，名词是完成工作所用的工具；用“落实”统一两义。","basis":"manual"},{"kind":"同族挂钩","text":"adventure 可与 venture（冒险去）放在同一词族里对照；保留共同词形，同时把 adventure 单独落到“冒险”。","basis":"family"},{"kind":"形近对照","text":"stride 是“大步走”，strife 是“冲突”；把差异位 d ↔ f 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"soil 是“土壤”，spoil 是“使人或事物变坏”；把差异位 o ↔ p 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"rose 是“玫瑰花”，robe 是“长袍”；把差异位 s ↔ b 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"释义锚点","text":"Open English WordNet 把 underlie 定义为“be or form the base for”。先抓定义中的 form，再落到中文核心“构成…的基础”；词形用外框 und…lie 定位。","basis":"definition"},{"kind":"形近对照","text":"slip 是“从原位滑脱”，slap 是“掌掴”；把差异位 i ↔ a 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"不要硬编词根：在“a slave to fashion”中直接圈出 slave，旁注“奴隶”。句位、场景和词形三者一起回放；回忆时保留完整短词形 slave。","basis":"usage"},{"kind":"真实语境","text":"用真实语境“a silly idea”校准词义：silly 不是孤立标签，而是在说明“愚蠢的”的状态；词形再钉住双写 ll。","basis":"usage"},{"kind":"释义锚点","text":"Open English WordNet 把 finite 定义为“bounded or limited in magnitude or spatial or temporal extent”。先抓定义中的 magnitude，再落到中文核心“有限的”；回忆时保留完整短词形 finite。","basis":"definition"},{"kind":"真实语境","text":"把 lease 固定在真实用法“They lease cars to the tourists”里：它在句中指向“租约”这一事物。下次先找名词位置，再由场景提取词义；回忆时保留完整短词形 lease。","basis":"usage"},{"kind":"真实语境","text":"在“spacious skies”里圈出被修饰对象，再把 spacious 写成中文侧注“广阔的”。对象＋特征一起记；词形用外框 spa…ous 定位。","basis":"usage"},{"kind":"词根链","text":"equ-（相等）+ -ator（起作用者/线）：把地球分成相等南北两半的线 → equator（赤道）。","basis":"manual"},{"kind":"形近对照","text":"distinct 是“清晰的”，distract 是“使分心”；把差异位 in ↔ ra 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"把 secondary 记成“a secondary issue”里的属性标签：它说明对象“次要的”。看到相同描述位就触发这个词；词形用外框 sec…ary 定位。","basis":"usage"},{"kind":"形近对照","text":"shout 是“大声说”，scout 是“侦察”；把差异位 h ↔ c 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"词根链","text":"sen-（年老，见 senate）+ -ior（比较级）：年龄或资历更高的 → senior（年长的、资深的）。","basis":"manual"},{"kind":"真实语境","text":"在真实句“Did he formulate his major works over a short period of time?”里，formulate 是正在发生的动作；把动作画面直接标成“制定计划”。以后先演动作，再叫出这个词；词形用外框 for…ate 定位。","basis":"usage"},{"kind":"真实语境","text":"把 sequence 固定在真实用法“he played the trumps in sequence”里：它在句中指向“一系列”这一事物。下次先找名词位置，再由场景提取词义；词形再钉住辨识块 qu。","basis":"usage"},{"kind":"真实语境","text":"不要硬编词根：在“a gossip session”中直接圈出 session，旁注“一段时间”。句位、场景和词形三者一起回放；词形再钉住双写 ss。","basis":"usage"},{"kind":"释义锚点","text":"用英文定义“cause to be attached”反向定位 attach：线索词 attached 指向“系牢”。说出中文后再完整看一遍词形；词形再钉住双写 tt。","basis":"definition"},{"kind":"真实语境","text":"在真实句“Grab the elevator door!”里，grab 是正在发生的动作；把动作画面直接标成“抓住”。以后先演动作，再叫出这个词；回忆时保留完整短词形 grab。","basis":"usage"},{"kind":"形近对照","text":"severe 是“严重的”，sphere 是“球体”；把差异位 ev ↔ ph 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"形近对照","text":"shake 是“摇动”，shade 是“阴凉处”；把差异位 k ↔ d 当成判别开关，先判义再落字母。","basis":"confusion"},{"kind":"真实语境","text":"用真实语境“the bare skeleton of a novel”做记忆证据：其中 skeleton 承担名词成分，核心就是“骨骼”。闭眼复述句意后再看词；词形用外框 ske…ton 定位。","basis":"usage"},{"kind":"真实语境","text":"真实句“he had a sharp crease in his trousers”给 trousers 留的是名词位；把这个位置换成“裤子”仍说得通。先复原句中事物，再认词；词形用外框 tro…ers 定位。","basis":"usage"}];
